insert into public.chunks (id, episode_id, cms_item_id, chunk_index, content, token_estimate, speakers, start_timestamp, end_timestamp, podcast_index, episode_name, slug, web_url, guest_name, guest_title, categories, short_description, podcast_length)
select id, episode_id, cms_item_id, chunk_index, content, token_estimate, speakers, start_timestamp, end_timestamp, podcast_index, episode_name, slug, web_url, guest_name, guest_title, categories, short_description, podcast_length
from jsonb_to_recordset($jsonpayload$
[{"id": "3d222ea3-1baf-41cf-b1e8-7754dfd65880", "episode_id": "1e32aa47-8f7f-4b63-9bdd-4e65200e4830", "cms_item_id": "68225dfc7bb476527f8c483e", "chunk_index": 12, "content": "Eric Rosen (21:56): I think that it helps our mission because it helps us stay in business. (22:01): But yeah, no, I think that when I say household name, that household could be in Colorado or that household could be in Mali. I think that for us, it's about growing the recognition and awareness of our brand because positive word of mouth, the growing recall helps scale in terms of, at the end of the day when we talk about impact, we talk about how many people we're reaching. And so the more people who know about us, the more people who know about us. It's sort of a somewhat empty tautology, but that's what we need. I think that another part of it, which we can save this one for another day, but BioLite believes in this future that is shared by all of us and is built in renewables. And so there's actually an education piece that comes with familiarizing and engaging with BioLite, which is understanding why are renewables important, why should we get off of fossil fuels? And so I would say that becoming a household name isn't just about our dollar and cents success at BioLite. It means that energy is also becoming a part of everyday conversation. And right now, I think that we're starting to see that happen more often, but in the eight years that we have been in business, I think talking about energy has gone from being this kind of pretty esoteric concept to becoming more and more tangible.\n\nCole Heilborn (23:35): Yeah. Do you think brands can become a household name without a strong why you guys have,\n\nEric Rosen (23:44): I mean, you do anything if you have enough money? I am serious. I think that if you've got enough investors and enough cash to burn, sure you can do anything. I think that that could be hot and fast. I think what we're trying to do is build a future that is authentic. And so for us that why is going to really help us build that staying power.", "token_estimate": 474, "speakers": ["Eric Rosen", "Cole Heilborn"], "start_timestamp": "21:56", "end_timestamp": "23:44", "podcast_index": 27, "episode_name": "Ep 27: Erica Rosen | One Watt at a Time | BioLit‪e‬", "slug": "ep-27-erica-rosen-one-watt-at-a-time-biolite", "web_url": "https://www.portsidepro.com/podcast-feed/ep-27-erica-rosen-one-watt-at-a-time-biolite", "guest_name": null, "guest_title": null, "categories": [], "short_description": "\"A brand is a way to build trust and measure permission.\"", "podcast_length": "44:49"}, {"id": "fcba8fcf-f32d-4dce-88fd-ae8d9926d912", "episode_id": "1e32aa47-8f7f-4b63-9bdd-4e65200e4830", "cms_item_id": "68225dfc7bb476527f8c483e", "chunk_index": 13, "content": "Cole Heilborn (24:13): Yeah. I, and you guys have probably noticed this, I would categorize you in this category, but there's a few brands that are popping up that are making a name for themselves that are working towards things like you guys are working towards social good. Why are we seeing these brands like yours popping up now?\n\nEric Rosen (24:37): Yeah, it's a good question. I think there are a few answers. I'm trying to figure out which one to pick, but I think one is customers. Now, regardless of what kind of marketing speak age group you're in, whether you're a millennial or a millennial or whatever you want to call it, I think a lot of customers now, regardless of whatever bracket they're in, are understanding that they can vote with their wallet. They can make choices about where their money goes and how they can consume. That is not the super optimistic rallying cry. I think that it's not that people are consuming less. I think it's just that there are more options to consume a little bit differently and hopefully with an eye on a slightly more responsible and sustainable future. And I think that we are not seeing necessarily solutions being played out by governments or really large corporations or other institutions. And so what you're seeing is this cropping up of brands who believe that there's a way to do business differently. And so you see that with the B Corp movement. You see that with the climate neutral certification where you're trying to create these collections and collectives of brands that represent billions of dollars of business that believe we can do things differently. And I think that it's a reaction to the change not coming from anywhere else.\n\nSpeaker 3 (26:19): And\n\nEric Rosen (26:19): So you end up with a series of brands who roll up their sleeves and they're like, all right, well, we'll do it ourselves.", "token_estimate": 468, "speakers": ["Cole Heilborn", "Eric Rosen", "Speaker 3"], "start_timestamp": "24:13", "end_timestamp": "26:19", "podcast_index": 27, "episode_name": "Ep 27: Erica Rosen | One Watt at a Time | BioLit‪e‬", "slug": "ep-27-erica-rosen-one-watt-at-a-time-biolite", "web_url": "https://www.portsidepro.com/podcast-feed/ep-27-erica-rosen-one-watt-at-a-time-biolite", "guest_name": null, "guest_title": null, "categories": [], "short_description": "\"A brand is a way to build trust and measure permission.\"", "podcast_length": "44:49"}, {"id": "db3c7eb4-d451-4322-9b4d-145c05bf1cbc", "episode_id": "1e32aa47-8f7f-4b63-9bdd-4e65200e4830", "cms_item_id": "68225dfc7bb476527f8c483e", "chunk_index": 14, "content": "Cole Heilborn (26:24): Yeah, that's funny you mentioned that because just yesterday I did in the interview with Austin over at Climate Neutral, and he says something very similar in his episode will be coming out the week before yours. So if folks want to learn more about that question, they should go watch that episode because it's all about social good and what brands are doing on the personal level. For people out there, founders who are maybe just starting a company and they've discovered what you guys discovered eight years ago, this product or this service that could help a ton of people, and they're charging down this road of wanting to become a social brand that's doing good. As someone who's been doing it for some time now, what should they consider? What tips would you pass along?\n\nEric Rosen (27:10): Yeah, I think that I would say one of the most important things is thinking about how you actually want to structure your business. So I think that one thing we didn't get really into in this interview is about social enterprise versus cause marketing. So is impact the business of your business or is impact something that is part of your corporate social responsibility? Or is it something that it'ss a part of your business, but it's at the end of the day, it's not the widget you make, if that makes\n\nSpeaker 3 (27:42): Sense.", "token_estimate": 339, "speakers": ["Cole Heilborn", "Eric Rosen", "Speaker 3"], "start_timestamp": "26:24", "end_timestamp": "27:42", "podcast_index": 27, "episode_name": "Ep 27: Erica Rosen | One Watt at a Time | BioLit‪e‬", "slug": "ep-27-erica-rosen-one-watt-at-a-time-biolite", "web_url": "https://www.portsidepro.com/podcast-feed/ep-27-erica-rosen-one-watt-at-a-time-biolite", "guest_name": null, "guest_title": null, "categories": [], "short_description": "\"A brand is a way to build trust and measure permission.\"", "podcast_length": "44:49"}, {"id": "fd4c32c7-d91c-4675-ade4-4e3243a347a1", "episode_id": "1e32aa47-8f7f-4b63-9bdd-4e65200e4830", "cms_item_id": "68225dfc7bb476527f8c483e", "chunk_index": 15, "content": "Eric Rosen (27:43): And I think that the good news is there's room for both. It's not that it's like, ah, cause marketing is a total fraud, get out of here. No, there are good examples and bad examples of both of them, but I do think that it's really important for a founder to ask themselves, is this the core of what I do every day and I'm going to build an entire infrastructure around it, or is it a pillar inside of my business, but I need to recognize that to keep the lights on and to keep the engine going. My business looks a little bit different. And so yeah, I think that that's something that's really important because I think that if you need to figure that out early on, A, because you need to make sure that your resources are put in the right place, and I think it's a very fair and hard question that you have to ask yourself. And B, I think that back to your point about the why needs to be as authentic as possible. And if you go around claiming that you're a social enterprise, but you've really only built infrastructure to have it be a CSR statement, you're going to get smoked out pretty quickly.\n\nCole Heilborn (28:56): Yeah. Okay. That's great. So if people want to learn more about the problems you guys are trying to solve, if they want to support what you guys are trying to do, is the easiest way just to buy one of your products or are there other resources that they can connect with?", "token_estimate": 354, "speakers": ["Eric Rosen", "Cole Heilborn"], "start_timestamp": "27:43", "end_timestamp": "28:56", "podcast_index": 27, "episode_name": "Ep 27: Erica Rosen | One Watt at a Time | BioLit‪e‬", "slug": "ep-27-erica-rosen-one-watt-at-a-time-biolite", "web_url": "https://www.portsidepro.com/podcast-feed/ep-27-erica-rosen-one-watt-at-a-time-biolite", "guest_name": null, "guest_title": null, "categories": [], "short_description": "\"A brand is a way to build trust and measure permission.\"", "podcast_length": "44:49"}, {"id": "6f50948a-f944-43f0-bddd-ca92c84fb3c6", "episode_id": "1e32aa47-8f7f-4b63-9bdd-4e65200e4830", "cms_item_id": "68225dfc7bb476527f8c483e", "chunk_index": 16, "content": "Eric Rosen (29:10): Yeah, I mean, check us out on light energy.com. That's B-I-O-L-I-T-E, that's how we spell our name. And you can see stuff about our mission there. You can check out our products. I would say that two other options are we have a really, really strong presence on Instagram, so we're just on Instagram. And so we've got great stories of our r and d team, our emerging markets, our ambassadors. So that's just a great way to just get caught up on BioLite. And then the last thing I would offer is both on our website and on our YouTube page, we actually have a short doc series called Connecting the wats, and it is three mini docs that are four minutes each that really dive into the work that we do and really root it in stories of individuals so that you understand when we talk about energy access, the kind of cascade of impact that it can create.\n\nCole Heilborn (30:02): Wow. Okay. Perfect. So if you're listening and interested, go watch those three videos. That's what I'm going to go do right now. Erica, thank you so much. I know what everything you guys are working on is, I mean, it's a worldwide challenge, and I appreciate you breaking it down and contextualizing it and talking about it in a digestible way. So thank you.\n\nEric Rosen (30:24): Yeah, thanks for having me here. I really appreciate it.\n\nCole Heilborn (30:26): Yeah, no problem. Well, have a good rest of your day and we'll chat later.\n\nEric Rosen (30:29): All right, sounds good.\n\nCole Heilborn (30:31): Thank you for listening to this episode of the Backcountry Marketing Podcast. If you enjoyed today's episode or learned something new, please consider leaving us a review on Apple or sharing this with a friend.", "token_estimate": 428, "speakers": ["Eric Rosen", "Cole Heilborn"], "start_timestamp": "29:10", "end_timestamp": "30:31", "podcast_index": 27, "episode_name": "Ep 27: Erica Rosen | One Watt at a Time | BioLit‪e‬", "slug": "ep-27-erica-rosen-one-watt-at-a-time-biolite", "web_url": "https://www.portsidepro.com/podcast-feed/ep-27-erica-rosen-one-watt-at-a-time-biolite", "guest_name": null, "guest_title": null, "categories": [], "short_description": "\"A brand is a way to build trust and measure permission.\"", "podcast_length": "44:49"}, {"id": "e00541b3-2a94-44d7-aaf5-aac1730ddecd", "episode_id": "e185c522-8c27-4a79-a92d-f221919c5eab", "cms_item_id": "68225dfc7bb476527f8c4840", "chunk_index": 0, "content": "Adam Vicarel (00:02): Welcome to the Backcountry Marketing Podcast. My name is Cole Helebo and I'll be your host today. This podcast dives deep with leaders of the outdoor marketing industry as they discuss the gritty details of their work, personal challenges and latest adventures, whether you're standing in the lift line, shuttling the fresh loam, or cracking a local beer. I hope you enjoyed today's episode. This is the Backcountry Marketing Podcast. This episode is produced by Portside Productions, an outdoor, commercial, and film production company based in the Pacific Northwest. Let's make waves. Welcome to the Backcountry Marketing Podcast. Today I'm sitting down with Adam Rell, the creative director at Vicar Rell Studios. Adam, how are you?\n\nCole Heilborn (00:49): I'm doing well, man. Thanks so much for having me today.\n\nAdam Vicarel (00:52): Thanks for being here. Where are you joining us from today?\n\nCole Heilborn (00:55): Today I am in my studio in Denver, Colorado. I'm currently with the weirdness of COVID. Depending if someone's listened to this in a couple months, I'm definitely splitting time pretty evenly between the home office and the studio office, which I'm slowly trickling back into.\n\nAdam Vicarel (01:09): Yep, yep. Well, I feel like you're not alone there. Well, quick shout out to Brenna for connecting us. You guys share an office, is that right?\n\nCole Heilborn (01:18): Yeah, exactly. Yeah. I actually met Brenna a couple years ago through a project where her company basically hired me and myself and a few other buddies who were in this space, kind of reeled her in and she's a badass. Yeah,", "token_estimate": 410, "speakers": ["Adam Vicarel", "Cole Heilborn"], "start_timestamp": "00:02", "end_timestamp": "01:18", "podcast_index": 28, "episode_name": "Ep 28: Adam Vicarel | Art and Business | Vicarel Studio‪s‬", "slug": "ep-28-adam-vicarel-art-and-business-vicarel-studios", "web_url": "https://www.portsidepro.com/podcast-feed/ep-28-adam-vicarel-art-and-business-vicarel-studios", "guest_name": "Adam Vicarel", "guest_title": "Vicarel Studios", "categories": [], "short_description": "\"I think like a designer, but I execute like a fine artist.\"", "podcast_length": "44:50"}, {"id": "3bc995d9-fd98-4a63-8539-6d148e51e705", "episode_id": "e185c522-8c27-4a79-a92d-f221919c5eab", "cms_item_id": "68225dfc7bb476527f8c4840", "chunk_index": 1, "content": "Adam Vicarel (01:32): She, she was on the podcast a few episodes ago. You should check it out. We talked all about production and how production is changing, not just because of COVID, but the relationship between big agencies and small agencies. And so it was a great time chatting with her, but I'm really excited to chat with you today. I think we've got something really interesting to chat about, something that I'm really personally interested in, and I'm hoping you can, I'm just curious to hear your thoughts. But before we jump into that, why don't you tell us a little bit about your background? Tell us a little bit about your company. What do you do?", "token_estimate": 166, "speakers": ["Adam Vicarel"], "start_timestamp": "01:32", "end_timestamp": "01:32", "podcast_index": 28, "episode_name": "Ep 28: Adam Vicarel | Art and Business | Vicarel Studio‪s‬", "slug": "ep-28-adam-vicarel-art-and-business-vicarel-studios", "web_url": "https://www.portsidepro.com/podcast-feed/ep-28-adam-vicarel-art-and-business-vicarel-studios", "guest_name": "Adam Vicarel", "guest_title": "Vicarel Studios", "categories": [], "short_description": "\"I think like a designer, but I execute like a fine artist.\"", "podcast_length": "44:50"}, {"id": "93f2ac05-c7dc-4aa7-b9e3-da308e49a100", "episode_id": "e185c522-8c27-4a79-a92d-f221919c5eab", "cms_item_id": "68225dfc7bb476527f8c4840", "chunk_index": 2, "content": "Cole Heilborn (02:05): Yeah, so my background is I have basically a degree in graphic design. Prior to getting that degree in college, I fell in love with painting. So I've always kind of grappled, at least early on in my career with am I an artist or am I a designer? The two starkly different things in the sense that design solves problems and art is intended to make people think, and or art is more of an interpretation of an artist's emotions or feelings or perceptions. And then design solves problems. That's maybe better said. And so I always kind of grappled with what am I? And over the years as a designer, I fell into hand lettering, which is literally just drawing words for lack of a better explanation. And as I started doing that more and more, I really fell in love with the artful nature of hand lettering, but how it's applied in a design sense. (02:58): So over the last couple of years, I've been working for myself about six years now, and just the beginning of this year, beginning of 2020, I rebranded my studio as a hybrid creative studio that specializes in the artful implementation of strategic design. So the idea is that I think and execute, or I think like a designer, but I execute a fine artist. And so what that enables me to do is bring a kind of unprecedented level of approachability or that cool factor to the work that I'm creating, but while still really being cognizant of the target demographic and who is the competition, what's the point of difference of this company? So it enables me to kind of tiptoe that line of, this is cool for cool's sake, or this is cool because it speaks to me because I am that target audience.\n\nAdam Vicarel (03:49): Right. And it also, it works. What you're doing is solving a problem.\n\nCole Heilborn (03:54): Exactly. That's\n\nAdam Vicarel (03:54): Neat. That's really cool. And I haven't heard that distinction before between art and design. Dive a little deeper into that. Explain your thinking there.", "token_estimate": 495, "speakers": ["Cole Heilborn", "Adam Vicarel"], "start_timestamp": "02:05", "end_timestamp": "03:54", "podcast_index": 28, "episode_name": "Ep 28: Adam Vicarel | Art and Business | Vicarel Studio‪s‬", "slug": "ep-28-adam-vicarel-art-and-business-vicarel-studios", "web_url": "https://www.portsidepro.com/podcast-feed/ep-28-adam-vicarel-art-and-business-vicarel-studios", "guest_name": "Adam Vicarel", "guest_title": "Vicarel Studios", "categories": [], "short_description": "\"I think like a designer, but I execute like a fine artist.\"", "podcast_length": "44:50"}, {"id": "1759a135-6f57-4836-836a-b3c29efb7cf1", "episode_id": "e185c522-8c27-4a79-a92d-f221919c5eab", "cms_item_id": "68225dfc7bb476527f8c4840", "chunk_index": 3, "content": "Cole Heilborn (04:03): Yeah, so, and it's funny, in college, one of my teachers said at some point, I feel like going into college, nobody really identifies as a designer. Anybody who's going into graphic design was good at drawing or good at painting or something in high school, and they were interested in the commercial application of design. So they pursue that in college. So at some point, one of my teachers said, you guys are all identifying as artists, but at some point you will start to identify as a designer, and when someone calls you an artist, it will almost repulse you. And I forget exactly how he phrased it, but basically he was saying, you're not an artist, you're a designer. And I remember everyone in the class was like, ah, yes, John, you're right. And I remember sitting there being like, I don't know if I agree with this. (04:53): And so since then I've always kind of, as I said, been grappling with what am I? And in reading a few articles and reading up on the definitions or the basis of art versus design frequently, maybe we'll look at a painter as an example, Picasso, his works really are, they're like a metaphor for something. So it's his perception of society or how he thinks the government works or something like that. And he's really pumping his emotions and thoughts and feelings into it. So every piece of art is a visceral interpretation of that artist's emotions. And the design, I forget who said it, it was some famous architect said, form follows function. So in the world of design, everything is created to solve a problem or to serve a purpose. So everything you make does something intentional. So as a graphic designer, everything I do, I'm considering why if I choose the Sam Serif versus a Crif, why did I do that? If I choose blue versus green, why did I do that? So I think they're starkly different in some ways, but at the same time, they do have a lot of overlap. So it's like a fun little thing I'm always playing with.", "token_estimate": 496, "speakers": ["Cole Heilborn"], "start_timestamp": "04:03", "end_timestamp": "04:03", "podcast_index": 28, "episode_name": "Ep 28: Adam Vicarel | Art and Business | Vicarel Studio‪s‬", "slug": "ep-28-adam-vicarel-art-and-business-vicarel-studios", "web_url": "https://www.portsidepro.com/podcast-feed/ep-28-adam-vicarel-art-and-business-vicarel-studios", "guest_name": "Adam Vicarel", "guest_title": "Vicarel Studios", "categories": [], "short_description": "\"I think like a designer, but I execute like a fine artist.\"", "podcast_length": "44:50"}, {"id": "998faf23-c6ba-4a23-9425-81dba99bd629", "episode_id": "e185c522-8c27-4a79-a92d-f221919c5eab", "cms_item_id": "68225dfc7bb476527f8c4840", "chunk_index": 4, "content": "Adam Vicarel (06:12): And that's got to be fun too for the education process with your clients, figuring out helping them navigate that as well. Maybe what would provide a little bit more context also for this is if you could share a little bit about some of who your clients are and what you've done for them in the past, I think that will also help as we continue down this conversation.\n\nCole Heilborn (06:29): Absolutely. Yeah. So I would say the bulk of what I do is branding and identity design. So a lot of just helping position businesses within their respective markets. So I'll do everything from logo design to selecting type systems, color palettes, and then coming up with the overarching art direction for, again, how they position themselves, their products or their services in the world. So I would say that's the majority of what I do. And then we'll call that 50%, and then I do 25% murals and 25% hand lettering. So I paint murals on interior and exterior of businesses. Murals is really where I lean into that art design hybridity, where some clients just want something cool and I can do that. Other clients want something that has a little bit more connection to their brand standards or their mission statement. And because of my background, I'm able to lean into that as well. (07:25): And then the lettering, which again is literally just drawing words fancy, that is used for packaging design ad campaigns. I use it in my murals, in my branding apparel design. It has tons and tons of application. So I think that's actually why I fell in love with hand lettering is because it's such a versatile art form that it's like no two days or no two projects are the same. Some days I'm just drawing on paper with a pen. Other days I am doing a stop motion video, two very different applications of the same art, and I really love that versatility of it.\n\nAdam Vicarel (08:04): Yeah. Okay. So would you say that there, let me think this through. Would you say that all design is art, but not all art is design? Is that an accurate statement?", "token_estimate": 516, "speakers": ["Adam Vicarel", "Cole Heilborn"], "start_timestamp": "06:12", "end_timestamp": "08:04", "podcast_index": 28, "episode_name": "Ep 28: Adam Vicarel | Art and Business | Vicarel Studio‪s‬", "slug": "ep-28-adam-vicarel-art-and-business-vicarel-studios", "web_url": "https://www.portsidepro.com/podcast-feed/ep-28-adam-vicarel-art-and-business-vicarel-studios", "guest_name": "Adam Vicarel", "guest_title": "Vicarel Studios", "categories": [], "short_description": "\"I think like a designer, but I execute like a fine artist.\"", "podcast_length": "44:50"}, {"id": "081e85ce-2764-4d23-b9fa-b32ace9d615d", "episode_id": "e185c522-8c27-4a79-a92d-f221919c5eab", "cms_item_id": "68225dfc7bb476527f8c4840", "chunk_index": 5, "content": "Cole Heilborn (08:20): I literally need to take a second to process that in my head. I would say that, okay, so I would say all this is so funny because it's such a simple question, but my brain is turning so hard. I had to think hard before I said it. Exactly. No, but it's a really good question. I would say that all art is design, but all design is not necessarily art. (08:49): And this is off the cuff. I think I have to think about it more to feel a hundred percent confident response. But I think what I mean is in the world of art, again, just looking at a painter, creating a painting, they're considering things like negative space in symmetry and composition, all of these things that are the fundamentals of design in the world of design, let's say you're doing a completely and totally minimalist bathroom sign in a restaurant and it just says you look at that and it is solving a problem. It is distinguishing men's restroom versus women's restroom. So in that sense, it is design. However, you would never look at that sign that just says women's in a samsara font or in times New Roman, and you'd never look and be like, that is some art. But at the same time, I'm sure there's some weird avant garde artist that's Duchamp who did the what do you write our mutt on the toilet and then put it in a gallery? And everybody was like, that's not art. I think in many senses, I don't know. I think it's an argument that you could have that everybody would have a different response to.\n\nAdam Vicarel (10:07): Sure. Who knows, someone might really love the circle combined with the triangle and two rectangles, that could be art. Exactly. Yeah. So for your business, how do you blend the two? Because I know that, and I guess I'll make some generalizations, but art and business sometimes seem like oil and water, they don't always mix. Sometimes they overlap. I guess what's your relationship or what's your thoughts on how those two mix together?", "token_estimate": 490, "speakers": ["Cole Heilborn", "Adam Vicarel"], "start_timestamp": "08:20", "end_timestamp": "10:07", "podcast_index": 28, "episode_name": "Ep 28: Adam Vicarel | Art and Business | Vicarel Studio‪s‬", "slug": "ep-28-adam-vicarel-art-and-business-vicarel-studios", "web_url": "https://www.portsidepro.com/podcast-feed/ep-28-adam-vicarel-art-and-business-vicarel-studios", "guest_name": "Adam Vicarel", "guest_title": "Vicarel Studios", "categories": [], "short_description": "\"I think like a designer, but I execute like a fine artist.\"", "podcast_length": "44:50"}, {"id": "9ac7e0f4-d752-4d81-9993-f820c2ff41d0", "episode_id": "e185c522-8c27-4a79-a92d-f221919c5eab", "cms_item_id": "68225dfc7bb476527f8c4840", "chunk_index": 6, "content": "Cole Heilborn (10:35): Yeah, it's a really good question because it's something that I can tell when I'm giving a high quote for a project that for what I'm delivering, it's a valid quote, but I can see the client sometimes wincing at how much it's going to cost, and they'll either vocalize it or I'm sure internally they're like, why am I paying this much for pretty pictures? (10:58): So I think the relationship is if picture yourself as a consumer, you just got contacts for the first time, you go to Kroger, king Soupers or whatever to buy your contact solution and nothing about any of it, and you're looking at the packaging on the shelf, there's 15 different options. If you know nothing and they're all generally a similar price point, you're going to pick the one that looks the coolest, simple as that. You're not going to pick the crappiest one, that's for sure. So I think for a very simple, concise example, in that instance, it's very obvious why quality design or art can influence purchase behavior. And from a business perspective, obviously more purchases means more revenue. So I think there's a direct correlation there, and I think it's a matter of understanding or being able to see that connection from a business standpoint. But sometimes it's really hard to have each person speaking the other person's language.\n\nAdam Vicarel (11:59): So if it is that obvious to some people, then why do you have clients in your example, they look at the sticker and they're like, oh, I don't know that I want to spend that for pretty pictures. What's that disconnect there if it really, because I think we could all say, yes, well-designed packaging makes sales on the shelf, but there's still that hesitancy to invest in the high quality design slash art. Why is that?", "token_estimate": 446, "speakers": ["Cole Heilborn", "Adam Vicarel"], "start_timestamp": "10:35", "end_timestamp": "11:59", "podcast_index": 28, "episode_name": "Ep 28: Adam Vicarel | Art and Business | Vicarel Studio‪s‬", "slug": "ep-28-adam-vicarel-art-and-business-vicarel-studios", "web_url": "https://www.portsidepro.com/podcast-feed/ep-28-adam-vicarel-art-and-business-vicarel-studios", "guest_name": "Adam Vicarel", "guest_title": "Vicarel Studios", "categories": [], "short_description": "\"I think like a designer, but I execute like a fine artist.\"", "podcast_length": "44:50"}, {"id": "ebc42562-fbf1-4537-b4c8-59a1f3f6ce8b", "episode_id": "e185c522-8c27-4a79-a92d-f221919c5eab", "cms_item_id": "68225dfc7bb476527f8c4840", "chunk_index": 7, "content": "Cole Heilborn (12:26): Yeah, I think it's another great question. I think it's a number of factors. I think every situation is different. Sometimes I believe that the person who is skeptical of the price of quality design is maybe just uninformed, and they've never worked with a quality designer before or somebody who produces high level work. So they're just not used to seeing that number of what that value is. I also think some people kind of in a similar fashion are familiar with websites like 99 Designs or Upwork where you can get a packaging design concept for $40. Whereas if you come to someone like myself, I'll be charging you thousands of dollars, and I think they kind of latch on to, well, why is this guy charging 40 and you're charging 14,000? And it's like, I don't know, you go to a car dealership and you see a used car for 850 bucks and the Ferrari is 120 grand. It's like, why is the Ferrari mow? There's a clear difference. Fricking better. Yeah. So I think I actually frequently try when clients or potential clients are confused or don't really understand or they ask the general question of how much is a logo? (13:44): I kind of compare it to cars. I'm like, well, go into a car dealership and ask 'em how much is a car? They're going to ask you a lot more questions after that. What kind of car? Do you have? Automatic windows? Do you have heated seats? Is it leather or cloth interior? So there's a lot of different things that you can do to really elevate that pricing. But to go back to your question, so I'm kind of going down a tangent here. I really do think a lot of it is either an uninformed client who doesn't understand that value of design or somebody who's seen that lower price range before and is just scared by real actual good design prices.\n\nAdam Vicarel (14:18): Yeah. It's funny you said you asked the question, what is a logo worth? And didn't Nike pay 20 or 40 bucks for their original swoosh?\n\nCole Heilborn (14:25): Yeah, it was like an intern who made it or something like that. Something ridiculous. Which to think about that the intern having that moment where he is like, wow, I could have retired or something. Yeah, it's", "token_estimate": 546, "speakers": ["Cole Heilborn", "Adam Vicarel"], "start_timestamp": "12:26", "end_timestamp": "14:25", "podcast_index": 28, "episode_name": "Ep 28: Adam Vicarel | Art and Business | Vicarel Studio‪s‬", "slug": "ep-28-adam-vicarel-art-and-business-vicarel-studios", "web_url": "https://www.portsidepro.com/podcast-feed/ep-28-adam-vicarel-art-and-business-vicarel-studios", "guest_name": "Adam Vicarel", "guest_title": "Vicarel Studios", "categories": [], "short_description": "\"I think like a designer, but I execute like a fine artist.\"", "podcast_length": "44:50"}, {"id": "0b7a7f38-3c6c-4616-9bbe-55eda32db74f", "episode_id": "e185c522-8c27-4a79-a92d-f221919c5eab", "cms_item_id": "68225dfc7bb476527f8c4840", "chunk_index": 8, "content": "Adam Vicarel (14:37): Crazy. I think they went back and paid him or her some extra after it became what it was, but that's still such a funny story.\n\nCole Heilborn (14:45): It's crazy. Yeah.\n\nAdam Vicarel (14:48): Okay, interesting. So part of it sounds like just lack of education or experience. Where does strategy for you fit into this? Because, and this is what I think your business sounds like does really well, is you have the creative, the artistic side, and you can deliver a pretty picture, I think doesn't do it justice. That doesn't sound like art. That just sounds like some Instagram photographer, which anyways, we won't go down that. Where does strategy fit into this for you? How do you take a client's goals and objectives and then apply strategy and deliver with the art?", "token_estimate": 198, "speakers": ["Adam Vicarel", "Cole Heilborn"], "start_timestamp": "14:37", "end_timestamp": "14:48", "podcast_index": 28, "episode_name": "Ep 28: Adam Vicarel | Art and Business | Vicarel Studio‪s‬", "slug": "ep-28-adam-vicarel-art-and-business-vicarel-studios", "web_url": "https://www.portsidepro.com/podcast-feed/ep-28-adam-vicarel-art-and-business-vicarel-studios", "guest_name": "Adam Vicarel", "guest_title": "Vicarel Studios", "categories": [], "short_description": "\"I think like a designer, but I execute like a fine artist.\"", "podcast_length": "44:50"}, {"id": "da61930d-5810-4033-ae05-62550d201ed9", "episode_id": "e185c522-8c27-4a79-a92d-f221919c5eab", "cms_item_id": "68225dfc7bb476527f8c4840", "chunk_index": 9, "content": "Cole Heilborn (15:28): I think so strategy is something I've recently started exploring or leaning into in my business. I realized I'd been doing that design strategy for a couple years now, but didn't really realize that I was doing it. And I also didn't really realize it was a service that people pay for. I kind of just thought I was getting better at what I was doing. So basically, I don't think every client needs intense design strategy. Some small businesses just need a logo and I'm not going to do it for a couple hundred bucks. But I think there is opportunity to tier out your work and say, if you need something for a couple grand, I can do that. But you bigger client who need strategy and really thoughtful thinking and research and consumer testing, obviously that is a whole separate service. So you're going to pay 10 x what small business charged. (16:28): But ultimately, I do think what the strategy enables is for a potential client that I'm working with, it almost validates the design for them and validate maybe is not the right word, but it proves the design is actually doing what's intended to do. So much of what I do when working on a project, let's say I'm designing packaging for a beer can, which I recently did. The beginning is just immersing myself in that industry and understanding who is doing what is working and why, who's failing, and who is pushing the boundary, and kind of trying to find out where this potential client wants to be and how they're positioning that product. And then how do I create designs that help do that? And then if you're really focusing on paying on that strategy, that's where you do more research and testing, where you're looking into this target demographic, what do they actually, what do they do on a daily basis? What brands are they using for their toothpaste in the morning? Are they getting hot dogs? Are they getting brought worse? Are they a Jack Daniels whiskey drinker or do they drink High West? I think those are the things you start to wrap your head around. And then it helps start to position the design concepts in terms of styles, colors, general layout and composition. (17:58): But again, I don't think every client needs that. That's obviously a lot of money and time and investment that goes into something like", "token_estimate": 577, "speakers": ["Cole Heilborn"], "start_timestamp": "15:28", "end_timestamp": "15:28", "podcast_index": 28, "episode_name": "Ep 28: Adam Vicarel | Art and Business | Vicarel Studio‪s‬", "slug": "ep-28-adam-vicarel-art-and-business-vicarel-studios", "web_url": "https://www.portsidepro.com/podcast-feed/ep-28-adam-vicarel-art-and-business-vicarel-studios", "guest_name": "Adam Vicarel", "guest_title": "Vicarel Studios", "categories": [], "short_description": "\"I think like a designer, but I execute like a fine artist.\"", "podcast_length": "44:50"}, {"id": "91378513-b00d-4053-b325-c2a41800c647", "episode_id": "e185c522-8c27-4a79-a92d-f221919c5eab", "cms_item_id": "68225dfc7bb476527f8c4840", "chunk_index": 10, "content": "Adam Vicarel (18:07): That. Yeah. When you look at what are the things that are most crucial for them in whatever stage they're at, sometimes it's just a real simple get off the ground package versus the fully developed, flushed out the full atom experience. Exactly, yes. So, okay. I'm curious what you think about this because I think, and this is something that we've run across and clients have said, coming back to that art, the idea of working with an artist from the client's perspective, do you think some clients feel, I don't know, burned or not heard from the creative that they hire? Because in the past, I think we as creatives sometimes have a tendency to take a client's project and turn it into our own project and not really consider what they need. Have you ran across\n\nCole Heilborn (19:02): That? In my own experience, have I done that\n\nAdam Vicarel (19:05): Well, if you've done it or have you come across clients who have experienced something similar? I wonder if that's part of the disconnect or maybe frustration between the artists that you hire and the work that they deliver.\n\nCole Heilborn (19:18): Yeah, I think in the past I've worked with clients who started off by basically telling me kind of a sob story about how they were burned by a previous designer. Coincidentally, that client ended up burning me and never paying me for the work. This was at the very beginning of my freelance career. It was an ordeal. And I think that's an instance of it's just either an inexperienced or a poor designer, poor as in bad, that found themselves in a position where they have this opportunity and it almost gives that client a bad taste. And unfortunately, it kind of screws the rest of us in the creative industry, and we almost have to make amends for them. So it's unfortunate that it's almost like we experienced the negative repercussions for someone else's bad\n\nAdam Vicarel (20:06): Actions.\n\nCole Heilborn (20:08): So yes, I have experienced it fortunately, at least in this direct question, it was only that one time, and that was truly right at the beginning of my career or at least beginning of my freelance career.", "token_estimate": 538, "speakers": ["Adam Vicarel", "Cole Heilborn"], "start_timestamp": "18:07", "end_timestamp": "20:08", "podcast_index": 28, "episode_name": "Ep 28: Adam Vicarel | Art and Business | Vicarel Studio‪s‬", "slug": "ep-28-adam-vicarel-art-and-business-vicarel-studios", "web_url": "https://www.portsidepro.com/podcast-feed/ep-28-adam-vicarel-art-and-business-vicarel-studios", "guest_name": "Adam Vicarel", "guest_title": "Vicarel Studios", "categories": [], "short_description": "\"I think like a designer, but I execute like a fine artist.\"", "podcast_length": "44:50"}, {"id": "a68753dc-70ea-4a52-809c-1cd8d591e9a4", "episode_id": "e185c522-8c27-4a79-a92d-f221919c5eab", "cms_item_id": "68225dfc7bb476527f8c4840", "chunk_index": 11, "content": "Adam Vicarel (20:21): Gotcha. Yeah. I guess what opportunities do you see where art and strategic art can be implemented in a better way or in new ways within our industry?\n\nCole Heilborn (20:36): In terms of better ways, I am just literally looking off at shelves of packaging that I've done right now to formulate a better response. But I think one of the things I like to lean into in terms of applying art in a design sense is that it really has this level of approachability or this cool factor. And there's probably, if there's designers listening to this, they're maybe wincing at the idea of saying, I just want something cool in the world of design that is not form following function, that's frivolous artwork. But I think if you tiptoe back and forth, sometimes as a designer, if you're designing for male millennials in the action sports industry, these are stoker. These dudes are snowboarding and skateboarding and drinking craft beer. These are the type of people that like cool shit for the sake of it being cool. So in many ways, that type of person is the type of person that is going to like art just for art's sake. (21:40): So if you have diagnosed the design problem and figured out that the solution for that design problem is art, then I think it makes sense. So I think I personally as a designer am trying to bring that cool factor or that approachability more and more into the design world. And this isn't a new thing by any means, but I'm trying to do so because not only does it make the product feel more honest and more considered and thoughtful, but it just is more enjoyable to look at. And I think for that reason, if you're looking at packaging design, it helps it stand out on shelf. It helps it be more memorable and recognizable. So I think in many ways there's a lot of positive applications for it. I'm just trying to figure out how to do it on a day-to-day basis, always\n\nAdam Vicarel (22:33): Learning. Yeah, that's the fun part of doing your own business, I suppose.\n\nCole Heilborn (22:37): Yeah, exactly.", "token_estimate": 513, "speakers": ["Adam Vicarel", "Cole Heilborn"], "start_timestamp": "20:21", "end_timestamp": "22:37", "podcast_index": 28, "episode_name": "Ep 28: Adam Vicarel | Art and Business | Vicarel Studio‪s‬", "slug": "ep-28-adam-vicarel-art-and-business-vicarel-studios", "web_url": "https://www.portsidepro.com/podcast-feed/ep-28-adam-vicarel-art-and-business-vicarel-studios", "guest_name": "Adam Vicarel", "guest_title": "Vicarel Studios", "categories": [], "short_description": "\"I think like a designer, but I execute like a fine artist.\"", "podcast_length": "44:50"}, {"id": "26781858-c5cf-4c28-9127-00b33310cb56", "episode_id": "e185c522-8c27-4a79-a92d-f221919c5eab", "cms_item_id": "68225dfc7bb476527f8c4840", "chunk_index": 12, "content": "Adam Vicarel (22:40): What companies do you look at or designers who have done a really good job of blending the two maybe? Are there any examples that you can think of that the average person would be familiar with?\n\nCole Heilborn (22:53): Yes. So I think in terms of designers, which people wouldn't be familiar with maybe, but John Canino is probably my go-to. He is a lettering artist and creative director based in Brooklyn, New York, and he kind of brought hand lettering into the mainstream media, or he's one of a few designers who did. So I think for an example of somebody, he's a great reference point in terms of an actual product or service in the real world. I think Lifewater is a great example. I believe they have little artful expressions on in so many different kinds on so many of their water bottles. And I think it is truly just what we talked about before where it is beautiful and cool looking, and that is why people buy it when they're looking at life water versus, I can't even think of another water example.\n\nAdam Vicarel (23:50): Water brands, I don't know, a plastic water bottle, Aquafina. Exactly,\n\nCole Heilborn (23:54): Exactly. Well, yeah, firstly they should be drinking out of a nail Jane, but we don't need to get into that. But yeah, it's something like life water is just beautiful and looks cool. Aquafina looks the same every time. So the life water, it feels like an obvious pick, at least to someone like myself. So I think that's a great example of somebody doing it in the broader real world and doing it quite well.\n\nAdam Vicarel (24:14): Yeah. Well then you also have to think, sure, okay, so I might spend, I don't know, $30 on this nice water bottle versus the dollar on the cheap plastic one, but how much more return does the company get from that individual purchasing that nice water bottle just in like, I'm imagining the social media engagement, they get, you have a beautiful water bottle, you take it on a cool hike, you're like, oh, this is pretty, I'm going to take a photo, post it on Instagram, and then that happens thousands or hundreds of thousands of times. That adds up.", "token_estimate": 535, "speakers": ["Adam Vicarel", "Cole Heilborn"], "start_timestamp": "22:40", "end_timestamp": "24:14", "podcast_index": 28, "episode_name": "Ep 28: Adam Vicarel | Art and Business | Vicarel Studio‪s‬", "slug": "ep-28-adam-vicarel-art-and-business-vicarel-studios", "web_url": "https://www.portsidepro.com/podcast-feed/ep-28-adam-vicarel-art-and-business-vicarel-studios", "guest_name": "Adam Vicarel", "guest_title": "Vicarel Studios", "categories": [], "short_description": "\"I think like a designer, but I execute like a fine artist.\"", "podcast_length": "44:50"}, {"id": "3d685ca0-11c9-488e-86f8-0dc112c8fa7c", "episode_id": "e185c522-8c27-4a79-a92d-f221919c5eab", "cms_item_id": "68225dfc7bb476527f8c4840", "chunk_index": 13, "content": "Cole Heilborn (24:47): Exactly. And I think brands more and more are recognizing the importance of that kind of organic marketing that especially with the prevalence of social media, people realize if something looks cool or works really well, they'll have these micro brand advocates, someone like yourself or myself who just takes a picture of the products because they're like, Hey, look, this is cool. Throws it up on Instagram stories, and all of a sudden it gets in front of another couple thousand people and it didn't cost that brand any extra money.\n\nAdam Vicarel (25:16): It just costs them whatever your fee is to design that cool art piece.\n\nCole Heilborn (25:20): Yes, exactly.\n\nAdam Vicarel (25:22): Yep. Yeah. Interesting. So where do you want your business to go? You mentioned you want to do more mural work. What would you love to be doing in the future? All entirely.", "token_estimate": 222, "speakers": ["Cole Heilborn", "Adam Vicarel"], "start_timestamp": "24:47", "end_timestamp": "25:22", "podcast_index": 28, "episode_name": "Ep 28: Adam Vicarel | Art and Business | Vicarel Studio‪s‬", "slug": "ep-28-adam-vicarel-art-and-business-vicarel-studios", "web_url": "https://www.portsidepro.com/podcast-feed/ep-28-adam-vicarel-art-and-business-vicarel-studios", "guest_name": "Adam Vicarel", "guest_title": "Vicarel Studios", "categories": [], "short_description": "\"I think like a designer, but I execute like a fine artist.\"", "podcast_length": "44:50"}, {"id": "2af7f53e-a1be-47ab-a010-d8873b23b568", "episode_id": "e185c522-8c27-4a79-a92d-f221919c5eab", "cms_item_id": "68225dfc7bb476527f8c4840", "chunk_index": 14, "content": "Cole Heilborn (25:33): Yeah. And are you talking next to year or are you talking five, 10 years down the line, whenever, whatever the future means when there's robots taking over the world? Yeah, I think we were kind of chatting offline before this, and I think with 2020 being the year it has been, it's forced me to, or maybe allowed me to step back and kind of look at my business from a more of a 10,000 foot perspective. I got into working for myself because I loved travel. I took a year off just traveling before I moved to Denver. And in that time I fell in love with hand lettering. I got into hand lettering because I wanted to be doing it in the outdoor and action sports industries, and that's kind of where I got my foot in the door. So I think this opportunity to step back because of 2020, I've realized that the last few years have been focused on go grow, grow, grow, and I realized that I don't want to grow a big business or a big agency. (26:40): I don't want it to be something where if I decide I want to go scuba dive in Mexico for a month, which is a very probable opportunity or thing I would do, I don't want to feel responsible for a bunch of people's salaries or worried about fulfilling payroll, or if a client project is done, I want to be able to disconnect and disconnect. So initially I was thinking that I would maybe get a few full-time employees and they would be able to help me grow the business, which would be the case. However, I think I'm more interested at this point in growing more of a freelance agency, if you will, and have trusted contractors that I go to for various projects that can help me grow things. And I pay them well on an hourly rate. I give them consistent work. So they're frequently available, but there isn't that pressure of, oh shit, we had another pandemic. There's no money coming in four months, but I still owe you each 70 grand a year. So I think that stepping back and realizing that I'm really interested in growing my business with just myself and trusted contractors is probably the route I'll be pursuing for the next few years.", "token_estimate": 526, "speakers": ["Cole Heilborn"], "start_timestamp": "25:33", "end_timestamp": "25:33", "podcast_index": 28, "episode_name": "Ep 28: Adam Vicarel | Art and Business | Vicarel Studio‪s‬", "slug": "ep-28-adam-vicarel-art-and-business-vicarel-studios", "web_url": "https://www.portsidepro.com/podcast-feed/ep-28-adam-vicarel-art-and-business-vicarel-studios", "guest_name": "Adam Vicarel", "guest_title": "Vicarel Studios", "categories": [], "short_description": "\"I think like a designer, but I execute like a fine artist.\"", "podcast_length": "44:50"}, {"id": "4fca4ef9-279c-4a13-ba7a-15e540d536e7", "episode_id": "e185c522-8c27-4a79-a92d-f221919c5eab", "cms_item_id": "68225dfc7bb476527f8c4840", "chunk_index": 15, "content": "Adam Vicarel (27:50): Yeah, I love it. Alright, my last question I've been thinking about, we've been talking about art and business, how they're connected, how they're not connected, but even in the nature of my questions I've been asking them about, they're two separate things. I ask, what do you think about art and business? In my question, they're separated. Do they need to be? Do you think there's a place where do design advertising in the future, we can get to where those two are synonymous and are blended in a much more, I dunno, symbiotic relationship?\n\nCole Heilborn (28:26): So I think in many ways they really already are. I think more than anything in the future, I would hope that there could be more education for all so that people understand that without the art and design that the business, neither of them can succeed without the other. The art and design is just going to sit there and be beautiful on a desk or in a drawer if not for a marketing plan or an innovative business product or idea associated with it. But the innovative product or idea likely is not going to gain traction without being attractive to its intended demographic. So again, I think in many ways this stuff is already happening. However, I think it is just a lack of education or a lack of knowledge from either end, whether you're more on the business side or more on the creative side. So hopefully with time and now the realized importance of how quality to design can really make or break a product, I'm hopeful that pushes things forward and enables people to kind of see that there are basically these two synonymous things, business and art.\n\nAdam Vicarel (29:33): Yeah. I love it. Alright, well if people want to find you, if they want to find your work, where can people go to check you out?\n\nCole Heilborn (29:40): Yeah, the best place to find my work would be Adam Vicar on Instagram just at Adam Vicar. And then my website would be vicar studios.com and you can find any other contact information or links through either of those platforms there.", "token_estimate": 515, "speakers": ["Adam Vicarel", "Cole Heilborn"], "start_timestamp": "27:50", "end_timestamp": "29:40", "podcast_index": 28, "episode_name": "Ep 28: Adam Vicarel | Art and Business | Vicarel Studio‪s‬", "slug": "ep-28-adam-vicarel-art-and-business-vicarel-studios", "web_url": "https://www.portsidepro.com/podcast-feed/ep-28-adam-vicarel-art-and-business-vicarel-studios", "guest_name": "Adam Vicarel", "guest_title": "Vicarel Studios", "categories": [], "short_description": "\"I think like a designer, but I execute like a fine artist.\"", "podcast_length": "44:50"}, {"id": "bdfc9bb4-9d41-4650-bd86-a41952ae7d7f", "episode_id": "e185c522-8c27-4a79-a92d-f221919c5eab", "cms_item_id": "68225dfc7bb476527f8c4840", "chunk_index": 16, "content": "Adam Vicarel (29:56): Okay, great. And if you're interested in learning more about how COVID has impacted creative entrepreneurs, you should check out one of Adam's blogs, which is recently blown up and is very insightful.\n\nCole Heilborn (30:08): Yeah, thank you so much. Yeah, definitely. I created it to be a resource for people like yourself and myself. I know a lot of people are struggling and I was panicking at the beginning. So yeah, if you guys are interested in the article just on vial studios.com/blog and it's called 30 K in 30 hours, and there's a lot of fascinating stuff in that article.\n\nAdam Vicarel (30:33): If I'm just going to take a guess, I'm going to assume that you didn't make 30 K in 30\n\nCole Heilborn (30:36): Hours. Yeah, yeah. For the record, it was definitely losing money, not making money.\n\nAdam Vicarel (30:40): Yeah. Alright, well, hey Adam, thanks so much. It's been a pleasure chatting. I appreciate you sharing your thoughts and sharing what you're working on over in Colorado.\n\nCole Heilborn (30:50): Yeah, thank you so much, Cole. It's great to meet you, man.\n\nAdam Vicarel (30:52): Yeah, take care. Thank you for listening to this episode of the Backcountry Marketing Podcast. If you enjoyed today's episode or learned something new, please consider leaving us a review on Apple or sharing this with a friend.", "token_estimate": 338, "speakers": ["Adam Vicarel", "Cole Heilborn"], "start_timestamp": "29:56", "end_timestamp": "30:52", "podcast_index": 28, "episode_name": "Ep 28: Adam Vicarel | Art and Business | Vicarel Studio‪s‬", "slug": "ep-28-adam-vicarel-art-and-business-vicarel-studios", "web_url": "https://www.portsidepro.com/podcast-feed/ep-28-adam-vicarel-art-and-business-vicarel-studios", "guest_name": "Adam Vicarel", "guest_title": "Vicarel Studios", "categories": [], "short_description": "\"I think like a designer, but I execute like a fine artist.\"", "podcast_length": "44:50"}, {"id": "8164dc37-a30c-4524-864d-a3da9a56e6d1", "episode_id": "866bde16-a78a-49c7-89c6-44cc876f737b", "cms_item_id": "68225dfc7bb476527f8c484b", "chunk_index": 0, "content": "Cole Heilborn (00:00:02): Welcome to the Backcountry Marketing Podcast. My name is Cole Helebo and I'll be your host today. This podcast dives deep with leaders of the outdoor marketing industry as they discuss the gritty details of their work, personal challenges, and latest adventures, whether you're standing in the lift line, shuttling the fresh loam, or cracking a local beer. I hope you enjoyed today's episode. This is the Backcountry Marketing Podcast. This episode is produced by Port Slide Productions, an outdoor, commercial and film production company based in the Pacific Northwest. Let's make waves. Welcome to the Backcountry Marketing Podcast. Today I'm sitting down with Gary Boulanger, the communications marketing manager at Fox Factory. Gary, how are you\n\nGary Boulanger (00:00:45): Doing fine, Cole. Thanks so much.\n\nCole Heilborn (00:00:47): Yeah, thank you for joining us. Where are you calling in from today?\n\nGary Boulanger (00:00:51): Mountain View, California.\n\nCole Heilborn (00:00:53): Okay, beautiful. A little sunnier down there, maybe a little bit too sunny right now, it sounds like, huh?\n\nGary Boulanger (00:00:58): Yeah, it's a little bright. Fire's going on, a little excessive heat, but we're sturdy. We're very sturdy here in Silicon Valley.\n\nCole Heilborn (00:01:06): Well, let's jump right in. I'm sure people know who Fox is. You guys are kind of everywhere, but why don't you give us kind of the quick background on who Fox is?", "token_estimate": 368, "speakers": ["Cole Heilborn", "Gary Boulanger"], "start_timestamp": "00:00:02", "end_timestamp": "00:01:06", "podcast_index": 29, "episode_name": "Ep 29: Gary Boulanger | Make the Jump | FOX Factor‪y‬", "slug": "ep-29-gary-boulanger-make-the-jump-fox-factory", "web_url": "https://www.portsidepro.com/podcast-feed/ep-29-gary-boulanger-make-the-jump-fox-factory", "guest_name": "Gary", "guest_title": "Communications Marketing Manager, FOX Factory", "categories": [], "short_description": "\"Don't be afraid to totally jump into a new industry and be confident that the skills learned translate to other industries.\"", "podcast_length": "44:51"}, {"id": "6106f1f7-21bc-486a-a95d-710f750db121", "episode_id": "866bde16-a78a-49c7-89c6-44cc876f737b", "cms_item_id": "68225dfc7bb476527f8c484b", "chunk_index": 1, "content": "Gary Boulanger (00:01:17): Back in the seventies, Bob Fox, he decided that with his hobby of racing motocross, he's a bigger guy. He was a bodybuilder. He was involved with a lot of different things. He realized that suspension on those bikes needed some uptick, so he took it upon himself with his brother Jeffrey. They started a company in the early seventies. Bob focused on suspension. Jeffrey focused on protective gear. By the late seventies, Bob wanted to suspend the world. Jeffrey wanted to protect the world, so to speak, of motocross, but Bob had an idea to literally suspend everything. A couple years later, he segued away from motocross. We won the 1983 Indy 500 with Tom s Neva. It never became commercially viable to do something, but he was just exploring. He wanted to expand. As the eighties went along, we got involved with Baja racing, off-road racing, snowmobile racing. (00:02:18): We ended up really getting heavily involved with bicycle suspension in the nineties as well. And between that and snowmobile, it really buoyed the company. But we were growing at such a rate that the OEM partners, the manufacturers, like the Fords, Polaris, people like Polaris, that we were already doing stuff with a TV and snowmobile when side-by-sides became a thing about 12 years ago. People know they knew to turn to Fox, and that really bolstered what we were doing from an engineering standpoint. Bob was an engineer. Bob's close to 80 now, still feisty, but engineering has always been our focus, and when you start doing things at that level where you're creating a suspension that can really travel and really catch the air, and really not just be action sports, but bigger than that some ways, that's where we caught the attention of the Jeeps and the Toyotas and the Fords, and now we're starting to see Fox Spec OE on the new Jeep Mojave, the Ford Raptor. The last few years we're getting heavily involved with electronic suspension as well in all facets of what we do. So it's been fun and interesting. 45 plus years later, we're always looking for the next big thing. And it's been fun because with COVID going on, people have been deciding to be outdoors, play outdoors, have fun outdoors, and that's really helped. That's really helped Fox. It helps that everyone at foxes and enthusiasts, and we have so many different sandboxes that we can play in. So it does make work quite a bit of fun. It makes work scary fun at times, but it's a very cohesive group of people, and we've got folks all around the world. So", "token_estimate": 634, "speakers": ["Gary Boulanger"], "start_timestamp": "00:01:17", "end_timestamp": "00:01:17", "podcast_index": 29, "episode_name": "Ep 29: Gary Boulanger | Make the Jump | FOX Factor‪y‬", "slug": "ep-29-gary-boulanger-make-the-jump-fox-factory", "web_url": "https://www.portsidepro.com/podcast-feed/ep-29-gary-boulanger-make-the-jump-fox-factory", "guest_name": "Gary", "guest_title": "Communications Marketing Manager, FOX Factory", "categories": [], "short_description": "\"Don't be afraid to totally jump into a new industry and be confident that the skills learned translate to other industries.\"", "podcast_length": "44:51"}, {"id": "868c63fc-25a0-46d3-a997-621454569704", "episode_id": "866bde16-a78a-49c7-89c6-44cc876f737b", "cms_item_id": "68225dfc7bb476527f8c484b", "chunk_index": 2, "content": "Cole Heilborn (00:04:11): Yeah, I mean, you guys get to play with all the cool toys that's got to make your job a little fun. What does your job entail? What do you oversee? What do you work\n\nGary Boulanger (00:04:20): On? My job is primarily to be the storyteller and the brand journalist, for lack of a better term, for Fox, because I come from a journalist and PR background. We realized up until a few years ago that so much of what we're doing was OE focused, where we would work closely with our OEM partners. They would design chassis vehicles and so forth. We'd come alongside at a certain point, we'd provide suspension with our name on it. Sometimes we'd share the space with our OE partner, and that would be it. We didn't have to do a whole lot of marketing. We would go racing, of course, and our athletes would be branded with Fox, so they would be our mouthpiece. It wasn't until our team was started, not quite two years ago, the power vehicle group marketing team, which we never had before. We always had a small corporate marketing team that would do the storytelling, but that was split amongst all our division, motorcycle, snow, A-T-V-U-T-V, truck off, offroad, mountain bike, you name it. So you can imagine that if a certain segment is grabbing more attention or more popular or more maybe identifiable with a larger segment like mountain biking can be worldwide, other categories are going to get neglected. A bit like case in point Motorcycle, I was senior editor at Cycle World Magazine, and I had no idea that Fox made shocks for Harley's (00:05:55): Because they didn't really put the time into it. They only had limited resources. So we realized that a big part of what we needed to do was tell our story. It's lovely when you have companies like ours that has four, almost five decades of heritage, history, victory, innovation, the fact that Bob is still with us and we're still located in the heart of where we started all those years ago, that meant that we needed to have a considered effort to tell and share the story. So with that back about a year ago, we realized that as the media is struggling to maintain its footing, tech editors, feature editors like I used to be printed publications, even online publications, there's a lot of branded content. And I think readers are feeling a little short shrifted in that they want information, they want tech. There are a lot of publications that focus on that, but oftentimes you need that plus a bit of a backstory. (00:07:06): That plus a bit of who is this person? What makes this athlete maybe a bit more special, not just because they're on the podium or winning, but what drives them. And conversely, what drives Fox? All of our engineers, when they go out playing, they're loading up the trailer with the side-by-side and they're towing it with their Ford or Chevy or Toyota truck, and there's usually mountain bikes in the back that are all specked out with Fox. So that's what we do. And even that story is one that I know we're going to be sharing at some point, so there's quite a bit going on. But with the storytelling, we also uncovered the fact a little over a year ago that education is something that needs to come first. Education and what is suspension all about? What makes a shock work? What other parts of a shock? (00:08:04): I buy a vehicle, I buy a very expensive vehicle to the tune of $65,000, either a Jeep Mojave or a Ford Raptor. I paid all this money. My suspension should work perfectly well. It's much like a guitar. You need to tune it, you need to lay hands on it. And we realized that known in the industry was really giving permission to the end user, the person who owns the vehicle to actually adjust, tune, set, sag, all those various things on their suspension based on the use case. What's this person going to do with this vehicle or bicycle? So we developed what we called Fox Academy, and it's a video series that goes along with telling the basics. We use our ambassadors and racers, and they give testimonials as to why certain upgrades matter versus stock or what we call standard. But the fact that we identify just all what the moving parts do and what they mean, and it's actually evolved into something that we use for onboarding new employees.", "token_estimate": 1071, "speakers": ["Cole Heilborn", "Gary Boulanger"], "start_timestamp": "00:04:11", "end_timestamp": "00:04:20", "podcast_index": 29, "episode_name": "Ep 29: Gary Boulanger | Make the Jump | FOX Factor‪y‬", "slug": "ep-29-gary-boulanger-make-the-jump-fox-factory", "web_url": "https://www.portsidepro.com/podcast-feed/ep-29-gary-boulanger-make-the-jump-fox-factory", "guest_name": "Gary", "guest_title": "Communications Marketing Manager, FOX Factory", "categories": [], "short_description": "\"Don't be afraid to totally jump into a new industry and be confident that the skills learned translate to other industries.\"", "podcast_length": "44:51"}, {"id": "d6a92d5a-4a14-4a8e-9cff-122554efe089", "episode_id": "866bde16-a78a-49c7-89c6-44cc876f737b", "cms_item_id": "68225dfc7bb476527f8c484b", "chunk_index": 3, "content": "Cole Heilborn (00:09:09): Okay.\n\nGary Boulanger (00:09:11): A lot of us do not come from suspension per se. We come from different sports, power sports. So it was really important that people understand what are all the moving parts just with suspension in general, and then what sets Fox apart. And for us to be able to share that story, then we've been able to cross pollinate with what we call Fox Stories, and that's our digital publication and Fox Academy. And we launched Fox Stories at King of the Hammers this past January 31st, right before the Super Bowl, and we had to do a virtual launch on June 9th of Fox Academy. And the reception that we've had from consumers, from the media, from the industry on Fox Academy specifically, has been very powerful. It's something that our, for example, four Wheel Parts is a very strong partner of ours, distributor, and this is Fox Academy, is something that they can share with their stores. It could be playing on screens in store, and as customers are milling around looking at things, here's a chance for them to learn a little bit more. And we don't specifically break down suspension for just one category. Each episode we run the gamut on what it looks like for snow, what it looks like for (00:10:34): Jeeping, what it looks like for riding a side by side. And that's been, I think probably with the benefit of hindsight, one of our strongest initiatives that has caught the attention of leadership and has received their support leadership is now based in Brazelton, Georgia, near Road Atlanta, where we have a new tech center, an r and d facility, and there's so much going on in the power vehicle world that to be able to get on top of it and really message it clearly has been a huge challenge because Fox, previous to our coming on board, was also very heavy on events. Let's take our big rig out to Sturgis and do installs for 10 days. Let's take our big rig to King of the Hammers and do installs for 10 days. Let when Fox goes out traveling, Fox goes big. (00:11:31): We have tuners that lay hands on people's race vehicles, like I mentioned Daytona or Sturgis, in years past, we would lay hands on people's bikes and we'd upgrade their shocks and fork springs and so forth. But when you do that, it's important. And we've been as one of our marketing cohorts on the bicycle sites, so we've been spreading the magic ferry dust of racing for decades. But in this digital age, especially with shelter in place and the uncertainty of what's going on, how do you reach more people? We were hamstrung with literally not being able to go. I mean, Sturgis just ended this past weekend, and for the first time in a while, we weren't there to support either our friends at Indian, our super hooligan race team, things like that. So the timing, the benefit of hindsight on what we're doing with Fox Stories and Fox Academy has been spot on. The big key is making sure that now that we're focusing on aftermarket as well as oe, that our aftermarket partners have product that's any company's challenge, right? It's all about fulfillment and distribution. That's what makes Amazon so amazing. That's what makes Apple so amazing, right?", "token_estimate": 798, "speakers": ["Cole Heilborn", "Gary Boulanger"], "start_timestamp": "00:09:09", "end_timestamp": "00:09:11", "podcast_index": 29, "episode_name": "Ep 29: Gary Boulanger | Make the Jump | FOX Factor‪y‬", "slug": "ep-29-gary-boulanger-make-the-jump-fox-factory", "web_url": "https://www.portsidepro.com/podcast-feed/ep-29-gary-boulanger-make-the-jump-fox-factory", "guest_name": "Gary", "guest_title": "Communications Marketing Manager, FOX Factory", "categories": [], "short_description": "\"Don't be afraid to totally jump into a new industry and be confident that the skills learned translate to other industries.\"", "podcast_length": "44:51"}, {"id": "2d40ecbc-f0f0-4f47-b09e-92c1712680dd", "episode_id": "866bde16-a78a-49c7-89c6-44cc876f737b", "cms_item_id": "68225dfc7bb476527f8c484b", "chunk_index": 4, "content": "Cole Heilborn (00:12:50): Yeah, interesting. Expand on that. What are some of the other challenges that you guys are facing?\n\nGary Boulanger (00:12:57): The biggest one for us was the fact that we had the shelter in place. Both of our US factories, we have a rather large facility in Watsonville, California, and that's where our power sports stuff is made. Motorcycle, A-T-V-U-T-V and snow. And then in El Cajon, California, near San Diego is where our truck and off road suspension parts are made. And for a certain amount of time, not only were we told, sorry, can't have your people making stuff anymore for the time being, same thing happened with Polaris Ford, FCA, which is Fiat Chrysler. So everyone that we do business with here in the States, everyone was in limbo. Meanwhile, companies like Revzilla that sell motorcycle parts direct online that we deal with, they're having record days one after another. So we're trying really hard to keep up with that. (00:13:59): Thankfully, a lot of our distributors really do some strong forecasting, and we were able to fill those pipelines. But the biggest challenge is it's a real catch 22 now that we're getting a lot of very high profile OEM spec. All of a sudden now, all this marketing and all this word of mouth and all the good effort that we've been striving for means that we have this rather large demand. So when, case in point, Brian Fuller is a custom car truck and motorcycle fabricator near Atlanta, a really good partner of ours, really good friend of mine. He reached out recently. He has a TV series, and he needed some suspension for 1961, international Harvester, (00:14:48): Beautiful. Basically the predecessor to the Bronco and all the cool stuff that we're seeing. And I said, I could get you something Brian, like we always do, but I'd have to take it away from a customer, a four wheel parts somewhere in the country, which means I'd have to call that person, that customer and say, do you mind if Brian Fowler has take this away from you? I know you've been waiting a few months. So that's the catch 22 is we have this demand. Thankfully, I dunno how Brian did it. I recommended that he get ahold of some four wheel parts somewhere in the country that doesn't have dibs on that product. (00:15:23): And he did. And then we'll settle up with getting him what he needs once the vehicle gets into a full on build form. So we're very sensitive that we're not grabbing product to give to an ambassador, to eraser that essentially is kicking a distributor or a customer out of the queue, so to speak. And a big part of what we're doing to offset that is we just finished a building, a 340,000 square foot factory near Brazelton, Georgia that is not fully up and running, but it's getting close because the off-road and truck segment of our business, there is such a large demand on production that we just cannot keep up blessing and a curse really. So a lot of that demand is from our OE partners, and they just want more. We just saw the forward Bronco was just introduced. Fox is not equipped on that vehicle, but the Bronco Raptor is going to be foxed out, and that's coming next year. We have a lot of things in the works with Polaris because Polaris does the snowmobiles, the side-by-sides, and they also own the Indian brand. So we're doing more on the OE side, which is wonderful. And we're also doing more on the aftermarket side. (00:16:51): Thankfully, Watsonville is so dialed that they're able to take the over spill production from El Cajon and help us keep up with the demand on the Jeep stuff. So it's been good, but it needs to be better. And that's where this rather large facility in Georgia, which is the same footprint of our two California facilities combined, is really going to help relieve that pressure and allow us to really position El Cajon to be ideally suited to do more r and d race development, tuning so close to the desert down there. And that's always been important for Fox as we go tuning every vehicle that we spec, whether it's OE or for aftermarket, there's a lot of miles that are put on those vehicles before things pass muster and make it to market.", "token_estimate": 1042, "speakers": ["Cole Heilborn", "Gary Boulanger"], "start_timestamp": "00:12:50", "end_timestamp": "00:12:57", "podcast_index": 29, "episode_name": "Ep 29: Gary Boulanger | Make the Jump | FOX Factor‪y‬", "slug": "ep-29-gary-boulanger-make-the-jump-fox-factory", "web_url": "https://www.portsidepro.com/podcast-feed/ep-29-gary-boulanger-make-the-jump-fox-factory", "guest_name": "Gary", "guest_title": "Communications Marketing Manager, FOX Factory", "categories": [], "short_description": "\"Don't be afraid to totally jump into a new industry and be confident that the skills learned translate to other industries.\"", "podcast_length": "44:51"}, {"id": "4641ea81-cfd0-461d-a16d-762c3307a271", "episode_id": "866bde16-a78a-49c7-89c6-44cc876f737b", "cms_item_id": "68225dfc7bb476527f8c484b", "chunk_index": 5, "content": "Speaker 3 (00:17:45): So\n\nGary Boulanger (00:17:45): That would explain why we've been so West Coast centric all these decades. So it's evolving. It's definitely evolving.\n\nCole Heilborn (00:17:55): Yeah, that's interesting. Too much demand and not enough supply.\n\nGary Boulanger (00:18:01): Yeah. Yeah. And I guess for the first time, probably since I can remember, it was actually a detriment to be a US manufacturer, because on the bicycle side, we transitioned manufacturing to our Taiwan factory about eight, nine years ago. Because as bicycles have evolved, mountain bikes specifically, virtually everything on that bicycle is made in Taiwan. So up until nine years ago, all the fox forks and shocks from mountain bikes were made in Watsonville, (00:18:34): And we realized we were making all this great stuff here, shipping it over there, the bike in the box would been shipped back here because North America is the largest market, Germany's close second or maybe their neck and neck, but it was very cost prohibitive. The challenge with Taiwan is you really do need to own your manufacturing, have your people quality control, intellectual property and all that. So it took a while to do that, which also freed up a lot, quite a bit of manufacturing space in that Watsonville facility as our power sports segment grew. So you can see, so the point being is our bicycle business has just exploded something like 75% increase over the last few months with demand, because now we're getting a lot of specific orders from our partners, whether it's Pivot, whether it's giant, whether it's Trek, whether it's specialized, because as you've probably seen bicycle shops, I think it's been unprecedented since the oil embargo days or early seventies where people are just buying everything off the shelf and bike shops are doing everything they can to keep up with that demand. So that was the exception for Fox Factory, actually to have Taiwanese manufacturing, but our domestic manufacturing suffered because of the shelter in place and all the protocols.\n\nCole Heilborn (00:20:08): I see. Okay.\n\nGary Boulanger (00:20:09): Yeah, very ironic. Very ironic.", "token_estimate": 540, "speakers": ["Speaker 3", "Gary Boulanger", "Cole Heilborn"], "start_timestamp": "00:17:45", "end_timestamp": "00:20:09", "podcast_index": 29, "episode_name": "Ep 29: Gary Boulanger | Make the Jump | FOX Factor‪y‬", "slug": "ep-29-gary-boulanger-make-the-jump-fox-factory", "web_url": "https://www.portsidepro.com/podcast-feed/ep-29-gary-boulanger-make-the-jump-fox-factory", "guest_name": "Gary", "guest_title": "Communications Marketing Manager, FOX Factory", "categories": [], "short_description": "\"Don't be afraid to totally jump into a new industry and be confident that the skills learned translate to other industries.\"", "podcast_length": "44:51"}, {"id": "508e9391-fa5d-41ee-8ac4-48386c11d9a2", "episode_id": "866bde16-a78a-49c7-89c6-44cc876f737b", "cms_item_id": "68225dfc7bb476527f8c484b", "chunk_index": 6, "content": "Cole Heilborn (00:20:12): Yeah. Interesting. Alright, so let's shift gears a little bit. You've got a really fascinating career story and I'd love for you to share all of it, parts of it, pieces of it, whatever you see fit. Because I think, and something that you've talked a lot about is it's okay to not necessarily know what's next. And it's interesting and relevant because as you guys are in these current challenges, you also don't know what's next. But I think I'm hoping your career history can kind of speak to that. So if you want to dive into that and kind of fill us in on where you started and how you ended up here, that would be great.\n\nGary Boulanger (00:20:54): Okay. Yeah, it was growing up in Green Bay, Wisconsin. Of course, everyone is fully bathed in being a Packer fan, being involved with sports, and I loved it. It was great family time. But I also, when I got involved with soccer at an early age, soccer is a very international sport. Football is definitely an American thing.\n\nSpeaker 3 (00:21:21): And", "token_estimate": 258, "speakers": ["Cole Heilborn", "Gary Boulanger", "Speaker 3"], "start_timestamp": "00:20:12", "end_timestamp": "00:21:21", "podcast_index": 29, "episode_name": "Ep 29: Gary Boulanger | Make the Jump | FOX Factor‪y‬", "slug": "ep-29-gary-boulanger-make-the-jump-fox-factory", "web_url": "https://www.portsidepro.com/podcast-feed/ep-29-gary-boulanger-make-the-jump-fox-factory", "guest_name": "Gary", "guest_title": "Communications Marketing Manager, FOX Factory", "categories": [], "short_description": "\"Don't be afraid to totally jump into a new industry and be confident that the skills learned translate to other industries.\"", "podcast_length": "44:51"}, {"id": "84cdb6f8-68fa-418c-a23a-dfa71984fcad", "episode_id": "866bde16-a78a-49c7-89c6-44cc876f737b", "cms_item_id": "68225dfc7bb476527f8c484b", "chunk_index": 7, "content": "Gary Boulanger (00:21:21): Soccer in the early seventies too, in the United States was very rare. So that gave me my first taste of maybe the unconventional, the eclectic. I remember vividly freshman year in high school where our history teacher was also the freshman football coach, and he did not like soccer players. He didn't really think we were athletes. I remember there vividly, right? (00:21:48): Not realizing that I think between Moto GB Formula One and soccer, they're the most physically demanding sports on the planet, but I digress. So I had this mindset of going for the unconventional. And when you start playing different sports, soccer, bicycle racing, cyclocross, all those things, which now everyone's aware of, a lot of people partake, it's no longer unconventional. It introduced me to books, movies, people, places, things that kind of open up my eyes beyond my perch in Allway, Wisconsin, outside of Green Bay. And because of my love for soccer, that's what took me to a college in southeastern Wisconsin where I was able to play soccer. But I went to school for marketing, which back in the early eighties meant most likely it meant sales slash marketing, which meant if you were lucky, you might be a fax machine salesperson or you'd end up selling things door to door. It was very cloudy. And the only reason I went to school for marketing is because I wanted to be a cartoonist in grade school, and I was a very good artist, but I would seek the approval or maybe the advice of different adults, Hey, I'm thinking of going to this school, what do you think? And because it's so unconventional, I'd get the response, well, why would you do that? You can't make any money at that. (00:23:18): So I thought, all right, I'm in high school. And I realized, well, my art skills, my good friend Louis's dad's an architect. I want to be an architect. Not realizing at the time that you needed to be really good with maths and science, and I was not good in math and science, but I remember Louis's dad telling me, well, the computer age is coming. I don't know if architects will exist anymore. It's going to all be computer driven, (00:23:43): Right? This is early eighties before Macintosh came out, before really saw the personal computer segment grow. So once again, a well-intentioned, but Ill-advised adult telling me that you can't make money at that or something's going to change it. I ended up going to school for marketing, which is all well and good, but I floundered for a few years, first few years of college playing soccer. And I realized that part of what I enjoyed about art was that visual storytelling. And I would read comic books, just like most writers read a lot to sharpen their cognitive skills for wordplay and structure and so forth. I would always read, probably read more comic books and actually read textbooks. Maybe that's why I wasn't good at Math of Science. But what prompted me to switch to journalism halfway through college was I just wasn't into playing soccer anymore. I enjoyed it, but I would find myself asking. All my teammates always had questions, very inquisitive, and I decided, well, I'm going to switch to journalism. I'm going to give up playing soccer. I had a good couple solid years on the varsity team, but I became a sports reporter for the school newspaper (00:25:04): Because I also loved music. I was the music reporter. So I'd go to concerts and interview bands. I got a job, a part-time job, as well as a sports reporter for the local daily newspaper. So this is back in the late eighties where I'm taking my own pictures, interviewing people, I'm developing my own film. It was college and high school sports, and I was just gobbling up what journalism meant. And I also was fortunate to have a solid professor or two that really encouraged me. So finally, an adult beyond my parents. Of course, my parents always encouraged me, but an adult whom I respected that said, you've got something here. But I learned the mechanics, the fundamentals, and the foundation of storytelling through the hard news journalism, of course, it's very dry. Your sports reporting, court reporting, news reporting isn't as exciting. So I was able to segue into more long form Narrative magazine stuff. (00:26:10): So the inquisitive nature of asking people, whether it's Brian Ritchie, the bass player from violent fems, who was a big part of my life growing up because they were in Milwaukee, Wisconsin, I was in Milwaukee, Wisconsin. You start asking other people their opinion or something, or you ask them to tell you their story. So in a sense, what I was doing for several years as a journalist is I was learning other people's trials, tribulations, highs, lows, successes, failures, and I've got this ability to soak it all up like a sponge. And as evolved, and I was wanting to be that full-time music journalist, I realized, well, I don't have the courage to move to New York to work for Rolling Stone. I really don't have the financial ability or courage to move to California where a lot of the other publications were. So I kept my nose down. (00:27:02): And when a big recession happened in the early nineties with the first Gulf War, I also found myself after leaving the advertising world kind of in a pickle. A lot of people are now, you're really overqualified. The jobs aren't there. There's a bit of, not a bit of, let's just call it, there's huge uncertainty. I also didn't have a master's degree, so I didn't quite have what it took to slot in where there might've been opportunity. So I kind of did a bit of a self audit. Let's call it an auto audit. What do I really enjoy? Well, I liked storytelling, but what do I really enjoy? Bicycling? And when I worked at my first magazine job when I was just finishing up college, before I got into advertising, the only other younger person, there was a guy named Steve Smith, and he was in the cycling. I walked into his office and he had jerseys hanging there. He had posters on the wall tour to France, stuff. I had no idea. It just wasn't in my thing. I was a hundred percent soccer and comic books, right? (00:28:05): So I said, hold my hand. Walk me into this world. What is bicycling all about? And this is 1988 following year, Greg Laman wins the second tour de France miraculously and the Champ final time trial. So late 1990, early 91. I'm like bicycling industry. That's for me. But as an enthusiast, I knew how to take care of my bicycle, take care of my body. I knew plenty from reading magazines, but I didn't really know the mechanics of the industry. So I took a job at a bike shop, and this is in Milwaukee, Wisconsin, when Schwinn was the brand, and it was Top Dog to everybody. And I was able to get a job managing a Schwinn shop. Well, that Schwinn shop had been around for close to 40 years by then. And we did good things because we were named the bicycle dealer Showcase Magazine, top 100 dealer in the country. (00:28:56): So we were part of 100 dealers out of that time, probably close to 7,000 dealers in the US or in the top 100. So I called up the editor and I said, Hey, man, this is really cool. Can you tell me more? I want to do a press release and let look a media know. And he said, well, this is unique. Usually bike shop managers don't respond. They just get the plaque in the mail and they hang it on the wall. But do you have some sort of business degree or journalism degree or PR degree? I said, yeah, journalism and pr. He goes, oh, and you're in Milwaukee, Wisconsin. Yeah. Well, we we're here in southern California. I'd really like to, if you're interested, if you want to write a monthly column, that would be great. In fact, if you'd like to do more with maybe interviewing some people in the industry, because Trek is in your backyard, we had a lot of companies that were in our backyard, so to speak, between Wisconsin and Chicago and a little further northwest in Minneapolis. (00:29:54): If it could be our man in the ground in the Midwest, that'd be great. Like, oh. So that was a paying gig that I was doing while I was managing the shop. Well, as you can imagine, after a while, I thought, I want to get into that world. Retail's great for learning. But at age 25, newly married, I kind of wanted to expand a bit. So that led to doing more freelance stuff while I was doing a other things wasn't always easy because lost the bike shop job because we had two locations, and Schwinn went bankrupt, got new ownership in 1993. So all of a sudden, Schwinn wasn't top dog anymore. Trek and Giant were starting to gobble everything up. So with that, I realized, well, I've got this journalism agreement in my back pocket. So I was able to continue freelance riding, but because of the affiliation with bicycle dealer, showcase bike, Europe, velo news, bicycle retailer, industry news, that gave me entree into a lot of bike companies. (00:30:52): Trek, for instance, was about 60 miles away. So here I am interviewing the new CEO and owner of Trek learning his story. So I was able to do the same thing with as I did, interviewing all the soccer players to begin with, with all the musicians for a spell. And it really encouraged me to continue that. But I didn't land my first full-time bike journalist job until February of 2007, because it was interesting. It was real catch 22 because of what I was doing, interviewing different people. I caught the attention of a guy that started a company in Madison, Wisconsin called Airborne Bicycles, and he developed a brand that was just like Dell Computers used to be where you would go online, configure it, customize it, and within a week it would be shipped to your house direct. And we did that with bicycles back in 19 98, 99. (00:31:47): Well, huffy caught the, caught our attention, or we caught Huffys attention rather. And they bought us lock, stock and Barrel and moved us to Dayton, Ohio. And I didn't even know where Dayton was. I had to look it up on a map. I didn't head southeast a whole lot. Moved down there, and it was great for about a year. And then the internet bubble burst. So buying things direct wasn't great anymore. People were going to dealers where bicycles, motorcycles, cars, it's always been the case. You don't just hand a box over it like you do electronic goods. So we struggled a bit and I decided to move on. But the beauty of moving on was starting my own bike shop with my wife and as a boutique bike shop kind of a few years before boutique bike shops were a thing, because with most businesses, you have to go grand theater, right? (00:32:42): Best Buy performance bike shops when they're a thing, or you go boutique. But what's nice about boutique is you rent a small space. So you can't really, you fill it pretty quick. You don't have all this space to fill. And being in Dayton, Ohio, we had the good fortune of also being the place where the Wright brothers did their thing first as newspaper guys, printing press, bicycle manufacturers, and then of course aviation pioneers. And when we launched our business in 2003, it was a hundredth anniversary of the Wright Brothers. So because of what I had learned in my bicycle years working for a manufacturer in Waterford, Wisconsin for a spell, interviewing all these SmartyAnts people that were designers and decision makers, we launched our own brand as well. That coincided with that. So my wife and I were doing that for a good solid four years. (00:33:40): But again, because I had this storytelling ability, and I was friends with the new editor of Bicycle Retailer in Industry News, he asked me to do a bi-monthly column on basically the daily trials and tribulations of launching a boutique bike shop and a bicycle brand in a place like Dayton, Ohio. So that was awesome. Doing that for a couple years, again, caught the attention of a smarty pants muckety muck by the name of Tom Richie. And he is one of the pioneers in the mountain bikes and the cycling industry. I caught his attention somehow something that I wrote, I think resonated with Tom. Fast forward to the fall of 2005, and as I came in, there's a bunch of bicycle industry people and American businessmen that are going to Rwanda soon. Do you want to come with me? And I remember thinking number one, where is that? (00:34:38): Why? And then memory serve that. That's where the genocide happened in 1994. So I said, explain. Explain number one, why you're going. Explain number two. Why on earth would you want me to go? Tom, I think caught on the fact that I was well connected in the industry. Tom, like most pioneers of any sort, the Steve job types, so on and so forth, I think he's got quite a cocktail of dyslexic. He's dyslexic, he's got Asperger's, and he has tunnel vision where nothing else matters, but the end goal of innovation, making things happen. And I don't have any of those, but I'm able to see a bigger picture and I'm able to consolidate and bring people together, build a community. So we ended up going in December of 2005 with the goal of seeing if the bicycle industry can help maybe attract bicycle tourism ecotourism to the country because the country had recovered from the genocide, very hilly about the size of Maryland. They have at that time a hundred thousand coffee and tea farmers. (00:35:55): There's a lot of things that they were growing, but because they didn't have railroad lines at the time, they couldn't really get things out affordably, and they're also landlocked. So what we decided when we went there, we were able to get the lay of the land. We took a tour of almost the entire country by mountain bike. The president of the country, whoever was involved with these business people were connected. So we were able to get helicoptered from one side of the country to another drop down in the middle of the jungle, riding our mountain bikes, getting on boats, doing all this stuff, and really getting the lay of the land, which of course was quite an adventure back home in Dayton, Ohio in December of 2005. I'm sure it was snowing, raining. My wife is trying to manage the business with some friends, help two small kids. But it was quite an adventure in those 10 days. What we saw was, yes, the coffee and tea was a big deal. The challenge was the coffee farmers, these families would pick the coffee cherries and to bring them to the washing station took a long time because the roads were horrible. They were rutted. You couldn't really drive those that had bicycles either hand card them with machetes out of wood. So it looked like something Fred Flintstone made (00:37:16): A hand hued tall wooden scooter, or they had these flying pigeons from China that were one speeds that looked like they were from the thirties. (00:37:26): So that was transportation. So because we came from the bicycle world, we thought if we could help them get the coffee cherries to the washing stations, a cargo bike would be great. And this is right around the time cargo bikes were starting to really take off. But in our travels on our bikes, and at the time we were all very, very fit. Tom has always been world-class fit. And here we are riding these lightweight titanium or lightweight steel or custom bikes through the jungle. And you have all these young boys not equating their teens riding alongside, riding alongside us, wearing fake crocs, riding these single speed bikes. Very heavy. Half of them didn't really have pedals. They just had the steel rods that were left over from when the pedals disintegrated, and they're keeping up with us now. They're keeping up with us, they're shouting at us, they're all excited. Here we are, and this is that elevation. (00:38:25): So we thought, okay, well there's some home talent here. Maybe we should consider starting a national cycling academy, something. So when we got back from our trip and everyone celebrated the holidays at home, wherever they came from in the us, we met in Carmel Highlands, south of Carmel, BA Sea, near Monterey in California. A couple months later, we decided, let's go ahead and develop cargo bikes. So with my connections and Tom's connections, we developed working prototype, which eventually became something that once we researched how A to Africa worked and didn't work, we realized these coffee farmers, there'd be co-ops where there'd be, let's say 10 to 20 of them in a co-op. They'd share expenses, they'd share the backbreaking work, but they'd also share in the spoils. When we developed these coffee hauling cargo bikes, we wouldn't just, you don't gift things to Africa because black market's going to intercept it and it's not going to land in the hands of the people that need it. (00:39:38): So we realized with micro loans that we were selling these bikes for our costs for basically the factories cost, which is about 150 bucks because they're made in Asia, and they were sturdy. Wonderful, perfect. So we're able to get a program on the ground that we sold these bikes, and I think we sold upwards of 2000 by 2007, 2008. And Tom's son, Jay was on the ground managing that process. So that was part of taking care of, from our perspective, how can we help the coffee farmers? As we found out later, two of the American businessmen involved were Howard Schultz from Starbucks and whoever the guy was that was leading Costco. So they had plans for volume. They really wanted to help the country, and they had the means and the connections to do it. So on the development side, with some sort of cycling academy, we realized and agreed that wouldn't it be great if we can identify some up and coming cyclists, just like they've done for years in Europe, and to some degree in the US kids, in their teens, they're a junior racer. They go through US Cycling Academy or maybe somewhere in Italy and Spain, where some of the best cyclists have been Belgium, France before that, and identify them young and train them up to represent their country at maybe an Olympics, maybe at a world championship, maybe at the creme de la creme, the true to France. And that would be the ultimate way of vaulting Rwanda in the international spotlight as a country that's healthy, what's more healthy than a cyclist (00:41:24): At that world-class level? So we went back to Rwanda in September of 2006. We put on what was called the Wooden Bike Classic. It was a mountain bike race that ended up in a stadium where 5,000 people were in attendance. And the 19-year-old kid that won it, Adrian Ti was his name, ended up taking 30 ninths in the 2012 London Olympics on the mountain bike team for Rwanda. In fact, he led the Rwandan contingency, the Olympic team. He carried the Rwandan flag into the stadium in London. (00:42:01): And how we achieved that was one of the gentlemen at that, that very timely meeting in Carmel Highlands was Jock Boyer. Jock Boyer was the first American win France to race the Tour de France in 1981. He raced with Bernardo, who was a five-time winner. The first American to win it, of course, was Greg Lamont in 1986. But Jock and Tom go way back to the seventies when they used to race against each other. Jock wanted to become a professional cyclist, and he did, and Tom thought he would be that. But he ended up becoming a very prolific bicycle frame builder, innovator, and one of the innovators and pioneers in mountain biking. So Jock decided, I will move to Rwanda. I will start an academy, and I will take everything. I learned all of his time from his mentors in California when he was first noticed in the seventies, to everyone that he was trained by and raced against in the seventies and eighties and in time, much like we're talking about Fox Stories, Fox Academy, it's one thing to identify a potential cyclist for any sort of level, but he realized he needed to bring mechanics over there. (00:43:24): He needed to not just focus on the young men, but the young women. So as it stands now, there are a handful of academies over in Africa that jocks has established, and there are men's teams and women's teams, and it's something that the foundation has been laid. And I think pre COVID, there was talk of possibly someone from one of those academies actually being part of a Tour de France team.", "token_estimate": 5061, "speakers": ["Gary Boulanger"], "start_timestamp": "00:21:21", "end_timestamp": "00:21:21", "podcast_index": 29, "episode_name": "Ep 29: Gary Boulanger | Make the Jump | FOX Factor‪y‬", "slug": "ep-29-gary-boulanger-make-the-jump-fox-factory", "web_url": "https://www.portsidepro.com/podcast-feed/ep-29-gary-boulanger-make-the-jump-fox-factory", "guest_name": "Gary", "guest_title": "Communications Marketing Manager, FOX Factory", "categories": [], "short_description": "\"Don't be afraid to totally jump into a new industry and be confident that the skills learned translate to other industries.\"", "podcast_length": "44:51"}, {"id": "6ce057d5-9d53-4f6c-a9ff-9f6ab938eaa2", "episode_id": "866bde16-a78a-49c7-89c6-44cc876f737b", "cms_item_id": "68225dfc7bb476527f8c484b", "chunk_index": 8, "content": "Speaker 3 (00:43:51): Oh, wow. This year,\n\nGary Boulanger (00:43:52): Yeah, I believe last year one of them did race Perry Rube. So it is rather interesting to see how someone's invitation, Hey, do you want to go Rwanda? To which I responded, well, if you're buying, I'm flying. Because back then it was a $2,500 round trip ticket and I didn't have that sort of cash, but I'm glad I did. Again, it goes back to what you're saying. When you have an opportunity, there's maybe a bit bewildering on the surface if you say yes, and just kind of explore and see what it means. Because fast forward to where I'm sitting now in California, project Rwanda, as it became known, became such a focus of Tom's, myself and others, that Tom convinced my wife and I to move out to California in May of 2006 to help him with Project Rwanda. Part of the challenge was our bike shop didn't quite make the cut in moving out and getting relocated out here. So (00:44:47): That left us with a bit of debt. It was cool to be a part of Project Rwanda, but we kind of had to go back to square one. But we were out here. Tom had said, well, there's always good opportunity out in California. And he knew that we were made of that sort of tough stuff to make things work. And even though our plans didn't come together, what led to that first full-time journalist job was future publications in the uk. They needed someone in the Bay Area that was willing to become the US editor for a new website called Bike Radar. And they chose me, which was awesome. That helped us kind of get out of debt. That helped me really gain some footing in the bike industry. (00:45:33): Again, it was something that the timing was ideal because I could work from a home office. So even though I had done that on the side, it was kind of like my side hustle with everything else I had done up until that point. It really conditioned me to be doing what most people are doing right now. So when a lot of people were freaking out about working from home, it's actually kind of awesome. So a lot of these experiences have meant that even with the uncertainty, nothing is paved in stone. And from a standpoint of someone like me who I enjoyed being classically trained in journalism and PR back in the eighties, that helped lay a foundation. But as time wore on with 2007 when I took the job at Bike Radar, that's when Twitter started coming along. That's when Facebook started picking up steam. (00:46:31): Instagram was just, it was a few years off, but social media, which was cool at the time, meant that traditional media like myself, our place in the world was starting to deteriorate. What used to be the town square where people would come and talk and share gossip became the general store became Walmart. Well, in time, that became Facebook and everyone's in front of a computer or some sort of gadget. People were allowed to do their storytelling, but it's not quite the same. You get people weighing in with their opinions, that's cool. But if someone's charged with myself writing about my experiences of Rwanda for a magazine at the time, or maybe doing a bike review for Bike Radar or interviewing the owners and CEOs of Trek and specialized on the state of American bicycling, the time that was starting to get wiped out, because then people's attention spans mainly because of Twitter, were being narrowed down to a soundbite. And as you and I talked about earlier, the big push then for marketing was, well, we need to align ourselves with what Facebook and others are doing that we need to message that community, that town square. And what's happened with that too is I remember seeing a billboard where it was General Mills, I believe, a large blue chip company, big company, it's been around for decades. Their marketing, instead of having their own tagline, it was they chose to put facebook.com, general Mills, (00:48:15): They put themselves from a branding perspective behind Facebook. Interesting. That's when I knew things were changing, right?", "token_estimate": 1006, "speakers": ["Speaker 3", "Gary Boulanger"], "start_timestamp": "00:43:51", "end_timestamp": "00:43:52", "podcast_index": 29, "episode_name": "Ep 29: Gary Boulanger | Make the Jump | FOX Factor‪y‬", "slug": "ep-29-gary-boulanger-make-the-jump-fox-factory", "web_url": "https://www.portsidepro.com/podcast-feed/ep-29-gary-boulanger-make-the-jump-fox-factory", "guest_name": "Gary", "guest_title": "Communications Marketing Manager, FOX Factory", "categories": [], "short_description": "\"Don't be afraid to totally jump into a new industry and be confident that the skills learned translate to other industries.\"", "podcast_length": "44:51"}, {"id": "fb09eb16-5c35-4c71-992c-b6172c8e746b", "episode_id": "866bde16-a78a-49c7-89c6-44cc876f737b", "cms_item_id": "68225dfc7bb476527f8c484b", "chunk_index": 9, "content": "Cole Heilborn (00:48:21): You saw the writing on the wall.\n\nGary Boulanger (00:48:23): Yeah, taking back, taking back the message. So as we saw, and as we're still seeing, a lot of publications are either compromising with branded content, so you're not really believing. To me, that's fake news, by the way, but you're not really believing what you're reading. And with companies thinking that their 100% marketing messaging has to be via social media. Well, last I checked our company, we own ride fox.com. Our competitor, technically, if you're following me, is facebook.com. So let's generate content that matters. That means something, that tells the story that's legit, that gets people excited. We'll share it with our competitor with Facebook because their stock and trade is shared content, but we're not going to make it our end all be all. I think it's really important that especially manufacturers do a better job with their own websites, but also do more storytelling with video. (00:49:26): And it's okay to go longer than the 15 to 30 seconds that Instagram stories is telling us it's best for readership and engagement. We do that too. Believe me, we have videos that start off with 10 minutes and we're going to be pulling out those core 15 seconds because we are going to be using different channels to market our message. But I think you had asked me recently when we were chatting, you were a little surprised that I've been advocating for a longer narrative with marketing. And it's something that I think when you look at the print magazines that are doing well, monocle and others, they're going long, right? They're looking for other revenue streams outside of the advertising. You look at Vogue, Marie, Claire, whatever. I do not look at those on a daily basis, but I'm aware of them. And I remember looking through one of those a few years back, and the first 20 pages plus were advertising. (00:50:31): It was all luxurious advertising, which is great. But I think readers deserve more. We want the meat. We want information. If we're going to be away from our computer screens and even our smartphones, we want to be able to drift away from that a bit and really detach. And that's where the long narrative can go. Now, mind you, that long narrative has to be good, if not stellar, if not fantastic. So the fact that I'm advocating long narrative in marketing and branding is not just for anybody. I think it definitely helps that there are several of us on the Fox marketing team that are classically trained in journalism. They're classically trained in storytelling. The fact that we do all of our video in-house, the only thing that we outsource is we use a voice narrator for the voiceover stuff. A few of us tried in-house, but a professional didn't work. (00:51:28): Yeah, a professional is so good, so amazingly good. But that's it. So that was our charter is how can we do with our staff? And our staff is not big. There's 10 of us in the power vehicle group marketing with our staff, run events, run our campaigns, and we make full use of the eyeballs at YouTube, Google search. It's inevitable. That's where people are going. But what we do is we drive people back to ride fox.com because again, we own that and that's where our livelihood lies, our products, our descriptions, our videos, and so forth. And it's been interesting because of the things that I experienced with being open-minded to different job opportunities, our career pivots, it's made moving forward with the challenges we face starting March 16th, when we were told in Santa Clara County, I think we're the first in the country to be told to shelter in place, and I think we turned to each other. (00:52:34): And so what does that mean? I mean, we're going home. Do we bring our laptops and our, so we're going home. We need to bring our monitors and everything. And to be able to pivot in a digital world has been helpful. And like we mentioned earlier, with our manufacturing being shuttered for a time being, that was a super huge challenge because we also had to throttle back our storytelling. We throttled back the introduction of Fox Academy until June 9th because we knew this would create instant engagement. And nothing's worse than reading about something online that you can't have because your competitor always going to be there to say, well, we got this. And people seemed with their stimulus money too. People seem to be eager to spend it in good ways. And our demographic, they play outdoors and they're not afraid to spend money. They're risk takers. (00:53:37): They work hard, they save up their money, and they're not as, impetuous isn't the right word. They're not just going to respond. They're not going to have a knee-jerk reaction to going out and buy something. Like most people that are buying something with technology, especially moving parts like ours, they're going to research it. So that's why when we first came out with Fox Academy, it was, alright, here's how a shock works, the various parts of a shock. And we just came back a couple of weeks ago from introducing our Jeep use case campaign, which essentially breaks down what people do with their Jeeps. A lot of times people would always assume, oh, someone has a Jeep, they're going to go rock crawling. Well, that's not for me. Or they're going to go racing in the desert. Well, that's definitely not for me. You see a lot of Jeeps, much like you see SUVs or even bulldozer trucks driving along on the highway. (00:54:39): It's all kinds of use. But we realize that people were a little confused as to what to do with some of the components we offered for their various levels of beeping. And we went out in the desert, had some media, we worked with four wheel parts based on there, and we created some content. The media were able to get behind or they weren't able to get behind the wheel. We wanted them to experience it because you have much more interesting seat of the pants experience when you're not behind the wheel. Because when you're behind the wheel, you're in charge. You don't quite feel everything. You know this from being a passenger in the backseat or even the passenger in the front seat. Everything feels different. You're always pushing for that fake brake pedal. You always feel like someone's going too fast. So we were able to provide this experience, and that was our first time being out and about in months of all these events being canceled, we did all the COVID protection, we had all the protective gear and all that, and it was fun. (00:55:34): It was hot in the desert, 108, but it was a dry heat. So there's a difference, a little more manageable. But it was fun to actually see hardcore off-road journalists have fun, get to experience something. Because what we took from that too is we got a much better understanding of how the end user is going to experience and respond to something. We served a lot of different needs on that quick trip down to Orange County. We're hoping to do some more of that. It's just there's so much going on with these wildfires, shelter in place down here where we are in California, there's still quite a bit of back and forth thing on just with the number of cases, a lot of mixed signals on how people should be behaving, how people should be operating. It's quite a testament to Google and Facebook and others where they said, we don't expect our employees to come back until next summer. Let's let everything fall into place. And it's a bit easier for our digital companies. It's a challenge for them is they own a lot of real estate and there's a lot of empty offices that they're struggling with. (00:56:50): A lot of people working from home. I think people have been wanting those that have been wanting to have a life balance and work from home that's been a benefit for them. We definitely see it here. My wife runs a rather sizable coffee shop in downtown Mountain View. They've not been closed for a day since this happened, and they've been able to make it work. So everyone has their own response to COVID, their own response to even how they message things. No one wants to keep hearing in these trying times or due to COVID. We get it. (00:57:23): Yeah. Part of it is, as marketers and brand ambassadors and storytellers, we do want to be uplifting to people. We all know that people need to take care of themselves. And being outside, I think personally has been very healthy for my family as cyclists, motorcyclists and other people seem to feel the same way. And I know that not everyone's been following protocol when it comes to the size of groups getting together. Sturgis was quite interesting, the fact that you still had tens of thousands of people. The fact that the Sturgis city Council asked its citizens of which they're only not quite 6,000 months ago, folks, what do you think? Should we do this or not? This is the 80th anniversary, right? Talk about branding the citizens. I think 60% of them said, yeah, yeah, we should do this. But there's a lot of voicing against it. (00:58:21): But then the Sturgis organizers met with the city council and realized people are coming, whether we're inviting them or not, 80 years of tradition. So what Sturgis did is they pivoted and they messaged people that were planning to come saying, you know what? Come, it's not going to be the same. We're not going to be holding huge concerts of Snoop Dogg in the Buffalo Chip like we've done. But by the way, when you do come out, just as a reminder, this is awesome riding out here. Come spend a few hours downtown, do your thing, but pop forth. Go ride the hills. And from what I can tell, it was good. But that's one of those situations where people don't realize that Sturgis is a town. They know it as this event, Coachella, same sort of thing. And you've got these regions that are now known for these events. (00:59:14): And that's where I think the biggest challenge has been is we're a society that is very community focused and it's always been healthy. And we have these beautiful festivals. We have these beautiful gatherings that have been thwarted for now. And I think that's been sending people into a bit of a tailspin. And we have a lot of social unrest, a lot of civic unrest. We have all kinds of political unrest. It's always been a challenge in a presidential election year. And that's some sort of branding too, because you have Democrats versus Republicans too bad. A lot of it is us versus them versus here's what we can do. It's what they're doing wrong. And I've worked for some companies in the past where we would pick out our competitors' weaknesses. And I never thought that was really wise. The whole Coke versus Pepsi thing, I think it's best to as individuals, but mainly as corporations, to highlight strengths, play on them. (01:00:19): And that's where the long narrative goes. If you have decades of content to share, maybe to repurpose in video form, in narrative, long narrative form, I think companies that have the benefit of having, not brand ambassadors per se, but athletes. I think that's why Red Bull has reigned supreme. I'm a big fan of Formula One and Moto gp, and it's interesting to see Monster and Red Bull just do so much. Monster doesn't do a whole lot of storytelling. Monster is kind of like Microsoft. They sell a lot of stuff. They get out there, but it's kind of boring. Apple is like Red Bull. They go long. They have these relationships, affiliations, and you just can't help yourself. You want to learn more. You want to be a part of that world. And Red Bull specifically has really captured my fancy, and what's interesting and very telling is when you go to Red bull.com, you're getting nothing but storytelling. You have to scroll for a long time to actually get down to a portion of the site that brings you anywhere near the product.", "token_estimate": 2972, "speakers": ["Cole Heilborn", "Gary Boulanger"], "start_timestamp": "00:48:21", "end_timestamp": "00:48:23", "podcast_index": 29, "episode_name": "Ep 29: Gary Boulanger | Make the Jump | FOX Factor‪y‬", "slug": "ep-29-gary-boulanger-make-the-jump-fox-factory", "web_url": "https://www.portsidepro.com/podcast-feed/ep-29-gary-boulanger-make-the-jump-fox-factory", "guest_name": "Gary", "guest_title": "Communications Marketing Manager, FOX Factory", "categories": [], "short_description": "\"Don't be afraid to totally jump into a new industry and be confident that the skills learned translate to other industries.\"", "podcast_length": "44:51"}, {"id": "203e12a7-cf60-4b7c-82ed-b44fa316b2a9", "episode_id": "866bde16-a78a-49c7-89c6-44cc876f737b", "cms_item_id": "68225dfc7bb476527f8c484b", "chunk_index": 10, "content": "Cole Heilborn (01:01:34): Yeah, it's interesting for a lot of companies, it's not about the product, it's about the culture, the lifestyle, the brand around it all. It's about the people around the product. And when you see big brands like Red Bull doing that, you're talking about writing on the wall. When you saw that billboard, it's the same thing.\n\nGary Boulanger (01:01:59): Oh yeah. And it all goes down to leadership. The owner of Red Bull, he knew a long time ago, one thing to have a product. He knew in time that he was going to get competition. (01:02:13): I mean, it's inevitable. You do something really good and other people are like, there's money in that. That's sweet. There's a lot of money in that. That's doubly sweet. But to go out and to capture the fancy of younger people, older people, like me people in between the fact that it's so exciting to see what people can do with GoPro, the fact that we could literally see what people were doing right with the action sports. Something that I think has really turned things around to society as spectators to participants. And I think that's one thing that's been probably the most healthiest from social media combined with what Red Bull has been fostering and what companies like GoPro have been providing and others like GoPro is people are going, I could do that. And again, it goes back to me in the seventies being excited about watching the Green Bay Packers, but wanting to be more of a participant, less of a spectator. And obviously not everyone's going to make it to the NFL and I did not make it to Major League Soccer, but that wasn't my goal. The fact that we identify with this brand and the Green Bay Packers, they're probably one of the strongest brands out there, major league sports, and it's still owned by the community. I think that's super cool. The last of the nonprofits to be a major league sport. (01:03:40): So that's it in a nutshell as far as branding from early days to current situation on why traditional storytelling probably matters more than any other time right now.", "token_estimate": 519, "speakers": ["Cole Heilborn", "Gary Boulanger"], "start_timestamp": "01:01:34", "end_timestamp": "01:01:59", "podcast_index": 29, "episode_name": "Ep 29: Gary Boulanger | Make the Jump | FOX Factor‪y‬", "slug": "ep-29-gary-boulanger-make-the-jump-fox-factory", "web_url": "https://www.portsidepro.com/podcast-feed/ep-29-gary-boulanger-make-the-jump-fox-factory", "guest_name": "Gary", "guest_title": "Communications Marketing Manager, FOX Factory", "categories": [], "short_description": "\"Don't be afraid to totally jump into a new industry and be confident that the skills learned translate to other industries.\"", "podcast_length": "44:51"}, {"id": "e4f1c18f-59e7-4f85-9af3-55a6b3c60d10", "episode_id": "866bde16-a78a-49c7-89c6-44cc876f737b", "cms_item_id": "68225dfc7bb476527f8c484b", "chunk_index": 11, "content": "Cole Heilborn (01:03:55): Yeah, I love it. My last question for you is a lot of people define themselves by their job or their career, and I have a feeling that you maybe don't feel the same way because you've done so much and you've been very willing and comfortable to go with the flow. What have you learned about yourself by not being so attached to whatever you were doing at the current time?\n\nGary Boulanger (01:04:23): I've learned to be open-minded growing up, and it's not so much, maybe it's a Midwest thing, I don't know. It's very endearing, but to be not narrow-minded, but solely focused on one particular career path. That used to be the case. My dad and my father-in-law both retired from, my dad retired from Proctor and Gamble, and my father-in-law retired from Shell Oil after 30 some years combined or each full pension. They made good money once they moved up the ladder, and that was great. Neither one of 'em really liked their jobs, but they provided it for their families. And I can't call that that narrowly focused and that's awesome. But the way society has evolved in this technical age, starting with personal computing and software in the eighties to the internet in the nineties to social media in the two thousands, that really doesn't apply anymore. And I had this weird feeling in the eighties. Like I said, my narrow focus was music journalists Rolling Stone, but I wasn't willing to make that jump. So when I pivoted toward bicycles, I'm glad I did because that led me to so many opportunities. But even at a certain point, after 24 years in the bicycle industry, in late spring of 2015, I woke up and I just didn't feel it anymore, (01:05:51): Which was really weird because I was the editor in chief of a bicycling magazine. You're supposed to feel it. You're supposed to exude it, you're supposed to evangelize it, you're supposed to. If you were to poke my skin, I'd bleed, bicycling. I mean, I was all in, right? But I wasn't feeling it anymore. And that's when I realized, all right, I'm not quite 50. I think I was 49 at the time. I want to do something else. So I did a self-audit like I did back in 19 90, 91. What do I really want to be doing right now? Motorcycling. (01:06:24): I'm an enthusiast. I ride a lot. Do I know it technically just like the bicycling that many years before. No, but I can learn that willingness to learn, not to shut down your capacity for learning once you graduate high school or college tech school or whatever, but always be open and have that confidence that if given the opportunity, you could fill up that void, that knowledge void and become an expert. And I did that with cycling, and I thought I could do this with motorcycling. And I'm really glad I did with hindsight because my storytelling and journalism skills, but also the fact that I didn't mind working retail. Not everyone wants to work retail. I don't recommend it to those that are not into it because it can be really hard, but you learn so much, you're literally on the front lines. (01:07:15): And that's what I learned at the Schwinn dealership back in 1991 when I first started. So I ended up taking a position as managing a motorcycle clothing store in San Francisco in the spring of 2015. They would show motor GP every Sunday it was playing. So that's how I discovered the place. And that was cool. But San Francisco has been a hotbed of motorcycling for decades. It's an epicenter. So people were literally, by my working there, I would go in and I would be working, and I have my staff and the brand was De and that's who sponsors Valentino Rossi, one of the greatest motorcyclists of all time. So people knew the brand. So I'm kind of marinating myself in all this cool motorcycle culture, but people were coming to where I was working and sharing all their knowledge, bragging about the latest Ducati purchase, asking me about Lorenzo versus Ducati, and as far as the championship was going, all these things. So I literally sponge it all up just like I did that many years before with bicycling. And that caught the attention of an editor of Cycle World Magazine. And he asked me to cover an assignment nearby a product launch. And I said, of course, of course. I was not the best motorcyclist compared to the other", "token_estimate": 1069, "speakers": ["Cole Heilborn", "Gary Boulanger"], "start_timestamp": "01:03:55", "end_timestamp": "01:04:23", "podcast_index": 29, "episode_name": "Ep 29: Gary Boulanger | Make the Jump | FOX Factor‪y‬", "slug": "ep-29-gary-boulanger-make-the-jump-fox-factory", "web_url": "https://www.portsidepro.com/podcast-feed/ep-29-gary-boulanger-make-the-jump-fox-factory", "guest_name": "Gary", "guest_title": "Communications Marketing Manager, FOX Factory", "categories": [], "short_description": "\"Don't be afraid to totally jump into a new industry and be confident that the skills learned translate to other industries.\"", "podcast_length": "44:51"}, {"id": "6fe71738-981b-4d18-854d-99ee75aaeca8", "episode_id": "866bde16-a78a-49c7-89c6-44cc876f737b", "cms_item_id": "68225dfc7bb476527f8c484b", "chunk_index": 12, "content": "Speaker 3 (01:08:33): World-class\n\nGary Boulanger (01:08:33): Journalists. So of course I was self-conscious about that. But I went into it like, I'm here representing Cycle world, so I must be good. (01:08:41): And I just took a different approach. We did some rides. It was fun. I felt nervous. I shouldn't have been, it was no big deal. But I was able to interview the chief technology officer. I had FaceTime with the CEO. I was able to use those journalistic and storytelling skills to go deeper. And I thought that my overview of that experience played well for what psych world needed. My editor was happy following year. I signed on as senior editor, and I spent a good year and a half with the Cycle World organization. And I had access to everybody, much like I did years before with cycling when I was enjoying cycling, rather sponge it all up. But it was at a time where Bonier, who owned Cycle World and other titles, they were shutting down print left and, and they're even combining digital left and, and that was super, super hard. (01:09:33): And I really was getting the itch to take what I learned, but also I don't want to be pigeonholed with just motorcycling. I mean power vehicle as a late comer to Formula One, seeing what was happening in the side-by-side world, realizing that just over the hill, there's a manufacturer called Fox that would be super cool. A friend of mine that worked at Ducati said, Hey man, they've got an opening. And I said, really? And I've not had the best luck doing interviews in the past. It was always word of mouth. I rarely had to fill out and create a resume. And I did not interview well over the phone, (01:10:10): Unfortunately. And I just thought, great, I would love to do this, but it looks like it's not to be. And somehow it was meant to be. And we've got a bit of a ragtag group of people that kind of come from all different industries. But our boss came from Apple and he knew how to identify all the various players and how we all fit in. And halfway through last year, I started January 2nd of 19, halfway through last year, we were also tasked with doing the marketing for El Cajon, so our trucking off road, all the big boys stuff. And that was a challenge and a chore because I was just warming up with learning the ins and outs, nuts and bolts of UTV snowmobile,", "token_estimate": 584, "speakers": ["Speaker 3", "Gary Boulanger"], "start_timestamp": "01:08:33", "end_timestamp": "01:08:33", "podcast_index": 29, "episode_name": "Ep 29: Gary Boulanger | Make the Jump | FOX Factor‪y‬", "slug": "ep-29-gary-boulanger-make-the-jump-fox-factory", "web_url": "https://www.portsidepro.com/podcast-feed/ep-29-gary-boulanger-make-the-jump-fox-factory", "guest_name": "Gary", "guest_title": "Communications Marketing Manager, FOX Factory", "categories": [], "short_description": "\"Don't be afraid to totally jump into a new industry and be confident that the skills learned translate to other industries.\"", "podcast_length": "44:51"}, {"id": "03ee9c96-b623-4fed-a1bd-1bb42980c51a", "episode_id": "866bde16-a78a-49c7-89c6-44cc876f737b", "cms_item_id": "68225dfc7bb476527f8c484b", "chunk_index": 13, "content": "Speaker 3 (01:10:56): Side\n\nGary Boulanger (01:10:56): By side motorcycling. I had down, I was asked just to focus primarily on motorcycling marketing for the first part of the year. No brainer. That was awesome. That was fun. I was just learning the mechanics of working for a corporation. Again, it had been a long time. And what was super cool about is that truck and offroad division has just soared as far as business dealings, aftermarket eyeballs, OEM partners, everything else. I mean, mind you, our power sports side does well, but the truck and off road is just exploding. So I'm glad we're given the opportunity to be working with that because that actually adds a lot more to my plate with opportunities to do some storytelling. (01:11:43): When you start talking Baja and you're looking at these images and videos of King of the Hammers where people are doing things in trucks that no mere mortal can even fathom, that's super cool. Those are great assets to capture from a marketing standpoint. And that's also where we get a lot of our fan base, so to speak. The last couple of King of the Hammers and Seima last year, I kept running into the same contingent from Australia, and they would take their holiday, they'd come over here, they'd do these races, they'd go to the events, and for them it was about buying Fox merch. They can't buy it in their homeland, and if they could, it would be really expensive to get it from us. So when they come here, they just stock up and they're just, they're whipping on a hundred dollars bills buying all this merch. (01:12:31): And as a newbie last year at Fox, I said, why are you guys so ggo over Fox? And I was able to just get it straight from the horse's mouth, what it meant to them. My father and I did this, my mom and I, our whole family did this much. And going back to the origin story with Bob Fox, the motocross scene and the motocross community has always been entire family. You've got mom and dad and the kids. They're all out there doing their thing right at the races out in the desert or at the track. And that's something that I realized that if we can bottle it up and capture that, and if we could reflect that in what we do with number one, our website, and now when you go to Ride Fox, most of what you're seeing on what we call our landing pages for our various categories, we've totally refurbished based on feedback we've received, based on our experiences out in the field. (01:13:22): The fact that we've been able to get behind the bars, behind the wheels of most of the vehicles for which we make suspension, you get a true understanding of why people get excited to get jazzed about things. I don't know if people are that excited about the new iPhone. They sometimes can be, but after a while, that wears off. So we have a bit of a responsibility to make good on the promise that this is going to be awesome. You're going to have fun. Please lay hands on it, make it your own, and so forth. And I think that's the same. I can say with my career, I've not allowed my career to be left to the hands of others. I mean, even when Tom Richie had promised to help us move our business out here, and that fell through. I mean, that kind of left us a bit destitute financially, but it was time to pivot and time to move the family out west and great things have happened, and I wouldn't be sitting here talking to you, I don't think, if I hadn't said yes to Tom's proposal to go to Rwanda and then move out here. (01:14:25): Right?", "token_estimate": 878, "speakers": ["Speaker 3", "Gary Boulanger"], "start_timestamp": "01:10:56", "end_timestamp": "01:10:56", "podcast_index": 29, "episode_name": "Ep 29: Gary Boulanger | Make the Jump | FOX Factor‪y‬", "slug": "ep-29-gary-boulanger-make-the-jump-fox-factory", "web_url": "https://www.portsidepro.com/podcast-feed/ep-29-gary-boulanger-make-the-jump-fox-factory", "guest_name": "Gary", "guest_title": "Communications Marketing Manager, FOX Factory", "categories": [], "short_description": "\"Don't be afraid to totally jump into a new industry and be confident that the skills learned translate to other industries.\"", "podcast_length": "44:51"}, {"id": "5098129c-9fde-4ea9-9bd8-7b5e29b84a7e", "episode_id": "866bde16-a78a-49c7-89c6-44cc876f737b", "cms_item_id": "68225dfc7bb476527f8c484b", "chunk_index": 14, "content": "Cole Heilborn (01:14:26): Yeah. Yeah. It's funny how it all comes together. You only realize that when you look backwards looking forwards, you can't see where it all goes, but you look back and you're like, oh, yeah, I see how that all\n\nGary Boulanger (01:14:36): Works. Yeah. It's funny when you mention it like that. I try really hard if someone ever gets a quick overview of maybe my career path. I have a lot of friends that are really struggling right now, a couple of them that have never lost a job before. So now they lost their job in January, and here they are looking for work, and the odds of finding something are really, really, really low. But I will share that. I'll say, well, with foresight, use the benefit of hindsight to understand that maybe if you take that personal audit and look at career, what does a career really mean in this day and age? What should it mean? What could it mean? But also, don't be afraid to totally jump into a whole new industry and be confident in the fact that the skills one learns in a different industry do apply. (01:15:38): And we should all remind ourselves that Steve Jobs lasted one semester at Reed College, and that Bill Gates decided to bag off Harvard, and at Gary Erickson at Cliff Bar, I think he got his AA from a community college in the East Bay of California. They've all done well for themselves. So sometimes we get too hung up on the fact that we need continual education, formal education in order to make it in this world. I think maybe COVID is going to shake things up where you're going to have someone that really brings something strong to the table and know they don't have a certain pedigree, but they've got grip, they have action, they have life experiences of failing really big, stumbling really hard, but getting up again, and I think that is what society needs as a whole, but also corporate world. I think we're going to see more of that as well. People that aren't just proud of their accomplishments, but are resilient.\n\nCole Heilborn (01:16:38): Right. Proud of their failures", "token_estimate": 517, "speakers": ["Cole Heilborn", "Gary Boulanger"], "start_timestamp": "01:14:26", "end_timestamp": "01:16:38", "podcast_index": 29, "episode_name": "Ep 29: Gary Boulanger | Make the Jump | FOX Factor‪y‬", "slug": "ep-29-gary-boulanger-make-the-jump-fox-factory", "web_url": "https://www.portsidepro.com/podcast-feed/ep-29-gary-boulanger-make-the-jump-fox-factory", "guest_name": "Gary", "guest_title": "Communications Marketing Manager, FOX Factory", "categories": [], "short_description": "\"Don't be afraid to totally jump into a new industry and be confident that the skills learned translate to other industries.\"", "podcast_length": "44:51"}, {"id": "1809b792-10f6-4bff-8adf-95b433a0c6ca", "episode_id": "866bde16-a78a-49c7-89c6-44cc876f737b", "cms_item_id": "68225dfc7bb476527f8c484b", "chunk_index": 15, "content": "Gary Boulanger (01:16:39): Too. Yeah, and gosh, I mean, talk about resilience right now. I need a triple dose of it every day. I think everyone's just kind of bubbling at the surface or right below the surface going, well, I'm just going to keep pushing for today. I can't make any plans for the weekend. That's fine. Weekend's going to arrive and times will improve. But it's been super solid and it's been good to look back on it and kind of go, that's why that happened. That's all hindsight thing, aha moment where, okay, I was pushing for that, not realizing that something better was about to happen and opening yourself up to that.\n\nCole Heilborn (01:17:15): Yeah. Well, you've said it better than I could have ever hoped you would've said it, but I appreciate you sharing your story. I feel like I need to write down your whole career history kind of a lot to take and process and put into a timeline, but thank you so much for spending the last bit of time here with us sharing. It's been a lot of fun.\n\nGary Boulanger (01:17:37): Yeah, my pleasure. I appreciate it, Cole.\n\nCole Heilborn (01:17:39): Absolutely. If people want to find you, if they want to follow along with the work you're doing or Fox, where can they go?\n\nGary Boulanger (01:17:47): Probably the best thing would be ride fox.com. I mean, most of what's going on there is the handiwork from myself and my team. It's been fun. I mean, I'm on LinkedIn as well. I actually have been pulled away from social media the last few months. That was one of those self audit things where I just thought, I really don't need to be filling my head with what everyone's thinking and doing. It's not a slight on any of my friends, family, or extended followers. I have that many followers. But I think it's been good. I think it's been good to have clarity.\n\nCole Heilborn (01:18:20): Yep. All right. Well, sounds good, Gary. Thanks so much and have a good rest of your day.\n\nGary Boulanger (01:18:24): Thanks, Cole.\n\nCole Heilborn (01:18:25): Alright, thank you. Thank you for listening to this episode of the Backcountry Marketing Podcast. If you enjoyed today's episode or learned something new, please consider leaving us a review on Apple or sharing this with a friend.", "token_estimate": 559, "speakers": ["Gary Boulanger", "Cole Heilborn"], "start_timestamp": "01:16:39", "end_timestamp": "01:18:25", "podcast_index": 29, "episode_name": "Ep 29: Gary Boulanger | Make the Jump | FOX Factor‪y‬", "slug": "ep-29-gary-boulanger-make-the-jump-fox-factory", "web_url": "https://www.portsidepro.com/podcast-feed/ep-29-gary-boulanger-make-the-jump-fox-factory", "guest_name": "Gary", "guest_title": "Communications Marketing Manager, FOX Factory", "categories": [], "short_description": "\"Don't be afraid to totally jump into a new industry and be confident that the skills learned translate to other industries.\"", "podcast_length": "44:51"}, {"id": "5db0c371-b831-4bb2-a5ff-81768a3edc66", "episode_id": "b52ccfcd-175d-4353-bfe6-3329bcfefa6b", "cms_item_id": "68225dfc7bb476527f8c4824", "chunk_index": 0, "content": "Cole Heilborn (00:03): Welcome to Brand Story, the podcast where we interview individuals who are creating and designing the brands we interact with every day. My name is Cole, he Warren, and today I'm here with Sean Fields, the Vice President of Brand at Gear Aid. How are you doing?\n\nSean Fields (00:14): I'm doing well.\n\nCole Heilborn (00:16): Good to see you.\n\nSean Fields (00:16): Thanks for having me.\n\nCole Heilborn (00:17): Yeah, absolutely. Tell me about Gear Aid. What do you guys do?\n\nSean Fields (00:21): We primarily make care and repair products for outdoor gear. We also make adventure tools, which is kind of things to make your outdoor experience better. Knives, lights, pair of cord, things like that. But historically we've been, our core has been about care and maintenance for your jackets and sleeping bags and anything that you would use in the outdoors.\n\nCole Heilborn (00:42): Okay, okay, gotcha. So you guys are all about getting people back on the road, back into the woods and get people back into the adventure after unfortunate snag or terror.\n\nSean Fields (00:53): Correct? Correct. Cool. I call it the pit stop company because our goal is to, one, educate people about how to be able to do things themselves and maintain their own gear, which really provides that sustainability and elongates their gear life. But also we want people to be getting outside Our why is basically champion renewal and we feel that the outdoors is one of the best places to do that.\n\nCole Heilborn (01:22): Tell me a little bit about yourself. What does your job look like? What do you do in the day to day?", "token_estimate": 405, "speakers": ["Cole Heilborn", "Sean Fields"], "start_timestamp": "00:03", "end_timestamp": "01:22", "podcast_index": null, "episode_name": "Ep 2: Sean Fields | Sustainability in the Outdoor Industry | Gear Aid", "slug": "sean-fields-sustainability-in-the-outdoor-industry-gear-aid-2f945", "web_url": "https://www.portsidepro.com/podcast-feed/sean-fields-sustainability-in-the-outdoor-industry-gear-aid-2f945", "guest_name": null, "guest_title": null, "categories": [], "short_description": "In this episode, I sit down with Sean Fields from Gear Aid and talk about what sustainability in the outdoor industry really means. Many brands have built upon that idea, but what does it actually mean?", "podcast_length": "44:24"}, {"id": "6076b24f-fad5-4678-a7f7-1a9e8748290b", "episode_id": "b52ccfcd-175d-4353-bfe6-3329bcfefa6b", "cms_item_id": "68225dfc7bb476527f8c4824", "chunk_index": 1, "content": "Sean Fields (01:28): Day to day? Good question. We're a small company. We have less than 50 employees. My role is over product development and marketing. I have two great team leads in that, Ray Klein and Charis. Ola. Ray is in charge of the product development and design. He's our design director. And then Charis is our marketing director, so she's the champion of that team. So I'm fortunate enough to have them, I don't want to say below me, but essentially running those teams and then I help kind of guide it from a brand standpoint. And then I also work with other departments within the organization specifically about things that are brand oriented, so hr, employee handbooks, events, things like that with sales, like how we present ourselves when we show up in retail or in sales meetings and giving them tools, even just in the warehouse, how we interact with our staff there and how we get them engaged with the brand.\n\nCole Heilborn (02:37): Okay. And so when you're looking at the company as a whole, you're looking at pieces of it, but all those pieces kind have to fit underneath this umbrella, and that's this brand that you're talking about. How do you see those different pieces and then how do you see them all fitting together?", "token_estimate": 313, "speakers": ["Sean Fields", "Cole Heilborn"], "start_timestamp": "01:28", "end_timestamp": "02:37", "podcast_index": null, "episode_name": "Ep 2: Sean Fields | Sustainability in the Outdoor Industry | Gear Aid", "slug": "sean-fields-sustainability-in-the-outdoor-industry-gear-aid-2f945", "web_url": "https://www.portsidepro.com/podcast-feed/sean-fields-sustainability-in-the-outdoor-industry-gear-aid-2f945", "guest_name": null, "guest_title": null, "categories": [], "short_description": "In this episode, I sit down with Sean Fields from Gear Aid and talk about what sustainability in the outdoor industry really means. Many brands have built upon that idea, but what does it actually mean?", "podcast_length": "44:24"}, {"id": "e31f229a-7176-4e7e-858a-88d1aae70a7b", "episode_id": "b52ccfcd-175d-4353-bfe6-3329bcfefa6b", "cms_item_id": "68225dfc7bb476527f8c4824", "chunk_index": 2, "content": "Sean Fields (03:01): The brand that we are building, historically, it's been around for 35 years, but it was a business model that had brands underneath the overarching business. And so four years ago, we made the decision that was just too much and we decided to say, Hey, we're going to collapse all these brands into one. That gave us an opportunity to really define what Gear Aid was. All the pieces worked together, just like the parts of the body or elements of your household, they all work together to make your home or who you are. And so whether that's in sales or in product development, marketing, finance, someone who greets people at the front door, shakes a hand when we're shipping stuff out, they all work together to be an impression on the brand. And so you want that to be as consistent as possible and educate people with the tools that makes their job easier, but also gives them the ability to leave that impression no matter where they're at.\n\nCole Heilborn (04:11): So back up a little bit. You said you had four different brands underneath the one. Where did those come from and how did you guys end up to a place where you decided to dissolve those and move forward with the one", "token_estimate": 302, "speakers": ["Sean Fields", "Cole Heilborn"], "start_timestamp": "03:01", "end_timestamp": "04:11", "podcast_index": null, "episode_name": "Ep 2: Sean Fields | Sustainability in the Outdoor Industry | Gear Aid", "slug": "sean-fields-sustainability-in-the-outdoor-industry-gear-aid-2f945", "web_url": "https://www.portsidepro.com/podcast-feed/sean-fields-sustainability-in-the-outdoor-industry-gear-aid-2f945", "guest_name": null, "guest_title": null, "categories": [], "short_description": "In this episode, I sit down with Sean Fields from Gear Aid and talk about what sustainability in the outdoor industry really means. Many brands have built upon that idea, but what does it actually mean?", "podcast_length": "44:24"}, {"id": "6479b061-30bf-4da4-a635-f6df4f98110a", "episode_id": "b52ccfcd-175d-4353-bfe6-3329bcfefa6b", "cms_item_id": "68225dfc7bb476527f8c4824", "chunk_index": 3, "content": "Sean Fields (04:25): We used to be called Mcne Corporation, and Dwayne and Nancy Mcne founded the company in 1981. So they were always interested in looking at new products. They kind of landed into care and repair back in the day with kind of outdoor rain suits, and they needed to develop products that would repair those. So that's where that kind of all started. Building the different brands, house of Brands was kind of the thing back then. And so Gear Aid was one of the brands and RevX, or not, sorry, not revive, X Gear Aid, M Essentials, which was a dive specific. There was Outgo, which was a brand specifically around towels. We had Mcna tactical. So all of those played together in different categories, but when we were purchased, that was something that was looking at the staff that we had and the resources we had to run all those brands, you need a lot of resources and a lot of money. (05:39): So that was something that was a recommendation that we did and we moved forward with. So that that's been a really rough transition to do that and to go from more of a B2B behind the scenes global brand into something that's very in your face. And we want to expand that. The name, the impression, what we do, because consumers demand it. It's becoming more and more important that consumers understand the companies that they're purchasing their goods from. So we've done a lot of work and we're still doing a lot of work to build a brand. Just the rework of product was a massive undertaking. And while we did that, we did a huge slim exercise to narrow up the product offering, get rid of duplicates so that then we can scale up and go bigger.\n\nCole Heilborn (06:41): And how involved have you been in that process, the trimming and the reshaping of the company's brand?", "token_estimate": 447, "speakers": ["Sean Fields", "Cole Heilborn"], "start_timestamp": "04:25", "end_timestamp": "06:41", "podcast_index": null, "episode_name": "Ep 2: Sean Fields | Sustainability in the Outdoor Industry | Gear Aid", "slug": "sean-fields-sustainability-in-the-outdoor-industry-gear-aid-2f945", "web_url": "https://www.portsidepro.com/podcast-feed/sean-fields-sustainability-in-the-outdoor-industry-gear-aid-2f945", "guest_name": null, "guest_title": null, "categories": [], "short_description": "In this episode, I sit down with Sean Fields from Gear Aid and talk about what sustainability in the outdoor industry really means. Many brands have built upon that idea, but what does it actually mean?", "podcast_length": "44:24"}, {"id": "1573dda1-3c50-41f5-b83e-d7f2c993a211", "episode_id": "b52ccfcd-175d-4353-bfe6-3329bcfefa6b", "cms_item_id": "68225dfc7bb476527f8c4824", "chunk_index": 4, "content": "Sean Fields (06:50): All of us had that opportunity. So I had one perspective. We hired a president to come onto the, I think it was about two years ago, Clark Campbell. And he's been really a go getter in that respect from Seattle and from outdoor research. So he's got an ability to really see the company in a different way and to push us in new directions that really elevate us from a business standpoint. And so he and I work together and I say we partner together. Sometimes it's battles, but honestly that's kind of our roles is that he's so gifted in operations and product management and even navigating large sales programs. And I come more from the brand side and design and the emotive side. So we balance each other out, and I appreciate his perspective on things and he does mine. So I think we work well together in that regard and keep pushing the brand even through really hard conversations when we're have different ideas of what might be the solution.\n\nCole Heilborn (08:08): Yeah. How would you describe a brand in a simple way? Because it can be a complicated thing. It's got a lot of moving parts. If you had to boil it down, what is it?", "token_estimate": 291, "speakers": ["Sean Fields", "Cole Heilborn"], "start_timestamp": "06:50", "end_timestamp": "08:08", "podcast_index": null, "episode_name": "Ep 2: Sean Fields | Sustainability in the Outdoor Industry | Gear Aid", "slug": "sean-fields-sustainability-in-the-outdoor-industry-gear-aid-2f945", "web_url": "https://www.portsidepro.com/podcast-feed/sean-fields-sustainability-in-the-outdoor-industry-gear-aid-2f945", "guest_name": null, "guest_title": null, "categories": [], "short_description": "In this episode, I sit down with Sean Fields from Gear Aid and talk about what sustainability in the outdoor industry really means. Many brands have built upon that idea, but what does it actually mean?", "podcast_length": "44:24"}, {"id": "529c777b-ee5d-4be7-8ff9-9f63a87b2099", "episode_id": "b52ccfcd-175d-4353-bfe6-3329bcfefa6b", "cms_item_id": "68225dfc7bb476527f8c4824", "chunk_index": 5, "content": "Sean Fields (08:21): It is so many different parts. Historically, the word brand came from brander. It was meant to burn. And as that migrated through history, it started to move from just ownership into quality. And then all these attributes started to be built upon it. And so now you look at brands and they're so complex and they're so diverse, and the expectation that's put on a brand to be all, do all and still make money, it's a challenge. And so I think it's good because from my standpoint, a brand, from a simple standpoint, it's defining who you are. So if we personalize it, just saying, Hey, it's my personality. It's all the aspects of my personality, it's my history, it's my future, it's my likes, it's my dislikes, it's all those things. And then you try to put those in through a business perspective. But it's still, when you think about how consumers look at brands, really, they want to identify, and it comes down to the word love. (09:35): I love this brand because they identify aspects of the brand that identify with their life and their values and what they love to do. So there's the connection from my perspective is that there's a lot of data and there's a lot of rationale that you can look to a brand of, it does these things for me and I'm saving money or I'm getting my value, but that still is what I call a love language. And so for me, connecting to users and connecting to consumers and customers in the way that gets that emotive trigger, that's all the way down through the line. You have to do that all the way down through distribution, through retail, through D two C, all these facets to tug on the heartstrings of consumers in the way that identifies with them. And we're not going to be the do all be all right? (10:39): We only have a market that is specific to outdoor gear. However, we believe that everybody has the ability to get outside and to use that to renew their heart, soul, and mind. And when you get outside and you start to do these things, you start to get gear, you start to want to do more, and you start to progress and you have failures. And so for us, failure literally is where we show up when a piece of gear fails, whether that's not waterproof anymore or it's got a hole in it, or the leather's all cracked and your boots, that's where we show up. So I think it's a beautiful analogy to speaking to failure is progress. Failure is growth and failure as the stories that consumers then look at their gear and be like, oh, I remember when that happened. Let me tell you the", "token_estimate": 636, "speakers": ["Sean Fields"], "start_timestamp": "08:21", "end_timestamp": "08:21", "podcast_index": null, "episode_name": "Ep 2: Sean Fields | Sustainability in the Outdoor Industry | Gear Aid", "slug": "sean-fields-sustainability-in-the-outdoor-industry-gear-aid-2f945", "web_url": "https://www.portsidepro.com/podcast-feed/sean-fields-sustainability-in-the-outdoor-industry-gear-aid-2f945", "guest_name": null, "guest_title": null, "categories": [], "short_description": "In this episode, I sit down with Sean Fields from Gear Aid and talk about what sustainability in the outdoor industry really means. Many brands have built upon that idea, but what does it actually mean?", "podcast_length": "44:24"}, {"id": "57e965cc-de8c-4082-8732-6ce78e620c54", "episode_id": "b52ccfcd-175d-4353-bfe6-3329bcfefa6b", "cms_item_id": "68225dfc7bb476527f8c4824", "chunk_index": 6, "content": "Speaker 3 (11:35): Story. And\n\nSean Fields (11:36): Then the beers crack and you tell about the stories. So that's where I really love about, that's what I love about our brand is that we just kind of happen to fall into that. And there's lots of stories. There's lots of love. People are passionate about our brand, sadly, but also opportunistically. A lot of people don't know who we are. They know our products. But pushing the Gear aid name, that's what our whole goal is now, is to push the gear aid name and everything points to that. So there's a lot of work that has been done, but there's even more work to still be done.\n\nCole Heilborn (12:14): Yeah. Well, there always seems to be, it's never ending cycle. Do you have any gear that you look at that's tattered and patched and repaired that you look at and you're like, man, this is a good story behind it? Or you have anything personally that you crack beers to?", "token_estimate": 231, "speakers": ["Speaker 3", "Sean Fields", "Cole Heilborn"], "start_timestamp": "11:35", "end_timestamp": "12:14", "podcast_index": null, "episode_name": "Ep 2: Sean Fields | Sustainability in the Outdoor Industry | Gear Aid", "slug": "sean-fields-sustainability-in-the-outdoor-industry-gear-aid-2f945", "web_url": "https://www.portsidepro.com/podcast-feed/sean-fields-sustainability-in-the-outdoor-industry-gear-aid-2f945", "guest_name": null, "guest_title": null, "categories": [], "short_description": "In this episode, I sit down with Sean Fields from Gear Aid and talk about what sustainability in the outdoor industry really means. Many brands have built upon that idea, but what does it actually mean?", "podcast_length": "44:24"}, {"id": "7db1615c-6972-4462-aa74-75cfb81df8c0", "episode_id": "b52ccfcd-175d-4353-bfe6-3329bcfefa6b", "cms_item_id": "68225dfc7bb476527f8c4824", "chunk_index": 7, "content": "Sean Fields (12:34): I personally, I have a pair of Fry cowboy boots. My dad had a pair and I loved those boots. And so I went out and bought a pair, and I've had those for probably close to 15 years. And the cool thing is that what I love about leather is that with age, it actually looks better. And if you take care of it, it starts to crack, moisturize it. You take care of it, fix the soles, those can last a lifetime. So that's one piece of outdoor gear that I love. Outside of that, I do have, we are not into making bicycles or doing repairs for bicycles, but again, I had, my dad's bike was 1965 rally that he gave to me, and then I turned it into a single speed. And if that got stolen, I'd be devastated. I have all my other bikes that I just bought, whatever. But that one is very, very special. So the renewal aspect of taking something and making it last longer, I mean, you look at what I would call the retro movement. Retro is like this moving window, but the authentic axes that are being produced and sold, they're expensive, but man, you take care of it, that's an heirloom item, (14:00): And that can be passed down. So I think that there's this revival of things that are now being passed down that are extremely valuable because they have the stories embedded with them and because they were built well. So I like to buy things once if possible, and take care of it as long as I can. It's just my personal belief. But I think it's also something that at Gear Aid, we believe that 100%. So we partner with brands that make really great quality stuff, but also we don't say, oh, we're only going to sell to a certain demographic or whatever. It's basically anybody that works or plays outside, we're going to be there for them. So thankfully, our products are affordable. Most of our products are under 10 bucks, and you can fix jackets from head to toe, basically take care of gear.", "token_estimate": 476, "speakers": ["Sean Fields"], "start_timestamp": "12:34", "end_timestamp": "12:34", "podcast_index": null, "episode_name": "Ep 2: Sean Fields | Sustainability in the Outdoor Industry | Gear Aid", "slug": "sean-fields-sustainability-in-the-outdoor-industry-gear-aid-2f945", "web_url": "https://www.portsidepro.com/podcast-feed/sean-fields-sustainability-in-the-outdoor-industry-gear-aid-2f945", "guest_name": null, "guest_title": null, "categories": [], "short_description": "In this episode, I sit down with Sean Fields from Gear Aid and talk about what sustainability in the outdoor industry really means. Many brands have built upon that idea, but what does it actually mean?", "podcast_length": "44:24"}, {"id": "b3a3787d-8f84-4c64-8bd9-eae7af978f61", "episode_id": "b52ccfcd-175d-4353-bfe6-3329bcfefa6b", "cms_item_id": "68225dfc7bb476527f8c4824", "chunk_index": 8, "content": "Cole Heilborn (15:02): Yeah. Tell me about what's happening in the outdoor industry, what's changing? There seems to be a lot of strong pushes towards really selling the sustainability idea, the idea that you can reuse, recycle, donate, pass it on, has that idea, has that mentality always been there in the recreation consumer, or do you feel like it's just coming to life? What's your opinion? What's your experience been with that?\n\nSean Fields (15:42): I think of it historically, you've had dirt bags that just go find stuff and use it until it literally disintegrates, right? They like to go climb and they don't have a lot of money because they like to climb. So just being conservative with their money and looking on ways that they can just do what they love to do. There was something that was there, making your own axes and peons and things like that. On the other hand, you have brands today like Value Village, just rebranded historically to now Value Village is, or not someone, but a brand and an organization. That's all they do is resell, use stuff. So there's a huge push for that. But specifically in the outdoor industry, there's an awareness of the damage that we can do with the things that we make. Yvonne Chouinard says, the only way to be sustainable is to not buy anything. (16:50): We know that that's not realistic, and Patagonia realizes that that's not realistic, but they put their funds and their efforts into mitigating that as much as possible. And that's where we come in with being able to educate people on how to take care of things that if you just buy it and then it doesn't work and they toss it, then all of a sudden that has an impact. So we internally have a program where we upcycle all the marketing materials that we use. Not all of 'em, but as much as we can into new things. So our fabric banners, we turn those into the little pouches and little satchels and things like that, creating old into New. So there's a big push for that, and there's a lot of people that are doing really, really great work in that realm. But I think also getting deeper into the product development, designing for repair, looking at materials, look at processes, supply chain's a big thing. All of that goes into it is really under the scrutiny. And big brands like REI, Patagonia, north Face are doing huge work in that as well. And we try to be involved as much as we can as well. But I think it's always been around, to be honest. (18:15): You look at homesteading, it was just all about using what you had with the land that you did and taking care of it. So I think it's just much more aware because we have more abilities to see what's going on. We can analyze it and look at the data and see how to make a difference.", "token_estimate": 689, "speakers": ["Cole Heilborn", "Sean Fields"], "start_timestamp": "15:02", "end_timestamp": "15:42", "podcast_index": null, "episode_name": "Ep 2: Sean Fields | Sustainability in the Outdoor Industry | Gear Aid", "slug": "sean-fields-sustainability-in-the-outdoor-industry-gear-aid-2f945", "web_url": "https://www.portsidepro.com/podcast-feed/sean-fields-sustainability-in-the-outdoor-industry-gear-aid-2f945", "guest_name": null, "guest_title": null, "categories": [], "short_description": "In this episode, I sit down with Sean Fields from Gear Aid and talk about what sustainability in the outdoor industry really means. Many brands have built upon that idea, but what does it actually mean?", "podcast_length": "44:24"}, {"id": "62725ba3-0f76-4d0f-9018-3a9a7b1a46fc", "episode_id": "b52ccfcd-175d-4353-bfe6-3329bcfefa6b", "cms_item_id": "68225dfc7bb476527f8c4824", "chunk_index": 9, "content": "Cole Heilborn (18:38): Yeah, yeah. Interesting. So I feel like a lot of customers are naturally critical of brands, and at least they can be of the messages that they promote. And I mean, thinking about myself, I've looked at a brand and the message they're promoting, and my first assumption, well, maybe it's negative, but it's usually, oh, they're just saying that because they want to make the sale or they want the customers to feel like they belong. People in your position who I know you and I know that the values that you stand for are real and that you just, you're trying to communicate them in a way that seems authentic. How do you do that in a way that doesn't come across and that you guys are just trying to pair with the customer or make the sale, but you guys are really authentic, you're really genuine about what you're doing. How do you communicate that to your customers?", "token_estimate": 224, "speakers": ["Cole Heilborn"], "start_timestamp": "18:38", "end_timestamp": "18:38", "podcast_index": null, "episode_name": "Ep 2: Sean Fields | Sustainability in the Outdoor Industry | Gear Aid", "slug": "sean-fields-sustainability-in-the-outdoor-industry-gear-aid-2f945", "web_url": "https://www.portsidepro.com/podcast-feed/sean-fields-sustainability-in-the-outdoor-industry-gear-aid-2f945", "guest_name": null, "guest_title": null, "categories": [], "short_description": "In this episode, I sit down with Sean Fields from Gear Aid and talk about what sustainability in the outdoor industry really means. Many brands have built upon that idea, but what does it actually mean?", "podcast_length": "44:24"}, {"id": "84dc30b1-7a68-4074-9983-18b8678d0be3", "episode_id": "b52ccfcd-175d-4353-bfe6-3329bcfefa6b", "cms_item_id": "68225dfc7bb476527f8c4824", "chunk_index": 10, "content": "Sean Fields (19:39): I think there's a lot of, I mean, that's a really good question. In the industry, there's a lot of greenwashing that's happening. There is no real metric for sustainability right now. There's things that are being developed to measure that. So there's organizations and there's affiliations and Blue Sign and Higg Index that kind of validate, okay, you're doing the right thing. But the cool thing about Gear Aid is that our products really represent a step in sustainability. So instead of throwing away, we don't have to put a carrot out there, we donate water. If you buy our mug, you're still making a mug. (20:27): So we don't have to do that. Our patch fixes stuff, it's broke, fix it. So we are just truthful in that, and we educate people in the reality of that and the steps and the tricks on how to use gear and get out there and use it in the environment. And when it fails, Hey, come back to us and here's a little patch. Boom, done. So I think being truthful in what you do, don't greenwash things, use data. There's a lot of tools out there now to push data into people's hands, educate them. But again, it's a hard thing with sustainability. It's such now a large word, and it's kind of overused. So we're navigating ways on how to not use that when we don't need to and use it when we do,\n\nCole Heilborn (21:20): But\n\nSean Fields (21:20): Not to overuse it.\n\nCole Heilborn (21:21): Yeah, yeah. Interesting to you. What is the power of a brand? It could be good or bad. Do you see power in a brand that's being used?", "token_estimate": 388, "speakers": ["Sean Fields", "Cole Heilborn"], "start_timestamp": "19:39", "end_timestamp": "21:21", "podcast_index": null, "episode_name": "Ep 2: Sean Fields | Sustainability in the Outdoor Industry | Gear Aid", "slug": "sean-fields-sustainability-in-the-outdoor-industry-gear-aid-2f945", "web_url": "https://www.portsidepro.com/podcast-feed/sean-fields-sustainability-in-the-outdoor-industry-gear-aid-2f945", "guest_name": null, "guest_title": null, "categories": [], "short_description": "In this episode, I sit down with Sean Fields from Gear Aid and talk about what sustainability in the outdoor industry really means. Many brands have built upon that idea, but what does it actually mean?", "podcast_length": "44:24"}, {"id": "e7da61b8-3c24-43df-9441-1285d5ff24f4", "episode_id": "b52ccfcd-175d-4353-bfe6-3329bcfefa6b", "cms_item_id": "68225dfc7bb476527f8c4824", "chunk_index": 11, "content": "Sean Fields (21:35): Yeah. I mean, gosh, words are brands, right? The power of a word and how it can be used like love, right? There's power in that. But on the backside of love, you can also get hurt. So I think we're all human brands aren't these entities that go along by themselves. They're really driven by human interaction and human decisions. So we're all human, we all fail. Grace is a huge part of our culture, grace and truth, it's a balanced thing. So we're not just all feelings, but we're not all just data either. So the grace and truth aspect, I think it's really seeing people for people, and I think that's something that when we sit behind our Twitter post, we don't realize that there's people on the other end receiving hateful words, and that can affect people. So the reality is, I think having that aspect that on the other side, there's people, and I personally love to have face-to-face conversations, and that's something that as a brand, we're doing more and more of, is doing more consumer events and getting face-to-face with the consumer, and they get to opportunity to share their struggles and share their wins, and we get to celebrate with them. (23:01): So that's really cool because then we get to see the stories that they've experienced and are generating, but also they're like, Hey, can you solve this problem? We're like, good question. We'll see what we can do. So as we work with other brands, that's something they come to us all the time, Hey, this is a problem that we have. Can you guys do it? And we put our heads down and sharpen our pencils and see how that we can solve a potential failure or struggle or issue that they're having.\n\nCole Heilborn (23:35): Oh, interesting.", "token_estimate": 431, "speakers": ["Sean Fields", "Cole Heilborn"], "start_timestamp": "21:35", "end_timestamp": "23:35", "podcast_index": null, "episode_name": "Ep 2: Sean Fields | Sustainability in the Outdoor Industry | Gear Aid", "slug": "sean-fields-sustainability-in-the-outdoor-industry-gear-aid-2f945", "web_url": "https://www.portsidepro.com/podcast-feed/sean-fields-sustainability-in-the-outdoor-industry-gear-aid-2f945", "guest_name": null, "guest_title": null, "categories": [], "short_description": "In this episode, I sit down with Sean Fields from Gear Aid and talk about what sustainability in the outdoor industry really means. Many brands have built upon that idea, but what does it actually mean?", "podcast_length": "44:24"}, {"id": "76a54a1e-cb69-4fef-9e9b-378cd54744e2", "episode_id": "b52ccfcd-175d-4353-bfe6-3329bcfefa6b", "cms_item_id": "68225dfc7bb476527f8c4824", "chunk_index": 12, "content": "Sean Fields (23:36): Yeah. So we work a lot with different brands and try to partner with them as much as we can. There's new technologies that, to be honest, that we get a problem and we're like, wow, we don't really know how to fix this. This is going to take a while. But we like to solve problems and we like to be the go-to for gear issues. We've done it for decades and we want to keep on doing it. But also we also want to ask people what is their problem and how can we help? So you can kind of ask it in a cheeky way, what's your problem? But that's really the core of one of the values that we have is solving problems, seeking them out and solving them.\n\nCole Heilborn (24:26): Yeah, interesting. So I feel like there's a couple brands from my perspective in the outdoor world that have really have made a name for themselves, and I feel like some of it has to do with just in the last couple years, I think a brand that everyone thinks of in the outdoor space is Patagonia. They're a large business. I think anyone in the Pacific Northwest owns at least three Patagonia branded pieces of clothing, but they've made a pretty big name for themselves, making a lot of public statements in regards to a lot of the recent political changes. I look at that example and I see that's a brand making a statement and saying, these are our values. We're going to make a public announcement and voice our opinion. Do you see a lot of brands leading the charge in that way and being that vocal about very controversial issues?", "token_estimate": 382, "speakers": ["Sean Fields", "Cole Heilborn"], "start_timestamp": "23:36", "end_timestamp": "24:26", "podcast_index": null, "episode_name": "Ep 2: Sean Fields | Sustainability in the Outdoor Industry | Gear Aid", "slug": "sean-fields-sustainability-in-the-outdoor-industry-gear-aid-2f945", "web_url": "https://www.portsidepro.com/podcast-feed/sean-fields-sustainability-in-the-outdoor-industry-gear-aid-2f945", "guest_name": null, "guest_title": null, "categories": [], "short_description": "In this episode, I sit down with Sean Fields from Gear Aid and talk about what sustainability in the outdoor industry really means. Many brands have built upon that idea, but what does it actually mean?", "podcast_length": "44:24"}, {"id": "48f47457-c597-4e33-bbac-ab02af1a95f5", "episode_id": "b52ccfcd-175d-4353-bfe6-3329bcfefa6b", "cms_item_id": "68225dfc7bb476527f8c4824", "chunk_index": 13, "content": "Sean Fields (25:32): Well, Jovan Cho's a pretty bold dude. He doesn't BS with anybody, and so he still has deep ties into that organization. Even though he's not heavily involved, he's still the face of Patagonia. So that's a little bit different. When you have an ownership, a founder that's still involved, the more that starts to get disseminated, or if you get sold, or if you are a startup and you're owned by lots of different people, it's a tough thing to navigate because you have to take a position that you really don't want to take a position on. (26:15): For us, we don't really want to step into those things because we serve all demographics and we don't really want to get into political issues. We want to solve problems. So if you have a problem, we want that you have, let's solve it. But that takes conversations and that takes a lot of time and patience. And I don't think that the digital realm really handles that really well because it's just knee jerk and people reacting. My perspective is reaction is never a good thing to do. It's the responding, because responding takes patience, and usually you put your foot in your mouth if you react. Personally, I've had to learn that over my life many a\n\nSpeaker 3 (27:01): Time.\n\nSean Fields (27:02): So I'm always much more interested in conversations with people than to just come out with statements. Really. How does that work out when you've got so many different people that you're serving? So serving to us is a big thing. And to serve people in giving them products that help their lives. So politically, personally, I don't think that whilst I understand what Patagonia is doing and they're doing great work, I think that for us, it's not a good time for us to be stepping into that.\n\nCole Heilborn (27:43): Yeah, yeah. That's something that I think you had mentioned when we had gotten coffee was that you just wish people could slow down. Do you feel like things are, I mean, people say social media moving fast, people are always on the go. Do you really feel like that? If people just slow down, that would help? Just some of the issues that people face in the world.", "token_estimate": 538, "speakers": ["Sean Fields", "Speaker 3", "Cole Heilborn"], "start_timestamp": "25:32", "end_timestamp": "27:43", "podcast_index": null, "episode_name": "Ep 2: Sean Fields | Sustainability in the Outdoor Industry | Gear Aid", "slug": "sean-fields-sustainability-in-the-outdoor-industry-gear-aid-2f945", "web_url": "https://www.portsidepro.com/podcast-feed/sean-fields-sustainability-in-the-outdoor-industry-gear-aid-2f945", "guest_name": null, "guest_title": null, "categories": [], "short_description": "In this episode, I sit down with Sean Fields from Gear Aid and talk about what sustainability in the outdoor industry really means. Many brands have built upon that idea, but what does it actually mean?", "podcast_length": "44:24"}, {"id": "d0482892-6ee1-4eb0-9097-1f490b4d2ea6", "episode_id": "b52ccfcd-175d-4353-bfe6-3329bcfefa6b", "cms_item_id": "68225dfc7bb476527f8c4824", "chunk_index": 14, "content": "Sean Fields (28:08): I think there's a time and place for fast, but fast food and fast fashion hasn't really gotten us anywhere. It's done more damage, obesity, more trash. It's destroyed ecosystems in countries where we get our manufacturing done. So when you ever want to go and have the best food or the best experience taking your time, really lets you appreciate that there's a lot of country when you fly over it that you don't get to see. And there's a lot of beauty that's there that when you're in a car or on a bike or hiking, wow. You get to see every aspect of that, and you get to understand all the minutiae that gets kind of passed by. So I think slow times are a very, they're hard to come by\n\nSpeaker 3 (29:08): Because\n\nSean Fields (29:08): We're always busy and there's always something to do, and we have to be very intentional about carving out time for that. So I love it. I love not being attached to digital devices all the time. And that's another piece is that we are not a digital company. We use digits our hands to fix things. That takes time. It's like getting to understand your gear, like, oh, with a puff jacket, there's a process to that. You've got to clean it. You've got to push the feathers back in. You've got to line everything up, and then you apply that tape and that process is really something beautiful. And then when you start to take that first step in repairing, it really makes you start to look at, well, what else do I have sitting around that's broken that I can repair? And then you start to approach life in a little bit different way and making different decisions.\n\nCole Heilborn (30:04): Yeah. Interesting. Is that why you enjoy getting outside\n\nSean Fields (30:08): For the renewal part or for\n\nCole Heilborn (30:10): Renewal? Just slow of pace.\n\nSean Fields (30:13): Slow of pace, but also I like skiing. I haven't been skiing in over a year, but\n\nCole Heilborn (30:21): Well, I mean, that's okay.\n\nSean Fields (30:22): That's fun\n\nCole Heilborn (30:22): Summer season,", "token_estimate": 507, "speakers": ["Sean Fields", "Speaker 3", "Cole Heilborn"], "start_timestamp": "28:08", "end_timestamp": "30:22", "podcast_index": null, "episode_name": "Ep 2: Sean Fields | Sustainability in the Outdoor Industry | Gear Aid", "slug": "sean-fields-sustainability-in-the-outdoor-industry-gear-aid-2f945", "web_url": "https://www.portsidepro.com/podcast-feed/sean-fields-sustainability-in-the-outdoor-industry-gear-aid-2f945", "guest_name": null, "guest_title": null, "categories": [], "short_description": "In this episode, I sit down with Sean Fields from Gear Aid and talk about what sustainability in the outdoor industry really means. Many brands have built upon that idea, but what does it actually mean?", "podcast_length": "44:24"}, {"id": "bd2c1d67-05ac-4b6d-ac69-5bcfa394536a", "episode_id": "b52ccfcd-175d-4353-bfe6-3329bcfefa6b", "cms_item_id": "68225dfc7bb476527f8c4824", "chunk_index": 15, "content": "Sean Fields (30:25): But I like to go fast than skiing, but there's the hiking part, right? Of the back country experience that's very slow. You're not on a lift. You remember every step, your lungs are burning or you're sweating or you're seeing something on a new line, or you're being aware of your environment, avalanche risks, things like that. So you get that slow approach and then you get to crush the down. And I think that that's something specifically in business that I like is being really good at what you do, but still taking the time to look at the nuances and enjoy the experience as much as you can. And then once you do the hard work, then you get the crush, the wins, which is making great products and seeing the revenue come in. But there's going to be failures too. And again, the failure part, when we talk about our business, that applies to our team and our company of when we have a failure, that's a huge learning aspect, learning opportunity for the team and the business to be like, wow, what did we learn from that? So you get the wins out of the failure and they're kind of essential as a part of the growth of the business.\n\nCole Heilborn (31:44): What do you think, speaking personally, what shaped your thought process towards your way of life? The idea of slowing down, repairing, buying things that have integrity and are made high quality. Where do you feel like that came from?", "token_estimate": 354, "speakers": ["Sean Fields", "Cole Heilborn"], "start_timestamp": "30:25", "end_timestamp": "31:44", "podcast_index": null, "episode_name": "Ep 2: Sean Fields | Sustainability in the Outdoor Industry | Gear Aid", "slug": "sean-fields-sustainability-in-the-outdoor-industry-gear-aid-2f945", "web_url": "https://www.portsidepro.com/podcast-feed/sean-fields-sustainability-in-the-outdoor-industry-gear-aid-2f945", "guest_name": null, "guest_title": null, "categories": [], "short_description": "In this episode, I sit down with Sean Fields from Gear Aid and talk about what sustainability in the outdoor industry really means. Many brands have built upon that idea, but what does it actually mean?", "podcast_length": "44:24"}, {"id": "bb8a0805-21e2-4b3c-8e2f-038feddfa531", "episode_id": "b52ccfcd-175d-4353-bfe6-3329bcfefa6b", "cms_item_id": "68225dfc7bb476527f8c4824", "chunk_index": 16, "content": "Sean Fields (32:01): Me personally, I think it came from how I was raised. My grandfather, he worked for IBM, but then he retired early and he just started building stuff. He took old cars and refurbed 'em and made an organ from scratch using a vacuum cleaner as the air source. He hand wound the pools with the can opener with five miles of copper wire. So sitting in the back porch in Missouri, watching the chicken on the barbecue and listening to my grandpa tell stories and then seeing the things that he would make the value that instilled in me, and then that got passed on to my uncle and my dad. That really made an impression on me of like, okay, I'd rather buy something that was more expensive that then I can use to build other things, and that's going to make me take care of it and use it and make it last long. That really changed how I view life. And so I've always been one to nice things, but sometimes you can find nice things in different places. So it's something that that's where, for me personally, where my values then align with what gear aid's doing, and it makes it enjoyable experience for me to work there. (33:32): It aligns with what I believe.\n\nCole Heilborn (33:33): Yeah. Yeah. Interesting. Are there any projects that you are working on?\n\nSean Fields (33:38): Lots. Some are not so exciting as new products. We've got a bunch of backend work that we're doing with our ERP and our B2B portal, building new platforms to make our systems better, got some new products that are coming down the line that are pretty exciting. But most of all, I enjoy working with our team and the people that I work with and having moments where we're able to laugh together and kind of take a break from the pressures of business. I really enjoy the team that I work with and the things that we appreciate about each other and also work too hard stuff together. So I think that builds a vulnerability and intimacy in work that kind of binds us together. So when we do have to go through future hard things, it makes it so we can kind of come together as a team and push through it and do it well.", "token_estimate": 529, "speakers": ["Sean Fields", "Cole Heilborn"], "start_timestamp": "32:01", "end_timestamp": "33:38", "podcast_index": null, "episode_name": "Ep 2: Sean Fields | Sustainability in the Outdoor Industry | Gear Aid", "slug": "sean-fields-sustainability-in-the-outdoor-industry-gear-aid-2f945", "web_url": "https://www.portsidepro.com/podcast-feed/sean-fields-sustainability-in-the-outdoor-industry-gear-aid-2f945", "guest_name": null, "guest_title": null, "categories": [], "short_description": "In this episode, I sit down with Sean Fields from Gear Aid and talk about what sustainability in the outdoor industry really means. Many brands have built upon that idea, but what does it actually mean?", "podcast_length": "44:24"}, {"id": "c8afa92a-bd4a-4535-9957-3acd146faf41", "episode_id": "b52ccfcd-175d-4353-bfe6-3329bcfefa6b", "cms_item_id": "68225dfc7bb476527f8c4824", "chunk_index": 17, "content": "Cole Heilborn (34:41): Yeah. Yeah. So now you guys are working on developing, continuing to develop the brand and communicate it, but where do you want it to be? What do you want the Gear AID'S brand to be and to ultimately mean one day?\n\nSean Fields (34:59): Well, when I first was there, just right off the bat, I was like, I want people to know where I work. When I say, oh, where do you work? And I say, Gary, they're like, oh, I've never heard of that. That's a challenge. And so that's where it's like you use every single method of branding that you can to push out to be known. That's the first thing to be known. And then once they know you, it's kind of like a handshake. It takes a while for them to remember you. Statistics say it's five to seven impressions for someone to remember just your logo, but\n\nCole Heilborn (35:38): What would you like to see change in the recreation\n\nSean Fields (35:39): World? Oh, it's getting that play well together. Different people coming together to enjoy the outdoors that have different views on things and learning how to come together and the things that they share, and then don't tear each other apart on the things that they disagree on. I think that that's something that is really cool about doing an adventure, whether it's climbing a mountain or going on a paddling trip, is that you literally have to rely on people for your life. And so it kind of removes all of the societal BS, and I think the outdoors does a great job in just doing that. You just start to forget. Your body literally gets reset to nature's time. You start to wake up when the sun comes up and go to sleep when sun goes down, and so you really start to forget about your job and all the pressures of life, and you just start to really enjoy just something as simple as a fire and just enjoying the fire and watching it for hours, and it's just a huge reset for your body and mind. And then that starts to open up the ability to start to be creative again and to solve problems through just relaxing and getting out there and doing something that's not work related or your traditional day to day.", "token_estimate": 532, "speakers": ["Cole Heilborn", "Sean Fields"], "start_timestamp": "34:41", "end_timestamp": "35:39", "podcast_index": null, "episode_name": "Ep 2: Sean Fields | Sustainability in the Outdoor Industry | Gear Aid", "slug": "sean-fields-sustainability-in-the-outdoor-industry-gear-aid-2f945", "web_url": "https://www.portsidepro.com/podcast-feed/sean-fields-sustainability-in-the-outdoor-industry-gear-aid-2f945", "guest_name": null, "guest_title": null, "categories": [], "short_description": "In this episode, I sit down with Sean Fields from Gear Aid and talk about what sustainability in the outdoor industry really means. Many brands have built upon that idea, but what does it actually mean?", "podcast_length": "44:24"}, {"id": "cd341892-767c-4618-afb2-cd14620e760a", "episode_id": "b52ccfcd-175d-4353-bfe6-3329bcfefa6b", "cms_item_id": "68225dfc7bb476527f8c4824", "chunk_index": 18, "content": "Cole Heilborn (37:13): Yeah, I am always surprised, not surprised, but just I can never understand why you can just stare at a fire for hours and you could be sitting next to people. You could be alone, but there's something about it and everyone gets it too. It's not just certain populations or cultures of people. Everyone can sit around at fire and just be content being there. It's a really kind of crazy and powerful thing.\n\nSean Fields (37:45): Yeah, it's hypnotic in a way, but it's also allows you to just think about the magnificence of just fire and the power that it has and how it works and the beauty of it. Fires are beautiful. If you take away all that's around it and just look at it, the colors are amazing. I personally love the smell of being in a campfire and what that do. It provides warmth, a cooking source, like the utility of it, and just being in community with people that are there for the same thing to enjoy a nice beer or whatever your drink of preference is and talking. It's just connecting with each other, which I think we're built to connect with each other and not to be siloed. We don't do well in solitude.\n\nCole Heilborn (38:49): That's one thing. The outdoors I think they do pretty well is they're a great equalizer. If you're climbing a mountain, the mountain doesn't care how fit you are or what your economic background is. It's just going to make sure it sucks for everyone. The only thing you can prepare is how prepared you are and how mentally and physically fit you are.\n\nSean Fields (39:14): Correct. Yeah.\n\nCole Heilborn (39:15): Nothing else really matters,\n\nSean Fields (39:18): And it also provides a challenge. If you're not fit, you're like, wow, I'm not fit. I need to do something about that.\n\nCole Heilborn (39:26): Yeah. Yeah. Well, we don't have much more time for today, but I really appreciate you taking the time to sit down. It's been great to learn a little bit about your story, a little bit about what gear aid's all about. For those people out there who are listening, where can they find gear AID'S products?", "token_estimate": 521, "speakers": ["Cole Heilborn", "Sean Fields"], "start_timestamp": "37:13", "end_timestamp": "39:26", "podcast_index": null, "episode_name": "Ep 2: Sean Fields | Sustainability in the Outdoor Industry | Gear Aid", "slug": "sean-fields-sustainability-in-the-outdoor-industry-gear-aid-2f945", "web_url": "https://www.portsidepro.com/podcast-feed/sean-fields-sustainability-in-the-outdoor-industry-gear-aid-2f945", "guest_name": null, "guest_title": null, "categories": [], "short_description": "In this episode, I sit down with Sean Fields from Gear Aid and talk about what sustainability in the outdoor industry really means. Many brands have built upon that idea, but what does it actually mean?", "podcast_length": "44:24"}, {"id": "0a7ba7b3-5a09-4052-bf77-554145edce0b", "episode_id": "b52ccfcd-175d-4353-bfe6-3329bcfefa6b", "cms_item_id": "68225dfc7bb476527f8c4824", "chunk_index": 19, "content": "Sean Fields (39:46): You can go to gear aid.com. Obviously all of our products are there, but go to your local dealer. Most hardware stores and most outdoor specialty shops are going to have our products all the way up to REI, Cabela's and the big box stores. So anything that anywhere where you're going to find outdoor gear, especially for or hiking or backpacking or whatever, you're going to find us there.\n\nCole Heilborn (40:13): Great. And where can people find you? Where, I mean, maybe not where you live, but\n\nSean Fields (40:21): Yeah, I'm one to go out and do adventures. I'm all over the place. We do a bit of traveling for work, and hopefully you'll see me up in the mountain or somewhere in Bellingham.\n\nCole Heilborn (40:31): Sounds good. Well, I appreciate your time and we'll see you guys next time.\n\nSean Fields (40:34): Sounds good. Thanks Cole.\n\nCole Heilborn (40:36): Thank you.", "token_estimate": 225, "speakers": ["Sean Fields", "Cole Heilborn"], "start_timestamp": "39:46", "end_timestamp": "40:36", "podcast_index": null, "episode_name": "Ep 2: Sean Fields | Sustainability in the Outdoor Industry | Gear Aid", "slug": "sean-fields-sustainability-in-the-outdoor-industry-gear-aid-2f945", "web_url": "https://www.portsidepro.com/podcast-feed/sean-fields-sustainability-in-the-outdoor-industry-gear-aid-2f945", "guest_name": null, "guest_title": null, "categories": [], "short_description": "In this episode, I sit down with Sean Fields from Gear Aid and talk about what sustainability in the outdoor industry really means. Many brands have built upon that idea, but what does it actually mean?", "podcast_length": "44:24"}, {"id": "35ab8be2-76cf-4cc3-8da3-5db4b81b465a", "episode_id": "63988d85-0936-491f-88a4-391fe15cb920", "cms_item_id": "68225dfc7bb476527f8c4843", "chunk_index": 0, "content": "Cole Heilborn (00:02): Welcome to the Backcountry Marketing Podcast. My name is Cole Helebo and I'll be your host today. This podcast dives deep with leaders of the outdoor marketing industry as they discuss the gritty details of their work, personal challenges and latest adventures, whether you're standing in the lift line, shuttling the fresh loam, or cracking a local beer. I hope you enjoyed today's episode. This is the Backcountry Marketing Podcast. This episode is produced by Port Side Productions, an outdoor, commercial and film production company based in the Pacific Northwest. Let's make waves. Welcome to the Backcountry Marketing Podcast. Today I'm sitting down with Todd Bischoff, the global creative director at Gerber. Todd, how are you?\n\nTodd Bischoff (00:44): Good, how are you?\n\nCole Heilborn (00:45): Doing? Great. Where are you calling in from today?\n\nTodd Bischoff (00:48): I am calling in from Portland, Oregon.\n\nCole Heilborn (00:51): Okay, right on. So not that far away from up here in Bellingham, about four hours. Yeah. Cool. So tell us a little bit about Gerber. Who are you? What's the team look like? Give us kind of the skinny on who you guys are.\n\nTodd Bischoff (01:07): Yeah, so we are not the baby food. We are Gerber gear, the Knife and Multitool company. But yeah, we're based out of Portland, Oregon, which seems to be sort of the knife mecca of the world here. A lot of brands are based in this area. But yeah, Gerber Gerber's located here. We've been around since 1939 and through all that, the company's definitely grown and evolved over the years, but ultimately, we're an outdoor brand. We're rooted in all things outdoor from camping, hiking, fishing, hunting, foraging, anything and everything that you like to do outdoors.\n\nCole Heilborn (01:59): I mean, I think most people probably know you guys from your knives. I got to imagine anyone who enjoys the outdoors probably has owned at least one Gerber knife in their lifetime.", "token_estimate": 495, "speakers": ["Cole Heilborn", "Todd Bischoff"], "start_timestamp": "00:02", "end_timestamp": "01:59", "podcast_index": 30, "episode_name": "Ep 30: Todd Bischoff | Positively Disrupt | Gerber Gea‪r‬", "slug": "ep-30-todd-bischoff-positively-disrupt-gerber-gear", "web_url": "https://www.portsidepro.com/podcast-feed/ep-30-todd-bischoff-positively-disrupt-gerber-gear", "guest_name": "Todd Bischoff", "guest_title": "Global Creative Director", "categories": [], "short_description": "\"We can positively disrupt a trade show by hosting a Guinness World Record event. Or we can come into a retail environment and disrupt a space by doing something no one is doing.\"", "podcast_length": "44:52"}, {"id": "feec7692-46a9-40bc-961c-ab14a61f246d", "episode_id": "63988d85-0936-491f-88a4-391fe15cb920", "cms_item_id": "68225dfc7bb476527f8c4843", "chunk_index": 1, "content": "Todd Bischoff (02:09): We definitely do two to our heritage and how long we've been around. Definitely there's no shortage of consumers that come up and tell us about receiving their first knife, and they were five and was handed down to them from their father, who was given by their father and so on. And so, yeah, there's definitely, when you think about all things outdoors, from survival to camping, to just going back to tools in general, a knife is definitely a tool that's needed and relevant in that space, whether it's hunting, fishing, camping, building, shelter, making fire.\n\nCole Heilborn (02:53): Well, it's a reason. It's one of the 10 essentials.\n\nTodd Bischoff (02:56): Yeah. Yep.\n\nCole Heilborn (02:58): That's awesome. So as creative director, what does your job entail?\n\nTodd Bischoff (03:03): Yeah, so it entails a lot. So basically my role and Gerber bringing me on was to build the internal sort of creative agency as well as take the brand and identity to the next level and start truly building that Gerber culture and through stories. And so with that, like we mentioned, we get so many consumers that are telling us about their first experience with Gerber and how long they've had their knife and how they got it. And those stories mean a lot to us. And over the years we haven't really truly presented those stories and told those stories. And so part of my role is to bring those stories to life through not only legacy products, but through a lot of our new products, new innovations that we have, as well as just all the activities that we're relevant in ambassadors and consumers that participate. So, so I oversee a team of creatives that include graphic designers, packaging designers, copywriters, oversee social media, pr, as well as our ambassador program. So everything from campaign development to packaging design to naming products, to coming up with crazy wild events. It's all part of the brand story and what we're after.", "token_estimate": 492, "speakers": ["Todd Bischoff", "Cole Heilborn"], "start_timestamp": "02:09", "end_timestamp": "03:03", "podcast_index": 30, "episode_name": "Ep 30: Todd Bischoff | Positively Disrupt | Gerber Gea‪r‬", "slug": "ep-30-todd-bischoff-positively-disrupt-gerber-gear", "web_url": "https://www.portsidepro.com/podcast-feed/ep-30-todd-bischoff-positively-disrupt-gerber-gear", "guest_name": "Todd Bischoff", "guest_title": "Global Creative Director", "categories": [], "short_description": "\"We can positively disrupt a trade show by hosting a Guinness World Record event. Or we can come into a retail environment and disrupt a space by doing something no one is doing.\"", "podcast_length": "44:52"}, {"id": "c8cb155b-e328-4f0f-9937-0ad43b9ca69c", "episode_id": "63988d85-0936-491f-88a4-391fe15cb920", "cms_item_id": "68225dfc7bb476527f8c4843", "chunk_index": 2, "content": "Cole Heilborn (04:51): Yeah. Well, speaking of crazy events, that's what I'm excited to talk about today, but I got a couple more questions before we go there. When we were chatting earlier, you were telling me a little bit about the history of Gerber, and I think it was surprising to me, I got to assume it would be surprising to other folks as well, because you guys weren't always a gear manufacturer. Knife manufacturer. Tell us a little bit about that story.\n\nTodd Bischoff (05:17): Yeah, so again, it's one of those stories that wasn't really told. And it's interesting that Gerber actually back in, I believe it was around 1910 or so, but Joseph Gerber, Pete Gerber's father, those two started a advertising agency here in Portland, and they over the years developed this reputation for creating these handmade knife sets that they would gift to their clients in and partners during the holidays. And they became so well known for these handmade gift sets that Abercrombie and Fitch actually requested to bring these to life and more of a less gift giving and more of a product line into their catalogs. And so that really took off in about 1939 when Gerber Legendary Blades was born and it went from this holiday gift idea to knife brand.\n\nCole Heilborn (06:33): So was it just like one day when they said, we're going to close the agency and just start making knives?\n\nTodd Bischoff (06:37): I mean, I don't think it was as simple as the flip of the switch, but I do feel like they were onto something and they realized that people enjoyed receiving this not only custom made gift, but high quality and premium. And it's super ironic because every year as a marketing department and team, it's like we always talk about what are we going to gift our partners? This year the bar was set pretty high with them. And so it's just kind of ironic and a cool story to tell that they started off as an app, especially me as a creative and being in marketing and advertising. This company started in those roots and has now evolved into this tool.\n\nCole Heilborn (07:33): Talk about a 180 and not being afraid to ditch what you were doing.", "token_estimate": 535, "speakers": ["Cole Heilborn", "Todd Bischoff"], "start_timestamp": "04:51", "end_timestamp": "07:33", "podcast_index": 30, "episode_name": "Ep 30: Todd Bischoff | Positively Disrupt | Gerber Gea‪r‬", "slug": "ep-30-todd-bischoff-positively-disrupt-gerber-gear", "web_url": "https://www.portsidepro.com/podcast-feed/ep-30-todd-bischoff-positively-disrupt-gerber-gear", "guest_name": "Todd Bischoff", "guest_title": "Global Creative Director", "categories": [], "short_description": "\"We can positively disrupt a trade show by hosting a Guinness World Record event. Or we can come into a retail environment and disrupt a space by doing something no one is doing.\"", "podcast_length": "44:52"}, {"id": "59614cdd-1d68-4292-a0c7-ede2db05ed7e", "episode_id": "63988d85-0936-491f-88a4-391fe15cb920", "cms_item_id": "68225dfc7bb476527f8c4843", "chunk_index": 3, "content": "Todd Bischoff (07:36): Yeah, for sure. And it's cool to go back and look at they obviously coming from a advertising background, seeing those early ads and stuff that they were creating, it's very, very cool.\n\nCole Heilborn (07:50): Oh yeah, that's got to be some neat legacy content.\n\nTodd Bischoff (07:53): Yeah,\n\nCole Heilborn (07:54): So that's really pretty fascinating and I think that's got to be kind of an original unique story for companies like yours. Let's transition the conversation a little bit, and let's talk about, you were telling me a little bit about this event a few years ago or not the event. In an event, you guys were at Outdoor Retailer a few years ago and you were expecting this awesome turnout of people, and then it turns into this dismal trickle of people and you ended up having to drink the whole keg by yourself, it sounds like. And comparing that to where you guys are at now in recent events that you've had at Outdoor Retailer and other similar conventions. Let's dive into that and let's, I want to dissect that progression, but first let's maybe dive into where you guys were, if you can kind of describe I guess all of that stuff.\n\nTodd Bischoff (08:51): So I tell this story to everyone, and probably everyone on my team is sick of hearing it, but my first trade show event with Gerber was at Shot Show, which is a big hook and bullet show. And coming off of the outdoor industry, I used to work at Smart Wall and attending or and SIA and all these a little bit more laid back shows and events and coming into Shot Show, I am used to wearing shorts and flip flops and just very laid back vibe. And coming into my first trade show with Gerber, it was, we were wearing these white Nordstrom shirts tucked into dress pants and shoes, and I wear a hat every day, and I wasn't able to wear a hat. And I just completely out of my element second guessing why I even joined the team in this company. And I was standing there just kind of trying to take it all in and sort of be that flying the wall in, I think it was day two, we were having a happy hour event. And so I was like, all right, this is, I'm getting excited. I was going to sort of remind me of", "token_estimate": 548, "speakers": ["Todd Bischoff", "Cole Heilborn"], "start_timestamp": "07:36", "end_timestamp": "08:51", "podcast_index": 30, "episode_name": "Ep 30: Todd Bischoff | Positively Disrupt | Gerber Gea‪r‬", "slug": "ep-30-todd-bischoff-positively-disrupt-gerber-gear", "web_url": "https://www.portsidepro.com/podcast-feed/ep-30-todd-bischoff-positively-disrupt-gerber-gear", "guest_name": "Todd Bischoff", "guest_title": "Global Creative Director", "categories": [], "short_description": "\"We can positively disrupt a trade show by hosting a Guinness World Record event. Or we can come into a retail environment and disrupt a space by doing something no one is doing.\"", "podcast_length": "44:52"}, {"id": "31babd37-570d-400b-aa3f-dffacf6f08fe", "episode_id": "63988d85-0936-491f-88a4-391fe15cb920", "cms_item_id": "68225dfc7bb476527f8c4843", "chunk_index": 4, "content": "Cole Heilborn (10:11): You're getting back into your element,\n\nTodd Bischoff (10:12): Getting back into my element a little bit and able to relax. And so they wheeled out the keg as they normally do at trade shows and stuff. And the keg arrived, the keg got tapped, everything got ready, music got turned on, and zero people showed up. And I was just standing there. I was just shocked because typically when people find out you have a keg or a happy hour, it's a mad dash of people trying to just find that free beer. So nobody showed up, and we had almost an entire keg that we were just standing around trying to beg people to come in. And from that moment on, I told myself, I was like, this will never happen again. This is the bar set from a brand standpoint and awareness and culture that people don't really know who we are and understand we're not about drinking beer and partying, but there is no following there. There was no presence. So\n\nCole Heilborn (11:27): I want to pause you really quick. How long ago was that?\n\nTodd Bischoff (11:29): Oh, man, that was five years ago.\n\nCole Heilborn (11:32): Okay. All right. So not that far ago.", "token_estimate": 288, "speakers": ["Cole Heilborn", "Todd Bischoff"], "start_timestamp": "10:11", "end_timestamp": "11:32", "podcast_index": 30, "episode_name": "Ep 30: Todd Bischoff | Positively Disrupt | Gerber Gea‪r‬", "slug": "ep-30-todd-bischoff-positively-disrupt-gerber-gear", "web_url": "https://www.portsidepro.com/podcast-feed/ep-30-todd-bischoff-positively-disrupt-gerber-gear", "guest_name": "Todd Bischoff", "guest_title": "Global Creative Director", "categories": [], "short_description": "\"We can positively disrupt a trade show by hosting a Guinness World Record event. Or we can come into a retail environment and disrupt a space by doing something no one is doing.\"", "podcast_length": "44:52"}, {"id": "3a66bc77-0eef-45aa-b7ce-f59f487ad7b9", "episode_id": "63988d85-0936-491f-88a4-391fe15cb920", "cms_item_id": "68225dfc7bb476527f8c4843", "chunk_index": 5, "content": "Todd Bischoff (11:35): No, no. And leading up to that point, the brand had evolved quite a bit. And over the years, the logo and the identity and the brand, obviously in that amount of time, things change and evolve, however, that story hadn't evolved and experience. So from that day on, we set ourselves this goal of we will never go back to that point. And we wanted to have this experience where engaging with consumers and not just being a brand that throws features and benefits and products over the wall and supports them with pricing. And we wanted to be more than that. We wanted to be truly that outdoor brand in that and that energy and that vibe. And so progressively got better and better. And the following year at Outdoor Retailer, we had a bald eagle in our booth, and that became known as the or Eagle. And it created such a buzz where people were just lined up and stacked in to get into our happy hour event. And we had at that point too, we started partnering up with a local brewery called Boneyard Beer, (12:58): And they started doing small batch of custom made brews for us. And so we wanted to break through, we called around the office, we like to positively disrupt, and so we wanted to break through all the other craft beers that everybody was serving and have this limited run special time. Only get it now in our booth and you'll never have it again. And so driving that excitement with having a bald eagle, having a beer that nobody else will probably ever have again, that drew a lot of crowd and a lot of buzzing. So we started thinking around, Hey, we're starting to connect with people. We're starting to engage with them and entertain them and bring them in and get them comfortable and start sharing our stories. And so year after year, it just started getting, it's like, okay, well, we had the Eagle and that set the bar, and so how are we going to go above that and how are we going to go above that? (13:52): And over the last five years, it's evolved from Eagles to tattoo parlors to, we almost had a 1200 pound Kodiak grizzly bear trucked into the booth to what I feel like is probably one of the most exciting events we've ever had. And to this day, people are still talking about it, but we had a Guinness Book, a World records attempt in our booth with one of our top level ambassadors, Tim Kennedy. And it literally just it to the point of the bar was set so high after that event that it's almost haunting us in a sense of we can't repeat it, we can't try and outdo it. But it was to the point of it was so executed from a team aspect as well, just logistically getting the Guinness Book of World Records adjudicator out having, we had to basically tear down half of our booth because the world record we were trying to attempt was the most beer can smashed and in a minute with an elbow. (15:02): And so everybody was like, how does that relate to Gerber and what's the point of this and why are we turning down half of our booth during prime selling time to put on this event? And it took a lot of planning and a lot of thought and a lot to go into it to get the confidence in the company to allow us to, for two hours basically tear down half the booth and prevent people from selling, showing products. And it was insane. We had people lined up for, I think six hours to get into the booth that day. And it seems to be a normal thing now where come 12 o'clock, one o'clock in the afternoon, people are starting to line up for our five o'clock happy hour event. But yeah, this world record, it was a highlight. We had media come in, we had special ponchos made, so everybody had these big ponchos standing in line", "token_estimate": 917, "speakers": ["Todd Bischoff"], "start_timestamp": "11:35", "end_timestamp": "11:35", "podcast_index": 30, "episode_name": "Ep 30: Todd Bischoff | Positively Disrupt | Gerber Gea‪r‬", "slug": "ep-30-todd-bischoff-positively-disrupt-gerber-gear", "web_url": "https://www.portsidepro.com/podcast-feed/ep-30-todd-bischoff-positively-disrupt-gerber-gear", "guest_name": "Todd Bischoff", "guest_title": "Global Creative Director", "categories": [], "short_description": "\"We can positively disrupt a trade show by hosting a Guinness World Record event. Or we can come into a retail environment and disrupt a space by doing something no one is doing.\"", "podcast_length": "44:52"}, {"id": "1fc305c7-0dcc-497d-a2e3-83d5943d20c3", "episode_id": "63988d85-0936-491f-88a4-391fe15cb920", "cms_item_id": "68225dfc7bb476527f8c4843", "chunk_index": 6, "content": "Cole Heilborn (16:01): Splash zone.\n\nTodd Bischoff (16:02): Yeah, everybody boneyard flew out and they again made a special brew for us to support one of our US made autons that we were launching at that event. So it all came together. It was a happy hour event. We called it the Empower Hour. We were supporting the new Empower Auto Knife that was coming out, and we basically had a world record attempt that we did not break. We didn't even come close,\n\nCole Heilborn (16:33): But it was cool, nevertheless, right.\n\nTodd Bischoff (16:35): Oh yeah. I mean, looking back at all the videos, everybody was smiling, everybody had a beer in their hand, everybody had their phone up. Everybody was recording the entire event, and all you could see was Gerber logos everywhere, just beer flying. I mean, it was just a complete shit show of an event that people were climbing. If you zoomed up and look up in the rt, like people were climbing up on top of Boost and rafters to look in on it. We had binocular and other brands that were holding up their scopes and everything looking in. I mean, it sent ripples through the show, and I feel bad in a sense that all the boosts around us sort of suffered through that two hours, not able to have any meetings or anything. But there was probably about, I don't know, I'd say anywhere between 1500 to 2000 people gathered round and shoulder to shoulder just watching this 62nd along event.\n\nCole Heilborn (17:34): Dang. We'll have to link the video into the show notes. You can describe it and it sounds awesome. But then you watch it and you're like, oh, that's actually really cool.\n\nTodd Bischoff (17:44): And the video, I was actually filming the video and actually one of the beer cans shout out and took me out and it went to the point of everybody's like, oh, Tim, you killed the cameraman. I mean, it was awesome.", "token_estimate": 465, "speakers": ["Cole Heilborn", "Todd Bischoff"], "start_timestamp": "16:01", "end_timestamp": "17:44", "podcast_index": 30, "episode_name": "Ep 30: Todd Bischoff | Positively Disrupt | Gerber Gea‪r‬", "slug": "ep-30-todd-bischoff-positively-disrupt-gerber-gear", "web_url": "https://www.portsidepro.com/podcast-feed/ep-30-todd-bischoff-positively-disrupt-gerber-gear", "guest_name": "Todd Bischoff", "guest_title": "Global Creative Director", "categories": [], "short_description": "\"We can positively disrupt a trade show by hosting a Guinness World Record event. Or we can come into a retail environment and disrupt a space by doing something no one is doing.\"", "podcast_length": "44:52"}, {"id": "2a1b31bd-4023-47c9-896d-6c73c01ae843", "episode_id": "63988d85-0936-491f-88a4-391fe15cb920", "cms_item_id": "68225dfc7bb476527f8c4843", "chunk_index": 7, "content": "Cole Heilborn (17:57): Yeah. So you're describing all of this over a five year span. You go from not having anyone showing up at your booth, you couldn't even pay them to take a beer to people lining up for hours for either a Gerber tattoo or to watch this Iron Man guy break beers with his elbow. How do you do that in five years? Because a lot of brand loyalty that you've created in a short amount of time, how have you guys done that?\n\nTodd Bischoff (18:29): Yeah, I think honestly it's getting to know who our consumers are and what their interests are and what they like to talk about and what they're passionate about. And you hear all these stories about somebody getting their first knife or their first tool, or for a while, Gerber was the number one supplier to the US military with Multitool. And so within the military and tactical space, Gerber's the Kleenex brand, and everybody says Hammy or Gerber, it could be six other brand of, but we're that brand. And so coming up with these events and stuff, again, it's not just about drinking beer and partying. It's more or less, I shouldn't say any, but it's like most consumers that we've talked with and we've interviewed is when they go out on a hunting trip, it's nine out of 10 times. It's a failure. But there's always a story that comes with that. And there's chances are that on the way home from that hunting trip, they're stopping at the local watering hole and they're going to share a pint with their buddy and talk about it. (19:42): Or when they're out fishing, there's so many fishing stories out there and the same thing on the way home. They're likely to share a beer with their buddy and talk about the one that got away, or just it's common things that people enjoy drinking a beer and hanging out. And so it's those simple things that come together. It's how we can connect more and engage more and sort of open the doors a little bit further. And with having a tattoo parlor in our booth, it's like what? That has no significance to knives and multi tools. But when you think about it, all these people that have served or people that have these moments in time that they want to remember, and a lot of times people, they'll get a tattoo to remember a moment in their life when something happened. And it's that sort of mentality of you see somebody that's got a tattoo and it's like, oh, man, I got a tattoo, or there's a story. (20:37): What's that tattoo mean then? So we were able to solely evolve this. I always rewarded our product managers for every US made product that they brought to market. I would reward them with this custom tattoo design that we would turn into a sticker and a patch and hand out at events, and they would get super excited about that. And so it turned in this from what used to be a sticker idea to eventually we started getting all these submissions of people getting the Gerber logo tattooed on their body. And it was over the years, we just collected all these photos from consumers and fans of like, Hey, look, I got the Gerber tattoo onto my leg or my arm. And so we started thinking about it more. And with the launch of our customization program, in a sense, you're tattooing your product, your laser marking onto the blade or the handle. (21:33): It's essentially a tool tattoo. And so we were able to bring to life this momentum that we already had with these tattoos and this heritage and the meaning behind them into the customization as well as giving people, not many people have the money to go out and just spend on a $800 tattoo. And so we were able to fly out a couple of Portland's best tattoo artists out to Vegas for a couple days, and we converted our half of our trade show booth into a tattoo parlor that was running for eight hours. And those two artists busted out as many tattoos as they could within eight hours. And again, we had people lined up for eight hours. And when you think about that, it's like I won't even wait at a restaurant for more than 30 minutes for a table, let alone growing up in Ohio and waiting in line at Cedar Point to ride a roller coaster for an hour and a half seems like days, and these people are standing in line for eight hours.", "token_estimate": 1051, "speakers": ["Cole Heilborn", "Todd Bischoff"], "start_timestamp": "17:57", "end_timestamp": "18:29", "podcast_index": 30, "episode_name": "Ep 30: Todd Bischoff | Positively Disrupt | Gerber Gea‪r‬", "slug": "ep-30-todd-bischoff-positively-disrupt-gerber-gear", "web_url": "https://www.portsidepro.com/podcast-feed/ep-30-todd-bischoff-positively-disrupt-gerber-gear", "guest_name": "Todd Bischoff", "guest_title": "Global Creative Director", "categories": [], "short_description": "\"We can positively disrupt a trade show by hosting a Guinness World Record event. Or we can come into a retail environment and disrupt a space by doing something no one is doing.\"", "podcast_length": "44:52"}, {"id": "b964c309-3a01-47f5-bb1e-412642083e64", "episode_id": "63988d85-0936-491f-88a4-391fe15cb920", "cms_item_id": "68225dfc7bb476527f8c4843", "chunk_index": 8, "content": "Cole Heilborn (22:38): That's the entire day,\n\nTodd Bischoff (22:41): And they may not get it. There was people that we had to turn down after standing there for that long, and people literally got the Gerber logo tattooed onto them. I mean, we had a contact sheet of 13 different designs that they could choose from one of those being the Gerber logo. And two people ended up getting that on. And that's two people out of hundreds of thousands of people attending that show. But those two people are going to have that logo on their body forever, ever probably. And they're going to remember, they're going to think back at that event that one day that they were in the Gerber booth and they got that done. And so it's not necessarily trying to appeal to everyone, but it's those moments that quality over quantity, those two people, that means something. And that's cool.\n\nCole Heilborn (23:32): Yeah. So you said the key to, I don't want to say unlocking, but building this brand loyalty and this brand enthusiasm has been through understanding who your customers are. What internal changes or mindset changes did you guys have to go through to start thinking about who your customer was?", "token_estimate": 298, "speakers": ["Cole Heilborn", "Todd Bischoff"], "start_timestamp": "22:38", "end_timestamp": "23:32", "podcast_index": 30, "episode_name": "Ep 30: Todd Bischoff | Positively Disrupt | Gerber Gea‪r‬", "slug": "ep-30-todd-bischoff-positively-disrupt-gerber-gear", "web_url": "https://www.portsidepro.com/podcast-feed/ep-30-todd-bischoff-positively-disrupt-gerber-gear", "guest_name": "Todd Bischoff", "guest_title": "Global Creative Director", "categories": [], "short_description": "\"We can positively disrupt a trade show by hosting a Guinness World Record event. Or we can come into a retail environment and disrupt a space by doing something no one is doing.\"", "podcast_length": "44:52"}, {"id": "d49d89e0-4337-4f8a-9bfc-eed8f693d69b", "episode_id": "63988d85-0936-491f-88a4-391fe15cb920", "cms_item_id": "68225dfc7bb476527f8c4843", "chunk_index": 9, "content": "Todd Bischoff (23:53): Yeah, so that's a good question. It is tough because we say we have the burden abroad. We don't just make knives. We don't just make multi-tool. We have a whole spectrum of tools and gear that we make, and it covers across many different activities from hunting to fishing, to foraging to camping, backpacking, everyday carry to military, tactical. I mean, it's hard to just mean something to everyone. And so we really wanted to take a step back and just go back to our foundation and who we are and what we stand for, and truly the outdoor industry where our heart and soul is. And over the years, it's the military side of things and the contracts during times of war, that impacts our business because those products excel and those orders come in and those sales go up. And so there's always this shift in depending on what's happening in the world, and as we're in a pandemic right now, it's like people are buying tools and knives, and there's this fear out there that they need this stuff before it disappears. (25:16): And so we struggled or are we a military tactical brand or are we a camping and hiking brand? And so there was always this battle and it came down to just a lot of research and development. And just from a marketing side, it's easy to talk to yourself. We sit around in a room like all of us creatives and everything, and we toss out all these ideas, and at the end of the day, it's like, are we talking to ourselves or are we talking to the consumer? And to go a step deeper, it's like we shouldn't be talking at them. We should be talking with them. We should talk to them as if they're our buddies sitting in that bar stool next to us, sharing a pint, talking about the deer they missed or the fish that broke off the line. So we did a lot. We took our time and conducted a lot of consumer research studies and interviewed consumers and just collected a lot of data and a lot of facts and just to kind of support how we needed to go back to our foundation, our roots of where we came from.\n\nCole Heilborn (26:31): So now how do you describe yourself", "token_estimate": 526, "speakers": ["Todd Bischoff", "Cole Heilborn"], "start_timestamp": "23:53", "end_timestamp": "26:31", "podcast_index": 30, "episode_name": "Ep 30: Todd Bischoff | Positively Disrupt | Gerber Gea‪r‬", "slug": "ep-30-todd-bischoff-positively-disrupt-gerber-gear", "web_url": "https://www.portsidepro.com/podcast-feed/ep-30-todd-bischoff-positively-disrupt-gerber-gear", "guest_name": "Todd Bischoff", "guest_title": "Global Creative Director", "categories": [], "short_description": "\"We can positively disrupt a trade show by hosting a Guinness World Record event. Or we can come into a retail environment and disrupt a space by doing something no one is doing.\"", "podcast_length": "44:52"}, {"id": "494347cc-698a-4b46-9a4e-5552f568d406", "episode_id": "63988d85-0936-491f-88a4-391fe15cb920", "cms_item_id": "68225dfc7bb476527f8c4843", "chunk_index": 10, "content": "Todd Bischoff (26:35): Now? Honestly, our focus is again, coming from the outdoor aspect of it. And truly, we're a hunting brand. We're a fishing brand. We just launched this huge line of fishing products. When you think about people that there's a lot of conversations and opinions around hunters and anglers and is it catch and release or are you the ethics? Are you just out there to get something to mount on your wall? There's more to it that, yeah, we can't make everybody happy. We're not going to try and be everything. But what we truly believe in and what we want to support is that hunting's hard. Fishing's hard forging is hard, but what's meaningful is that you're outside. You're getting connected to nature. (27:34): You're out there providing for yourself and your friends and family, for somebody, especially coming out of a pandemic where you have to wait in line to get into the grocery store, and you get in there and the shelves are empty and you get back home and it's like you panic a little bit versus you look at the person that hunts every year and has that freezer stocked full of meat in their garage. I don't think they were panicking too much. There's a lot more meaning behind saying, Hey, I went out and I harvested that elk or that deer provided a freezer full of food for my family versus saying, I drove to the grocery store, purchased that meat, not sure where it came from, and came home and cooked it. And so again, it's that story. It's that adventure. It's that nine out of 10 times that hunt ends up in a failure, but they keep going back out there and there's this energy or this call to do that. And we want to be a part of that, and we want to support those people with the products they need to help them hopefully come home successful.\n\nCole Heilborn (28:52): Well, that's a whole nother podcast topic, like hunter ethics and all of that. But I mean, I think it seems more respectful to the animal to go out and harvest it yourself versus buying it from some supermarket where it wasn't free range or out in the woods,", "token_estimate": 516, "speakers": ["Todd Bischoff", "Cole Heilborn"], "start_timestamp": "26:35", "end_timestamp": "28:52", "podcast_index": 30, "episode_name": "Ep 30: Todd Bischoff | Positively Disrupt | Gerber Gea‪r‬", "slug": "ep-30-todd-bischoff-positively-disrupt-gerber-gear", "web_url": "https://www.portsidepro.com/podcast-feed/ep-30-todd-bischoff-positively-disrupt-gerber-gear", "guest_name": "Todd Bischoff", "guest_title": "Global Creative Director", "categories": [], "short_description": "\"We can positively disrupt a trade show by hosting a Guinness World Record event. Or we can come into a retail environment and disrupt a space by doing something no one is doing.\"", "podcast_length": "44:52"}, {"id": "96401e3a-735f-4be7-b94d-f50d5b365084", "episode_id": "63988d85-0936-491f-88a4-391fe15cb920", "cms_item_id": "68225dfc7bb476527f8c4843", "chunk_index": 11, "content": "Todd Bischoff (29:11): Or even just living here in the Pacific Northwest, the forging opportunities. I mean, going out the mushroom seasons and everything that you can forge here, it's awesome. I mean, to be able to walk out and say, I collected all these mushrooms today and brought 'em home and cooked them, versus going to the store and buying them is very easy and convenient, but it's fulfilling.\n\nCole Heilborn (29:35): Yeah, no, I totally hear you. It makes sense. You say you use the phrase positively disrupt when you're looking for, I guess your next disrupting opportunities. How do you guys think about how we're going to disrupt? I don't know if that makes sense.", "token_estimate": 169, "speakers": ["Todd Bischoff", "Cole Heilborn"], "start_timestamp": "29:11", "end_timestamp": "29:35", "podcast_index": 30, "episode_name": "Ep 30: Todd Bischoff | Positively Disrupt | Gerber Gea‪r‬", "slug": "ep-30-todd-bischoff-positively-disrupt-gerber-gear", "web_url": "https://www.portsidepro.com/podcast-feed/ep-30-todd-bischoff-positively-disrupt-gerber-gear", "guest_name": "Todd Bischoff", "guest_title": "Global Creative Director", "categories": [], "short_description": "\"We can positively disrupt a trade show by hosting a Guinness World Record event. Or we can come into a retail environment and disrupt a space by doing something no one is doing.\"", "podcast_length": "44:52"}, {"id": "ae8bac25-f385-428f-a3b0-11209842e8df", "episode_id": "63988d85-0936-491f-88a4-391fe15cb920", "cms_item_id": "68225dfc7bb476527f8c4843", "chunk_index": 12, "content": "Todd Bischoff (29:58): Yeah, I mean don't, there's not really an equation that we follow to disrupt something, but I think it just depends on what it is. I mean, for example, two years ago we launched our entire fishing line of products. And when you walk through any retailer, say Cabela's, whatever it may be, you walk through those aisles and all you see is Ziploc, baggies, clam shells, plastic, everything. And when we were bringing this product line to life, we knew we wanted to enter this space. We weren't the first people to enter this space. So you got to think about, okay, are we just showing up? Are we coming in just guns blazing and just out of control, or are we coming in with meaning and purpose and then doing so how can you sort of disrupt that space? How do you break through the threshold of the aisles and aisles of plastic and baggies and plastic in general is just a big topic, and especially from an environmental standpoint and what's happening and cleanup efforts in the oceans and waterways and stuff. And so one night I woke up just with this, I had this dream of out in the river fly fishing and a piece of our packaging floating past us, and I was like, okay, we got to eliminate plastic from our packaging. And from that moment on, that's how we were going to positively disrupt that space and introduce this product line. It's like we were going to, in what people are comfortable with and are used to seeing within the fishing category of all that plastic, we were going to come into that space with no plastic. (31:59): And for us having knives, that's a big deal. I mean, having a completely exposed knife blade at retail, nobody has done that. (32:11): And if you look at our fishing line of products that you go to any retailer and see that product on the shelves and pegged, it's everything from knives to pliers to whatever tool it is in the fishing category. There's no plastic. And so you can touch every aspect of that product and experience the grips, the textures, the cold hard steel, the filet knives. I mean, it was exciting. I mean, it sent ripples out there. Our legal team was definitely a little nervous. Retailers were a little nervous, but at the end of the day, it's like what? I mean, we want to make sure that everything we're doing has meaning and purpose. And yes, it's the product. We're out there promoting new products, but it's also packaging is a big part of the product, and they're selling features and information on the packaging, but also it's the one thing that the consumer is going to just, they don't keep the packaging. (33:22): They're not buying an Apple computer and afraid to let go of that box. This is what people are used to seeing in a clamshell or a blister or a baggie. And it's like they're not going to keep that. And so we wanted to make sure that the packaging that supported this new innovative line of fishing products truly resonated with that consumer from an environmental standpoint as we want to make sure that we're helping to support those waterways and the environment just as much as we want to see you out there in that environment. So yeah, in a sense there, it's like we can positively disrupt a trade show by hosting against Booker World Records event, or we can come into a retail environment and disrupt a space by doing something that nobody else has done before.", "token_estimate": 843, "speakers": ["Todd Bischoff"], "start_timestamp": "29:58", "end_timestamp": "29:58", "podcast_index": 30, "episode_name": "Ep 30: Todd Bischoff | Positively Disrupt | Gerber Gea‪r‬", "slug": "ep-30-todd-bischoff-positively-disrupt-gerber-gear", "web_url": "https://www.portsidepro.com/podcast-feed/ep-30-todd-bischoff-positively-disrupt-gerber-gear", "guest_name": "Todd Bischoff", "guest_title": "Global Creative Director", "categories": [], "short_description": "\"We can positively disrupt a trade show by hosting a Guinness World Record event. Or we can come into a retail environment and disrupt a space by doing something no one is doing.\"", "podcast_length": "44:52"}, {"id": "23a27854-4cb6-46f7-9415-22d9a1c0d536", "episode_id": "63988d85-0936-491f-88a4-391fe15cb920", "cms_item_id": "68225dfc7bb476527f8c4843", "chunk_index": 13, "content": "Cole Heilborn (34:10): So you can do it on the large scale, you can do it on the small scale, you can do it in between. It doesn't have to be huge. It's just doing something different is what it sounds like.\n\nTodd Bischoff (34:20): And a lot of times it can be overthought too. I think a lot of people come in and that's why we call it positively disrupt. A lot of people just come in and fucking disrupt the space, and it's bad. And you got to be careful with it. And I think that all comes down too, to just knowing and understanding the consumer or the audience that you're talking with.\n\nCole Heilborn (34:43): Yeah, no, well said. So what's the future of Gerber look like? Is there going to be another 180 switch in its future? Are you going to go back to advertising or, I don't know, jump into something else?", "token_estimate": 204, "speakers": ["Cole Heilborn", "Todd Bischoff"], "start_timestamp": "34:10", "end_timestamp": "34:43", "podcast_index": 30, "episode_name": "Ep 30: Todd Bischoff | Positively Disrupt | Gerber Gea‪r‬", "slug": "ep-30-todd-bischoff-positively-disrupt-gerber-gear", "web_url": "https://www.portsidepro.com/podcast-feed/ep-30-todd-bischoff-positively-disrupt-gerber-gear", "guest_name": "Todd Bischoff", "guest_title": "Global Creative Director", "categories": [], "short_description": "\"We can positively disrupt a trade show by hosting a Guinness World Record event. Or we can come into a retail environment and disrupt a space by doing something no one is doing.\"", "podcast_length": "44:52"}, {"id": "cd6ccec8-f4cd-466f-8bef-c5014c438b56", "episode_id": "63988d85-0936-491f-88a4-391fe15cb920", "cms_item_id": "68225dfc7bb476527f8c4843", "chunk_index": 14, "content": "Todd Bischoff (34:54): I joke around with them because just my history of coming from the apparel industry, I joke around every day that I'm going to turn it into an apparel company. But no, we're always after maintaining that leadership position in the industry and making sure that we're staying ahead of trends and consumer insights. And so right now it's really just, it's not so much coming out with all this new stuff, but it's really going back to, again, Gerber became well-known for their custom quality gifted knife sets that people wanted and inspired to have. And so truly, the product lines that have been coming out over the last couple of years are just, I mean, the quality for the price is nothing that we've ever done before. And so we have all this momentum with the brand and building this culture and the abilities to engage at a deeper level with our consumers. (36:01): And now the product line is matching that too. We're not the most expensive product out there. We're not the least expensive. We're within reach. And so we get a lot of like, oh, that's cheap and made overseas, or Why can't you make more? If that was made in the US I would purchase that. And it's like we are always going to have those consumers that are either unhappy with the price or where it came from, but at the end of the day, it's we're trying to just make sure that we're producing, we're not fixing something that Snap broke. It's that quality over quantity. Making sure that within our price range that we're providing the best quality materials. And if that can be done in the us, awesome, we're going to do that. But if it can be done better and overseas, then we're going to do that because that's what's best for that product versus trying to let one or the other dictate what that needs to be. And so, yeah, I mean, super excited about the product line. We have a lot of, again, about half our products are us made, and so just trying to maintain that balance of supporting local industries as well as being able to, some things you just get better overseas than you can here. So yeah, so I think just from the next steps for us, it is really just connecting with those outside hunters, anglers, forgers, as well as just bringing to market the best quality products that we can for those activities.", "token_estimate": 578, "speakers": ["Todd Bischoff"], "start_timestamp": "34:54", "end_timestamp": "34:54", "podcast_index": 30, "episode_name": "Ep 30: Todd Bischoff | Positively Disrupt | Gerber Gea‪r‬", "slug": "ep-30-todd-bischoff-positively-disrupt-gerber-gear", "web_url": "https://www.portsidepro.com/podcast-feed/ep-30-todd-bischoff-positively-disrupt-gerber-gear", "guest_name": "Todd Bischoff", "guest_title": "Global Creative Director", "categories": [], "short_description": "\"We can positively disrupt a trade show by hosting a Guinness World Record event. Or we can come into a retail environment and disrupt a space by doing something no one is doing.\"", "podcast_length": "44:52"}, {"id": "8eca0b09-7d85-4132-8ff5-0671ee6780e6", "episode_id": "63988d85-0936-491f-88a4-391fe15cb920", "cms_item_id": "68225dfc7bb476527f8c4843", "chunk_index": 15, "content": "Cole Heilborn (37:33): Yeah. Great. Well, I'm excited to see what's next for you guys. If outdoor retailer happens next year, everyone should probably swing by your booth to see what the next big thing is.\n\nTodd Bischoff (37:44): Yeah, no, it's interesting. I mean, we had all this excitement around activities and happy hour events, and now with everything COVID, it's going to be, I'm really excited to see what happens with the trade shows and events and how those evolve and what comes out of that.\n\nCole Heilborn (38:04): Yeah, well, it just gives you guys more time to prepare for the next Guinness World record, right?\n\nTodd Bischoff (38:08): Exactly. Awesome. Maybe we'll just do a road show, Guinness Book World Records.\n\nCole Heilborn (38:13): There you go. I like it. Well, Todd, thanks so much. We're out of time for today, but if people want to follow along with you or the company, where can they tune in?\n\nTodd Bischoff (38:23): Yeah, so don't follow me. You're just going to get dog picks and kiddo picks. But yeah, Gerber gear, you can follow us on Instagram, Facebook. But yeah, follow along gerber gear.com\n\nCole Heilborn (38:42): Or just listen for the largest cheering crowd and go that\n\nTodd Bischoff (38:45): Direction. Or just listen for the Eagle squalling, or people chanting or confetti cannons going off.\n\nCole Heilborn (38:54): Awesome. Well, Todd, thanks so much. Have a good rest of your day, and thanks for joining us.\n\nTodd Bischoff (38:59): Alright, thanks man.\n\nCole Heilborn (39:00): Take care. Thank you for listening to this episode of the Backcountry Marketing Podcast. If you enjoyed today's episode or learned something new, please consider leaving us a review on Apple or sharing this with a friend.", "token_estimate": 436, "speakers": ["Cole Heilborn", "Todd Bischoff"], "start_timestamp": "37:33", "end_timestamp": "39:00", "podcast_index": 30, "episode_name": "Ep 30: Todd Bischoff | Positively Disrupt | Gerber Gea‪r‬", "slug": "ep-30-todd-bischoff-positively-disrupt-gerber-gear", "web_url": "https://www.portsidepro.com/podcast-feed/ep-30-todd-bischoff-positively-disrupt-gerber-gear", "guest_name": "Todd Bischoff", "guest_title": "Global Creative Director", "categories": [], "short_description": "\"We can positively disrupt a trade show by hosting a Guinness World Record event. Or we can come into a retail environment and disrupt a space by doing something no one is doing.\"", "podcast_length": "44:52"}, {"id": "ae0df1be-61e0-4034-8fa8-add19b0ec23e", "episode_id": "9ee7e03d-6aec-4f8b-b0e5-ff1259bad24b", "cms_item_id": "68225dfc7bb476527f8c4844", "chunk_index": 0, "content": "Cole Heilborn (00:02): Welcome to the Backcountry Marketing Podcast. My name is Cole Helebo and I'll be your host today. This podcast dives deep with leaders of the outdoor marketing industry as they discuss the gritty details of their work, personal challenges and latest adventures, whether you're standing in the lift line, shuttling the fresh loam, or cracking a local beer. I hope you enjoyed today's episode. This is the Backcountry Marketing Podcast. This episode is produced by Porch Line Productions, an outdoor, commercial and film production company based in the Pacific Northwest. Let's make waves. Welcome to the Backcountry Marketing Podcast. Today I'm sitting down with Eric Porter. He's a professional mountain biker. He rides for a number of different brands, I think most prominently, maybe not most prominently, but Diamondback is one of your big supporters. Eric, how are you?\n\nEric Porter (00:52): I'm doing awesome. Yeah, thanks for having me on.\n\nCole Heilborn (00:55): Thank you. Thanks for joining us. You're calling in from Utah today?\n\nEric Porter (00:59): Yep, I'm in the Park City area of Utah.\n\nCole Heilborn (01:01): Okay, right on. Quick shout out before we jump in. Jill over at Alta Cycling for connecting us. She was on episode 14 and she connected us and a couple months later we're finally sitting down and recording.\n\nEric Porter (01:15): Yeah, she's awesome. She's been great to work with.\n\nCole Heilborn (01:18): Yeah, she was a lot of fun to chat with and dive into branding and how to manage brands. For those of you that haven't listened to that episode, she works at Alta Cycling. They manage five different brands. Diamond Back is one of them, and she dove deep into how she is. A small team manages five different brands, so if you're interested, go check it out. But Eric, tell us a little bit about yourself. What's stay in the life of a professional mountain bike athlete look like?", "token_estimate": 483, "speakers": ["Cole Heilborn", "Eric Porter"], "start_timestamp": "00:02", "end_timestamp": "01:18", "podcast_index": 31, "episode_name": "Ep 31: Eric Porter | Ride On | Porter MT‪B‬", "slug": "ep-31-eric-porter-ride-on-porter-mtb", "web_url": "https://www.portsidepro.com/podcast-feed/ep-31-eric-porter-ride-on-porter-mtb", "guest_name": "Eric Porter", "guest_title": "YouTuber", "categories": [], "short_description": "\"When you find a sport that you love and you're able to go do it and get out of the real world and go ride a bike. It's the best feeling ever.\"", "podcast_length": "44:53"}, {"id": "8ecd37b0-4c51-486e-bf5d-6c6436889671", "episode_id": "9ee7e03d-6aec-4f8b-b0e5-ff1259bad24b", "cms_item_id": "68225dfc7bb476527f8c4844", "chunk_index": 1, "content": "Eric Porter (01:46): It's all over the place. It's same as what it's always been, but different like everybody. So I have a lot of aspects to my job. The main one is being to be in magazines and videos and TV shows, all that sort of thing. So I'm getting exposure for the brands that sponsor me and that I work with. And it's typically more than just a sponsorship. I usually do a lot more with those brands as well, and that's something that I look at as a value add as an athlete. So I also help with product development. I also help with PR things and just really try to be able to do whatever the brands need me to do to better support the selling products. Basically, that's what makes this all happen. They're not just sponsoring me because I'm good at riding bikes, which is something that everybody thinks when you're getting into it. I want to be sponsored because I'm good and because I want free stuff. But the bottom line is that my job is to help them get their name out there and create a good image around their brand and in the end sell products because if bikes aren't selling, then I don't have a job.\n\nCole Heilborn (03:02): Right. Yeah. So tell us a little bit about your background as an athlete. What has that journey looked like?\n\nEric Porter (03:10): Yeah, it was kind of a interesting one. I grew up in Louisville, Kentucky, which is not known for producing professional mountain bikers.\n\nCole Heilborn (03:17): You guys make bats?\n\nEric Porter (03:19): Yeah, Louisville sluggers right there, and I was just lucky enough to have trails that I could ride from my house. So when I was 12 and it was time to get kind of a big kid bike or an adult bike or whatever, we went to Kmart and got what we could afford, which was probably a hundred dollars mountain bike. And I just started exploring the neighborhood and then beyond, which took me to Trails, and then I got a mountain bike magazine and found out that there's a whole sport about this. And then my first job was at a bike shop going into college. I was on the mountain bike team, which was, I was the only kid in high school that mountain biked or snowboarded.\n\nCole Heilborn (04:01): Oh, wow.", "token_estimate": 544, "speakers": ["Eric Porter", "Cole Heilborn"], "start_timestamp": "01:46", "end_timestamp": "04:01", "podcast_index": 31, "episode_name": "Ep 31: Eric Porter | Ride On | Porter MT‪B‬", "slug": "ep-31-eric-porter-ride-on-porter-mtb", "web_url": "https://www.portsidepro.com/podcast-feed/ep-31-eric-porter-ride-on-porter-mtb", "guest_name": "Eric Porter", "guest_title": "YouTuber", "categories": [], "short_description": "\"When you find a sport that you love and you're able to go do it and get out of the real world and go ride a bike. It's the best feeling ever.\"", "podcast_length": "44:53"}, {"id": "f6ba741c-ea45-433f-aa0f-8b88e15165a6", "episode_id": "9ee7e03d-6aec-4f8b-b0e5-ff1259bad24b", "cms_item_id": "68225dfc7bb476527f8c4844", "chunk_index": 2, "content": "Eric Porter (04:02): Yeah, so I was definitely not doing the cool thing, which awesome. It's awesome. That is now. So then going into college, there was a mountain bike team there at Western Kentucky University, and so I started racing Collegiate, did well with that, raced the Novas, and I was trying to make it as a downhill racer, but the whole time while I was trying to race downhill, I was dirt jumping and riding street and doing all kinds of fun stuff on the side when I probably should have been training, but I was having fun and doing what I wanted to do. And eventually that ended up being kind of a movement in mountain biking, which was street riding and dirt jumping, and I just happened to be in the right place at the right time (04:51): And surrounded myself with the right people through racing with Aaron Chase and Jeff Linsky and Kyle Abbott and those guys who were kind of pioneering that and fell into filming with them, which ended up leading to a magazine cover. It was, I mean, everything's connected. So the guy that shot my first cover for it was Flow Magazine was the best slalom racer in the Midwest, Scott Hart. So anyway, and at that time that was actually grinding a handrail on a mountain bike without pegs, which no one had done before. And it was just something that made sense to me and it worked out. So that got me my first Joel Smith, who's another industry legend and used to run a magazine and his dad's Malcolm Smith, legendary Moto guy that cover produced my first, he gave me just a cold call, Hey, I'm the Manitou guy, you have a fork sponsor. And of course I had nothing. So yeah, one thing led to another there, which slopestyle started at the same time. So the first crank works, I did really well on that and all of the dirt jumping slopestyle contests, and within a year I had a job riding my bike.\n\nCole Heilborn (06:08): Wow. So how did you go from dirt riding, dirt jumping wasn't really a thing to then competing in slopestyle and a year later having brand sponsorship. How did that happen so quickly?", "token_estimate": 514, "speakers": ["Eric Porter", "Cole Heilborn"], "start_timestamp": "04:02", "end_timestamp": "06:08", "podcast_index": 31, "episode_name": "Ep 31: Eric Porter | Ride On | Porter MT‪B‬", "slug": "ep-31-eric-porter-ride-on-porter-mtb", "web_url": "https://www.portsidepro.com/podcast-feed/ep-31-eric-porter-ride-on-porter-mtb", "guest_name": "Eric Porter", "guest_title": "YouTuber", "categories": [], "short_description": "\"When you find a sport that you love and you're able to go do it and get out of the real world and go ride a bike. It's the best feeling ever.\"", "podcast_length": "44:53"}, {"id": "f9f57976-13af-4cd6-90e2-7719e07e052f", "episode_id": "9ee7e03d-6aec-4f8b-b0e5-ff1259bad24b", "cms_item_id": "68225dfc7bb476527f8c4844", "chunk_index": 3, "content": "Eric Porter (06:24): I think it was just, I'm not really sure. I mean, it was something that was happening in mountain biking, so the media was looking to cover that, (06:36): What was going on, and I was one of the names that was doing things and I was pushing the boundaries there with what you could do on a bike. And we were kind of doing BMX tricks on a mountain bike and originally on streets, and then we started doing that in the mountains, building cool features on trees and dirt and everything as well. And then the industry really got behind it because they wanted to be a part of it. And so that's when slopestyle, they realized that that was such a great way to showcase what people could do on bikes and get a crowd. It's not always easy to get a large crowd for a race because you can only see 'em cross the finish line at the end, whereas this is a full on spectator sport, and Whistler has thousands and thousands of people crowded around the base area watching a slope style contest. So it's a really spectator friendly sport as well. Yeah. So that was from then for the next eight years, that was my primary job, was competing in slopestyle. So there ended up being kind of the world tour of stops all around in Europe and everywhere else, and then in between the contests we were filming video parts and yeah, it was really cool.\n\nCole Heilborn (07:53): What type of progression did you see in the writing and Slope style over those few years? I feel like you go to a Crank Works now and you watch the Joy Ride event and it's nothing like what it was. It's progressed so much, the rider have changed so much.", "token_estimate": 408, "speakers": ["Eric Porter", "Cole Heilborn"], "start_timestamp": "06:24", "end_timestamp": "07:53", "podcast_index": 31, "episode_name": "Ep 31: Eric Porter | Ride On | Porter MT‪B‬", "slug": "ep-31-eric-porter-ride-on-porter-mtb", "web_url": "https://www.portsidepro.com/podcast-feed/ep-31-eric-porter-ride-on-porter-mtb", "guest_name": "Eric Porter", "guest_title": "YouTuber", "categories": [], "short_description": "\"When you find a sport that you love and you're able to go do it and get out of the real world and go ride a bike. It's the best feeling ever.\"", "podcast_length": "44:53"}, {"id": "dbf6560f-c049-4b2e-b11a-1cd03b8b3046", "episode_id": "9ee7e03d-6aec-4f8b-b0e5-ff1259bad24b", "cms_item_id": "68225dfc7bb476527f8c4844", "chunk_index": 4, "content": "Eric Porter (08:08): Yeah, I would say it's kind of as crazy as it's ever been because every year there's new tricks that have never been done in a contest before, and that's the way that it was then too. So it was even the very first year back flipping a 30 foot jump was not a normal thing. (08:28): And that was my first crank works. I got second place, it was called Joy Ride that first year, and it was because I was, for whatever reason, it made sense to me that I could back flip this big jump. It was, and then it kind of went through this phase where they were trying to see how big they could make things go. So the features just got bigger and bigger, and then there's 20 something foot vertical drops and there's 60 foot gaps, and they wanted to see how big the sport could go. And then now they've kind of reeled it in and arguably made it quite a bit safer. I think there's less injuries and better success rate of runs and it's better than it's ever been, and it's still really big, but it's actually made safer and not trying to push the limits of what the riders can do as far as the biggest thing ever, but make it look good as well.\n\nCole Heilborn (09:28): Sure.\n\nEric Porter (09:30): Yeah. Same thing with Rampage where it's like, it's always been as crazy as it is. It just keeps getting crazier and the level keeps coming up as well.\n\nCole Heilborn (09:40): Right. Yeah, that makes sense. Okay, interesting. So you competed for a long time. You've done a little bit of a transition though, and I'm curious to kind of dive into that transition from Pro Rider to being a dad to now making YouTube videos. Can you walk us through, I guess maybe the last few legs of your journey?", "token_estimate": 425, "speakers": ["Eric Porter", "Cole Heilborn"], "start_timestamp": "08:08", "end_timestamp": "09:40", "podcast_index": 31, "episode_name": "Ep 31: Eric Porter | Ride On | Porter MT‪B‬", "slug": "ep-31-eric-porter-ride-on-porter-mtb", "web_url": "https://www.portsidepro.com/podcast-feed/ep-31-eric-porter-ride-on-porter-mtb", "guest_name": "Eric Porter", "guest_title": "YouTuber", "categories": [], "short_description": "\"When you find a sport that you love and you're able to go do it and get out of the real world and go ride a bike. It's the best feeling ever.\"", "podcast_length": "44:53"}, {"id": "192ac254-3d1e-42c9-a3e7-f8b7f8bb06ac", "episode_id": "9ee7e03d-6aec-4f8b-b0e5-ff1259bad24b", "cms_item_id": "68225dfc7bb476527f8c4844", "chunk_index": 5, "content": "Eric Porter (10:02): Yeah, so 2010 was when the oh eight financial crisis was really kind of hitting the hardest. I think 10 11 was kind of the low point, and so I got dropped from Harrow at that point who had been on for four years. They just cut the whole team and the sky was falling everywhere. And so I looked at it as an opportunity to rebrand what I do. So I still looked at it as I'm a professional mountain biker, but instead of my job being that I compete in contests and try to push the sport with crazy tricks filming as well, what I would do is do more backcountry trips and camping and fishing and tie all these other elements in that I love and that are what make mountain biking special to me because I grew up racing cross country and riding just mountain bike\n\nSpeaker 3 (10:55): Trails.\n\nEric Porter (10:56): And so I wanted to pull that in because the more I thought about it as well, what you're doing in a contest setting is a spectator sport and it's really cool, but it's completely unattainable to anybody else. So my idea was that I would shoot videos and kind of tell the stories of adventures that are something that people can actually aspire to and think, well, I can do that. Maybe it's not going to be at the level that he's doing it at, or as remote of a location or as many miles, but I wanted to put that out there, kind of the vibe of this is a fun sport that you can do and turns out that actually supports more bike sales anyway. So my job as an athlete is still the same. It's just a little bit different in terms of how I'm portraying it to the media and to the public.\n\nCole Heilborn (11:53): Okay, gotcha. And when did you start working with Diamondback?\n\nEric Porter (11:57): So 2011. So I've been with them for 10 years now.\n\nCole Heilborn (12:00): Oh, wow.", "token_estimate": 451, "speakers": ["Eric Porter", "Speaker 3", "Cole Heilborn"], "start_timestamp": "10:02", "end_timestamp": "12:00", "podcast_index": 31, "episode_name": "Ep 31: Eric Porter | Ride On | Porter MT‪B‬", "slug": "ep-31-eric-porter-ride-on-porter-mtb", "web_url": "https://www.portsidepro.com/podcast-feed/ep-31-eric-porter-ride-on-porter-mtb", "guest_name": "Eric Porter", "guest_title": "YouTuber", "categories": [], "short_description": "\"When you find a sport that you love and you're able to go do it and get out of the real world and go ride a bike. It's the best feeling ever.\"", "podcast_length": "44:53"}]
